  depends_on = [aws_cloudwatch_log_resource_policy.route53-query-logging-policy]

  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id                  = aws_route53_zone.primary.zone_id
}

LLM Output #0:
 Description:
This Terraform configuration will create an Amazon Route 53 zone named "primary", a CloudWatch Log Group named "aws_route53_example_com", a CloudWatch Log Resource Policy named "route53-query-logging-policy", and set up logging for Route 53 query events.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  log_group_name = "aws_route53_example_com"
  log_resource_policy_name = "route53-query-logging-policy"
}

resource "aws_route53_zone" "primary" {
  name = "primary"
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = local.log_group_name
  retention_in_days = 14
}

resource "aws_iam_role" "log_role" {
  name = "route53_query_logging_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_cloudwatch_log_group_policy_attachment" "log_group_attachment" {
  name          = "route53-query-logging-policy"
  log_group_name = aws_cloudwatch_log_group.log_group.name
  policy_arn    = aws_iam_policy.log_policy.arn
}

resource "aws_iam_policy" "log_policy" {
  name        = local.log_resource_policy_name
  description = "Policy for Route 53 query logging"

  path        = "/"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*:*:*:*:*:*"
      }
    ]
  })
}

resource "aws_route53_zone_logging_configuration" "logging_config" {
  zone_id = aws_route53_zone.primary.id

  cloudwatch_log_group_arn = aws_cloudwatch_log_group.log_group.arn
  cloudwatch_log_stream_prefix = "route53-query-logs"
  log_file_name_enabled = true
  log_file_names_format = "route53-query-logs-{yyyy-MM-dd}.log"
  log_filter_query = "queryType=RECURSIVE_QUERY"

  role_arn = aws_iam_role.log_role.arn
}
```

This configuration creates an Amazon Route 53 zone named "primary", a CloudWatch Log Group named "aws_route53_example_com", a CloudWatch Log Resource Policy named "route53-query-logging-policy", and sets up logging for Route 53 query events using the specified log group and log resource policy. The configuration also creates an IAM role for Route 53 to assume when logging events. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

