This Terraform configuration will create a Route 53 hosted zone named "primary" and an Elastic Load Balancer (ELB) named "main". The ELB will be associated with the Route 53 record.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "zone_name" {
  default = "primary"
}

variable "elb_name" {
  default = "main"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count = 3
  cidr_block = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  vpc_id     = aws_vpc.example.id
}

resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id
}

resource "aws_route_table" "example" {
  vpc_id = aws_vpc.example.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.example.id
  }
}

resource "aws_route_table_association" "example" {
  count = 3
  subnet_id      = aws_subnet.example[count.index].id
  route_table_id = aws_route_table.example.id
}

resource "aws_security_group" "example" {
  name        = "allow_all_inbound_traffic"
  description = "Allow all inbound traffic"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elb" "example" {
  name            = var.elb_name
  security_groups = [aws_security_group.example.id]
  subnets         = aws_subnet.example.*.id

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }
}

resource "aws_route53_zone" "example" {
  name = var.zone_name
}

resource "aws_route53_record" "example" {
  zone_id = aws_route53_zone.example.zone_id
  name    = "${aws_elb.example.dns_name}"
  type    = "A"
  ttl     = "300"
  records = [aws_elb.example.id]
}
```

This configuration creates a VPC, subnets, an internet gateway, a route table, route table associations, a security group, an Elastic Load Balancer, a Route 53 zone, and a Route 53 record. The Elastic Load Balancer is associated with the Route 53 record. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

