 Description:
This Terraform configuration will set up a weighted routing policy using Amazon Route 53 to distribute traffic between a primary database instance in `us-west-1` and three replica database instances in `us-east-1`, `eu-central-1`, and `ap-southeast-1`. The zones and database instances will be named as specified.

Terraform HCL:

```hcl
provider "aws" {
  alias  = "main"
  region = "us-west-1"
}

provider "aws" {
  alias  = "us-east"
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-central"
  region = "eu-central-1"
}

provider "aws" {
  alias  = "ap-southeast"
  region = "ap-southeast-1"
}

variable "primary_db_instance_id" {
  description = "ID of the primary database instance"
  default     = ""
}

variable "replica_us_east_db_instance_id" {
  description = "ID of the replica database instance in us-east-1"
  default     = ""
}

variable "replica_eu_central_db_instance_id" {
  description = "ID of the replica database instance in eu-central-1"
  default     = ""
}

variable "replica_ap_southeast_db_instance_id" {
  description = "ID of the replica database instance in ap-southeast-1"
  default     = ""
}

resource "aws_route53_zone" "main" {
  provider = aws.main
  name     = "main"
}

resource "aws_route53_record" "primary" {
  provider = aws.main
  zone_id  = aws_route53_zone.main.id
  name     = "primary"
  type     = "A"
  alias {
    name                   = aws_db_instance.primary.address
    zone_id                = aws_db_instance.primary.private_dns_hostname.id
    evaluate_target_health = true
    alias_target {
      dns_name = aws_db_instance.primary.address
      zone_id  = aws_db_instance.primary.private_dns_hostname.id
    }
  }
}

resource "aws_route53_record" "replica_us_east" {
  provider = aws.us-east
  zone_id  = aws_route53_zone.main.id
  name     = "replica_us_east"
  type     = "A"
  alias {
    name                   = aws_db_instance.replica_us_east.address
    zone_id                = aws_db_instance.replica_us_east.private_dns_hostname.id
    evaluate_target_health = true
    alias_target {
      dns_name = aws_db_instance.replica_us_east.address
      zone_id  = aws_db_instance.replica_us_east.private_dns_hostname.id
    }
  }
}

resource "aws_route53_record" "replica_eu_central" {
  provider = aws.eu-central
  zone_id  = aws_route53_zone.main.id
  name     = "replica_eu_central"
  type     = "A"
  alias {
    name                   = aws_db_instance.replica_eu_central.address
    zone_id                = aws_db_instance.replica_eu_central.private_dns_hostname.id
    evaluate_target_health = true
    alias_target {
      dns_name = aws_db_instance.replica_eu_central.address
      zone_id  = aws_db_instance.replica_eu_central.private_dns_hostname.id
    }
  }
}

resource "aws_route53_record" "replica_ap_southeast" {
  provider = aws.ap-southeast
  zone_id  = aws_route53_zone.main.id
  name     = "replica_ap_southeast"
  type     = "A"
  alias {
    name                   = aws_db_instance.replica_ap_southeast.address
    zone_id                = aws_db_instance.replica_ap_southeast.private_dns_hostname.id
    evaluate_target_health = true
    alias_target {
      dns_name = aws_db_instance.replica_ap_southeast.address
      zone_id  = aws_db_instance.replica_ap_southeast.private_dns_hostname.id
    }
  }
}

resource "aws_route53_health_check" "db_check" {
  provider = aws.main
  name     = "db_check"
  type     = "EC2"
  resource_id = aws_db_instance.primary.id
}

resource "aws_route53_weighted_record" "weighted_record" {
  provider = aws.main
  zone_id  = aws_route53_zone.main.id
  name     = "primary"
  type     = "A"

  weighted_routing_policy {
    weight_all_values {
      weight = 10
    }

    weight_all_values {
      weight = 30
      alias {
        zone_id                = aws_route53_health_check.db_check.zone_id
        dns_name               = aws_route53_health_check.db_check.fqdn
        evaluate_target_health = true
      }
    }

    weight_all_values {
      weight = 30
      aliases {
        name                   = aws_route53_record.replica_us_east.name
        zone_id                = aws_route53_record.replica_us_east.zone_id
        evaluate_target_health = true
      }
    }

    weight_all_values {
      weight = 30
      aliases {
        name                   = aws_route53_record.replica_eu_central.name
        zone_id                = aws_route53_record.replica_eu_central.zone_id
        evaluate_target_health = true
      }
    }

    weight_all_values {
      weight = 30
      aliases {
        name                   = aws_route53_record.replica_ap_southeast.name
        zone_id                = aws_route53_record.replica_ap_southeast.zone_id
        evaluate_target_health = true
      }
    }
  }
}

data "aws_db_instance" "primary" {
  provider = aws.main
  instance_id = var.primary_db_instance_id
}

data "aws_db_instance" "replica_us_east" {
  provider = aws.us-east
  instance_id = var.replica_us_east_db_instance_id
}

data "aws_db_instance" "replica_eu_central" {
  provider = aws.eu-central
  instance_id = var.replica_eu_central_db_instance_id
}

data "aws_db_instance" "replica_ap_southeast" {
  provider = aws.ap-southeast
  instance_id = var.replica_ap_southeast_db_instance_id
}
