}

variable "public_rds_endpoint" {
  default = "public-rds-endpoint.us-west-2.rds.amazonaws.com"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
}

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = [aws_subnet.private.id, aws_subnet.public.id]
}

resource "aws_iam_role" "rds_assume_role" {
  name = "rds_assume_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_route_53_zone" "private" {
  name = "private.example.com"
  vpc {
    vpc_id = aws_vpc.main.id
  }
}

resource "aws_route_53_zone" "public" {
  name = "public.example.com"
}

resource "aws_route_53_record" "private" {
  zone_id = aws_route_53_zone.private.zone_id
  name    = "@"
  type    = "A"

  alias {
    name                   = aws_rds_cluster.internal.endpoint.address
    zone_id                = aws_rds_cluster.internal.endpoint.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route_53_record" "public" {
  zone_id = aws_route_53_zone.public.zone_id
  name    = "@"
  type    = "A"

  alias {
    name                   = aws_rds_cluster.public.endpoint.address
    zone_id                = aws_rds_cluster.public.endpoint.zone_id
    evaluate_target_health = true
  }
}

resource "aws_rds_cluster" "internal" {
  cluster_identifier      = "internal"
  engine                  = "aurora-postgresql"
  master_username         = "internal_user"
  master_password         = "internal_password"
  database_name           = "internal_db"
  vpc_security_group_ids   = [aws_security_group.internal.id]
  subnet_group_name       = aws_db_subnet_group.main.name
  skip_final_snapshot     = true

  tags = {
    Name = "internal"
  }
}

resource "aws_rds_cluster" "public" {
  cluster_identifier      = "public"
  engine                  = "aurora-postgresql"
  master_username         = "public_user"
  master_password         = "public_password"
  database_name           = "public_db"
  vpc_security_group_ids   = [aws_security_group.public.id]
  subnet_group_name       = aws_db_subnet_group.main.name
  skip_final_snapshot     = true

  tags = {
    Name = "public"
  }
}

resource "aws_security_group" "internal" {
  name_prefix = "internal"
  vpc_id      = aws_vpc.main.id
}

resource "aws_security_group" "public" {
  name_prefix = "public"
  vpc_id      = aws_vpc.main.id
}
```

This configuration creates an AWS VPC, two subnets (one private and one public), an RDS subnet group, two IAM roles for RDS, two Route 53 zones (one private and one public), and two RDS clusters (one internal and one public). The private zone will route internal traffic to the internal RDS cluster, while the public zone will route external traffic to the public RDS cluster. The default values for the RDS endpoints can be replaced with your actual RDS endpoint addresses.

