 **Description:**
This Terraform configuration will create a basic Elastic Beanstalk environment with an associated Elastic Beanstalk application. The IAM role for EC2 instances will be named `eb_ec2_role`, and the instance profile will be named `eb_ec2_profile`. The Elastic Beanstalk application will be named `my_application`.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

locals {
  application_name = "my_application"
  role_name        = "eb_ec2_role"
  profile_name     = "eb_ec2_profile"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = local.profile_name
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_elastic_beanstalk_application" "my_application" {
  name = local.application_name
}

resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = "${local.application_name}-env"
  application          = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running Node.js (including App Server)"

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    name      = "VPCId"
    value     = "vpc-xxxxxxxx"
  }

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    name      = "SubnetIds"
    value     = "subnet-xxxxxxxx,subnet-yyyyyyyy"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "NODE_ENV"
    value     = "production"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "APP_PORT"
    value     = "80"
  }

  option_settings {
    namespace = "aws:elasticbeanstalk:ec2:instance"
    option_name = "InstanceProfile"
    value = jsonencode({
      Name = aws_iam_instance_profile.eb_ec2_profile.name
    })
  }
}
```

**Note:**
- Replace `vpc-xxxxxxxx` and `subnet-xxxxxxxx,subnet-yyyyyyyy` with your VPC ID and Subnet IDs, respectively.
- This configuration assumes the use of the Node.js solution stack. If you are using a different platform, you will need to adjust the `solution_stack_name` accordingly.
- The `NODE_ENV` and `APP_PORT` settings can be adjusted to suit your application's requirements.
- This configuration does not include any Elastic Beanstalk application code or versioning. You will need to provide that separately.

