 Terraform Program Description:
This Terraform program will configure Amazon Route 53 resources to manage a domain, create an S3 bucket, and set up traffic routing to an Elastic Beanstalk environment. The zone will be named "main", the Elastic Beanstalk environment will be named "eb-env", the IAM role will be named "eb_ec2_role", the instance profile will be named "eb_ec2_profile", the S3 bucket will have a unique name, the object in the bucket will be named "examplebucket_object", the Elastic Beanstalk application will be named "myapp", and the application version will be specified.

Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  unique_id = uuid()
  bucket_name = "myapp-version-${local.unique_id}"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_s3_bucket" "bucket" {
  bucket = local.bucket_name
  acl    = "private"

  tags = {
    Name        = local.bucket_name
    Environment = "eb-env"
  }
}

resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.bucket.id
  key    = "examplebucket_object"
  source = "example_object"
  etag   = filemd5("example_object")
}

resource "aws_elasticbeanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Application"
}

resource "aws_elasticbeanstalk_application_version" "version" {
  application = aws_elasticbeanstalk_application.myapp.name
  version_label = "1"

  source_bundle = {
    s3_bucket = aws_s3_bucket.bucket.id
    s3_key    = aws_s3_bucket_object.examplebucket_object.id
  }
}

resource "aws_route53_zone" "main" {
  name = "example.com"

  vpc {
    vpc_id = aws_vpc.default.id
  }
}

resource "aws_route53_record" "a" {
  zone_id = aws_route53_zone.main.id
  name    = "@"
  type    = "A"

  alias {
    name                   = aws_elasticbeanstalk_environment.eb-env.cname
    zone_id                = aws_elasticbeanstalk_environment.eb-env.zone_id
    evaluate_target_health = true
  }
}

resource "aws_elasticbeanstalk_environment" "eb-env" {
  name                = "eb-env"
  application          = aws_elasticbeanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running Node.js (including App Server)"

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "NODE_ENV"
    value     = "production"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "PORT"
    value     = "80"
  }

