    namespace = "aws:elasticbeanstalk:application:resources"
    name      = "AWS::ElasticBeanstalk::ApplicationHealthCheck"
    value     = "HTTP:80/"
  }

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.default.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc:security-group"
    name      = "CreateSecurityGroup"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc:security-group"
    name      = "SGInbound"
    value     = "HTTP:80,HTTPS:443"
  }

  setting {
    namespace = "aws:elasticbeanstalk:ec2:vpc:security-group"
    name      = "SGOutbound"
    value     = "ALL - ALL"
  }

  option_settings {
    namespace = "aws:elasticbeanstalk:application:environment"
    option_name = "AWSEB_IB_INSTANCE_PROFILE"
    value       = aws_iam_instance_profile.eb_ec2_profile.name
  }

  option_settings {
