  policy_arn = data.aws_iam_policy.eb_ec2_policy.arn
}

resource "aws_db_instance" "default" {
  engine = "postgres"
  engine_version = "13.2"
  instance_class = "db.t2.micro"
  name = local.db_instance_name
  username = "myuser"
  password = "mypassword"
  parameter_group_name = "default.postgres13"
  allocated_storage = 20
  vpc_security_group_ids = [aws_security_group.default.id]
  publicly_accessible = true
}

resource "aws_elastic_beanstalk_environment" "default" {
  name = "my-eb-environment"
  application = "my-eb-application"
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running Node.js 14.x"
  region = aws_db_instance.default.region
  cname_prefix = "my-eb-environment"
  setting {
    namespace = "aws:rds:dbinstance"
    name = "DBInstanceIdentifier"
    value = aws_db_instance.default.name
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "NODE_ENV"
    value = "production"
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "RDS_HOSTNAME"
    value = aws_db_instance.default.address
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "RDS_PORT"
    value = aws_db_instance.default.port
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "RDS_USERNAME"
    value = aws_db_instance.default.username
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "RDS_PASSWORD"
    value = aws_db_instance.default.password
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name = "RDS_DB_NAME"
    value = aws_db_instance.default.name
  }
  option_settings {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    option_name = "VPCId"
    value = aws_vpc.default.id
  }
  option_settings {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    option_name = "Subnets"
    value = join(",", aws_subnet.default.*.id)
  }
  option_settings {
    namespace = "aws:elasticbeanstalk:ec2:vpc"
    option_name = "SecurityGroups"
    value = aws_security_group.default.id
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "default" {
  count = 2
  cidr_block = "10.0.${count.index}.0/24"
  vpc_id = aws_vpc.default.id
}

resource "aws_security_group" "default" {
  name = "default"
  vpc_id = aws_vpc.default.id

  ingress {
    from_port = 22
    to_port = 22
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port = 443
    to_port = 443
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

This configuration creates a VPC, two subnets, a security group, an IAM instance profile, an IAM role, an RDS instance, and an Elastic Beanstalk environment. The Elastic Beanstalk environment is linked to the RDS instance through environment settings.

