 Description:
This Terraform configuration will provision an AWS infrastructure for deploying a web application. It includes the creation of IAM roles for access management, a VPC with an Internet Gateway, two subnets, route configurations, an RDS instance, and an Elastic Beanstalk environment.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

data "aws_caller_identity" "current" {}

# IAM Roles

resource "aws_iam_role" "web_app_role" {
  name = "web_app_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
  tags = merge(local.common_tags, { Name = "Web App Role" })
}

resource "aws_iam_role_policy_attachment" "web_app_policy_attachment" {
  role       = aws_iam_role.web_app_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

# VPC, Internet Gateway, Subnets, and Route Tables

resource "aws_vpc" "web_app_vpc" {
  cidr_block = "10.0.0.0/16"
  tags       = merge(local.common_tags, { Name = "Web App VPC" })
}

resource "aws_internet_gateway" "web_app_igw" {
  vpc_id = aws_vpc.web_app_vpc.id
  tags   = merge(local.common_tags, { Name = "Web App Internet Gateway" })
}

resource "aws_subnet" "web_app_subnet_1" {
  vpc_id     = aws_vpc.web_app_vpc.id
  cidr_block = "10.0.1.0/24"
  tags       = merge(local.common_tags, { Name = "Web App Subnet 1" })
}

resource "aws_subnet" "web_app_subnet_2" {
  vpc_id     = aws_vpc.web_app_vpc.id
  cidr_block = "10.0.2.0/24"
  tags       = merge(local.common_tags, { Name = "Web App Subnet 2" })
}

resource "aws_route_table" "web_app_route_table" {
  vpc_id = aws_vpc.web_app_vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.web_app_igw.id
  }
  tags = merge(local.common_tags, { Name = "Web App Route Table" })
}

resource "aws_route_table_association" "web_app_subnet_1_association" {
  subnet_id      = aws_subnet.web_app_subnet_1.id
  route_table_id = aws_route_table.web_app_route_table.id
}

resource "aws_route_table_association" "web_app_subnet_2_association" {
  subnet_id      = aws_subnet.web_app_subnet_2.id
  route_table_id = aws_route_table.web_app_route_table.id
}

# RDS Instance

resource "aws_db_subnet_group" "web_app_rds_subnet_group" {
  name       = "web_app_rds_subnet_group"
  subnet_ids = [aws_subnet.web_app_subnet_1.id, aws_subnet.web_app_subnet_2.id]
  tags       = merge(local.common_tags, { Name = "Web App RDS Subnet Group" })
}

resource "aws_rds_cluster" "web_app_rds_cluster" {
  cluster_identifier      = "web_app_rds_cluster"
  engine                  = "aurora-postgresql"
  engine_version          = "14.3"
  master_username         = "web_app_master_user"
  master_password         = "YourMasterPassword"
  db_subnet_group_name    = aws_db_subnet_group.web_app_rds_subnet_group.name
  vpc_security_group_ids   = [aws_security_group.web_app_security_group.id]
  skip_final_snapshot      = true
  tags                    = merge(local.common_tags, { Name = "Web App RDS Cluster" })
}

# Elastic Beanstalk Environment

resource "aws_elastic_beanstalk_environment" "web_app_environment" {
  name                = "web_app_environment"
  application          = "YourApplicationName"
  solution_stack_name = "64bit Amazon Linux 2 v3.0.6 running Node.js 14.x"
  region              = aws_vpc.web_app_vpc.region
  vpc_id              = aws_vpc.web_app_vpc.id
  cname_prefix        = "web-app"
  setting {
