    value     = aws_security_group.web_app_security_group.id
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:network"
    name      = "ELBSecurityGroups"
    value     = aws_security_group.web_app_security_group.id
  }
  setting {
    namespace = "aws:elasticbeanstalk:application:network"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.web_app_subnet_1.id, aws_subnet.web_app_subnet_2.id)
  }
