  name = "@"
  type = "A"
  alias {
    name                   = aws_route53_record.ipv6_record.fqdn
    zone_id                = local.hosted_zone_id
    evaluate_target_health = true
    host_name              = aws_route53_health_check.example.fqdn
  }
}

