LLM Output #0:
 Description:
This Terraform configuration will set up a blue/green deployment with Amazon Web Services (AWS) resources, including EC2 instances, Route 53, RDS, and IAM roles. The configuration will create two separate environments named "blue" and "green", each connected to a shared RDS database named "myapp_db". Health checks will be enabled on the Route 53 records, and a failover routing policy will be implemented. An instance profile named "eb_ec2_profile" will be created for the EC2 instances.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  environment_name = {
    blue = "blue"
    green = "green"
  }
  database_name = "myapp_db"
  instance_profile_name = "eb_ec2_profile"
}

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    effect = "Allow"

    principals {
      type        = "Federated"
      identifiers = [aws_oidc_provider.oidc_provider.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.sts.assumable_role_with_web_identity.oauth2.amazonaws.com"

      values = [
        "sts:AssumeRoleWithWebIdentity"
      ]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "token.sub"

      values = [
        "system.accounts.oauth-ids.amazonaws.com"
      ]
    }
  }
}

resource "aws_iam_openid_connect_provider" "oidc_provider" {
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [data.aws_caller_identity.current.arn]
  url             = "https://${var.oidc_issuer_url}"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = local.instance_profile_name

  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json
}

resource "aws_iam_role_policy_attachment" "eb_ec2_policy_attachment" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_rds_db_instance" "shared_db" {
  allocated_storage      = 20
  storage_type           = "gp2"
  engine                 = "postgres"
  engine_version         = "13.2"
  instance_class         = "db.t2.micro"
  db_name                = local.database_name
  username               = "myapp_user"
  password               = "myapp_password"
  parameter_group_name   = "default.postgres13"
  skip_final_snapshot    = true
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  publicly_accessible    = false
}

resource "aws_security_group" "rds_sg" {
  name_prefix = "rds_sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "deployer" {
  key_name   = "deployer_key"
  public_key = file("~/.ssh/id_rsa.pub")
}

data "aws_availability_zones" "available" {}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_launch_configuration" "blue_launch_config" {
  name_prefix          = "blue_launch_config"
  image_id             = data.aws_ami.ubuntu.id
  instance_type        = "t2.micro"
  key_name             = aws_key_pair.deployer.key_name
  security_groups      = [aws_security_group.ec2_sg.id]
  user_data            = filebase64("user_data.sh")
  iam_instance_profile = aws_iam_role.eb_ec2_role.name

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_launch_configuration" "green_launch_config" {
  name_prefix          = "green_launch_config"
  image_id             = data.aws_ami.ubuntu.id
  instance_type        = "t2.micro"
  key_name             = aws_key_pair.deployer.key_name
  security_groups      = [aws_security_group.ec2_sg.id]
  user_data            = filebase64("user_data.sh")
  iam_instance_profile = aws_iam_role.eb_ec2_role.name

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "blue_asg" {
  name                 = "blue_asg"
  launch_configuration = aws_launch_configuration.blue_launch_config.name
  vpc_zone_identifier  = data.aws_subnet_ids.default.ids

  lifecycle {
    create_before_destroy = true
  }

  tag {
    key                 = "Name"
    value               = "${local.environment_name.blue}.myapp"
    propagate_at_launch = true
  }
}

resource "aws_autoscaling_group" "green_asg" {
  name                 = "green_asg"
  launch_configuration = aws_launch_configuration.green_launch_config.name
  vpc_zone_identifier  = data.aws_subnet_ids.default.ids

  lifecycle {
    create_before_destroy = true
  }

  tag {
    key                 = "Name"
    value               = "${local.environment_name.green}.myapp"
    propagate_at_launch = true
  }
}

data "aws_route53_zone" "primary" {
  name = var.domain_name
}

resource "aws_route53_record" "blue_record" {
  zone_id = data.aws_route53_zone.primary.zone_id
  name    = data.aws_route53_zone.primary.name
  type    = "A"

  alias {
    name                   = aws_alb.blue_alb.dns_name
    zone_id                = aws_alb.blue_alb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green_record" {
  zone_id = data.aws_route53_zone.primary.zone_id
  name    = data.aws_route53_zone.primary.name
  type    = "A"

  alias {
    name                   = aws_alb.green_alb.dns_name
    zone_id                = aws_alb.green_alb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_alb" "blue_alb" {
  name            = "blue_alb"
  internal        = false
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = data.aws_subnet_ids.default.ids

  tags = {
    Name = "${local.environment_name.blue}.myapp_alb"
