 **Description:**
This Terraform configuration will deploy a web application on AWS using an EC2 instance with an Elastic Load Balancer (ELB) for scalability. The web application can be written in supported programming languages such as Node.js, Python, Java, or PHP. The configuration includes an IAM role for the EC2 instance to allow it to access necessary AWS resources.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "app_name" {
  default = "my-web-app"
}

variable "instance_type" {
  default = "t2.micro"
}

variable "key_name" {
  default = "my-key-pair"
}

variable "subnet_id" {
  default = "subnet-0abcdefghijklmnopqrst"
}

variable "vpc_security_group_ids" {
  type    = list(string)
  default = ["sg-0abcdefghijklmnopqrst"]
}

variable "ami_id" {
  type    = string
  default = "ami-0abcdefghijklmnopqrst"
}

data "aws_ami" "amazon_linux" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["amazon"]
}

resource "aws_iam_role" "ec2_role" {
  name = "${var.app_name}-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "${var.app_name}-ec2-profile"
  role = aws_iam_role.ec2_role.name
}

resource "aws_key_pair" "deployer" {
  key_name   = var.key_name
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_security_group_rule" "allow_http_tcp" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = element(var.vpc_security_group_ids, 0)
}

resource "aws_security_group_rule" "allow_ssh_tcp" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = element(var.vpc_security_group_ids, 0)
}

resource "aws_launch_configuration" "web_server" {
  name_prefix          = "${var.app_name}-"
  image_id             = var.ami_id
  instance_type        = var.instance_type
  key_name             = aws_key_pair.deployer.key_name
  security_groups      = var.vpc_security_group_ids
  user_data            = filebase64("user_data.sh")
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name
}

resource "aws_autoscaling_group" "web_server_asg" {
  name                 = "${var.app_name}-asg"
  launch_configuration = aws_launch_configuration.web_server.name
  vpc_zone_identifier  = [var.subnet_id]

  min_size             = 2
  max_size             = 10
  desired_capacity     = 2

  tag {
    key                 = "Name"
    value               = var.app_name
    propagate_at_launch = true
  }
}

resource "aws_elb" "web_server_elb" {
  name            = "${var.app_name}-elb"
  subnets         = [var.subnet_id]
  security_groups = var.vpc_security_group_ids

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    target              = "HTTP:80/"
    interval            = 30
  }

  instances                   = [aws_autoscaling_group.web_server_asg.id]
  cross_zone_load_balancing   = true
  idle_timeout                = 400
  connection_draining         = true
  connection_draining_timeout = 300
}
```

**Note:**
- Replace the `subnet_id`, `vpc_security_group_ids`, `ami_id`, and `key_name` variables with appropriate values for your environment.
- The `user_data` script (`user_data.sh`) should be a shell script that installs and configures your web application on the EC2 instance.

