 Description:
This Terraform configuration creates an AWS CodeBuild project with a basic setup. It includes an IAM role for the CodeBuild service and grants necessary permissions. The project is configured to use a GitHub repository as its source.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  codebuild_project_name = "my-codebuild-project"
  github_repo_owner      = "my-github-username"
  github_repo_name       = "my-repository"
  github_branch          = "main"
}

data "github_repository" "repo" {
  owner    = local.github_repo_owner
  repo_name = local.github_repo_name
}

resource "aws_iam_role" "codebuild_role" {
  name = local.codebuild_project_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildBasicBuild"
}

resource "aws_codebuild_project" "codebuild_project" {
  name          = local.codebuild_project_name
  description   = "My CodeBuild project"
  service_role  = aws_iam_role.codebuild_role.arn

  source {
    type      = "GITHUB"
    location  = data.github_repository.repo.clone_url
    buildspec = file("buildspec.yml")
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:4.0"
    type                        = "LINUX_CONTAINER"
    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_token
      type  = "PLAINTEXT"
    }
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }
}

variable "github_token" {
  description = "GitHub personal access token"
  type        = string
  default     = ""
}
```

Please replace `my-github-username`, `my-repository`, and `my-codebuild-project` with your actual GitHub username, repository name, and desired CodeBuild project name. Also, provide a valid GitHub personal access token for the `github_token` variable.

