  region = "us-west-2"
}

locals {
  codebuild_project_name = "my-codebuild-project"
}

data "aws_iam_policy_document" "codebuild_policy" {
  statement {
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "${local.codebuild_project_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "CodeBuildPolicy"
    policy = data.aws_iam_policy_document.codebuild_policy.json
  }
}

resource "aws_codebuild_project" "codebuild_project" {
  name      = local.codebuild_project_name
  role      = aws_iam_role.codebuild_role.arn
  source {
    type      = "GITHUB"
    location  = "https://github.com/my-org/my-repo.git"
    buildspec = file("buildspec.yml")
  }

  secondary_source {
    type      = "S3"
    location  = "my-bucket-name/my-key"
    buildspec = file("buildspec-s3.yml")
  }
}
```

In this configuration, replace `us-west-2` with your desired AWS region, `my-org` with your GitHub organization, `my-repo` with your GitHub repository, `my-bucket-name` with your S3 bucket name, and `my-key` with your S3 object key. The `buildspec.yml` and `buildspec-s3.yml` files should be located in the same directory as your Terraform configuration files.

