  })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildBasicCodeStarSourceAccess"
}

resource "aws_codebuild_project" "codebuild_project" {
  name          = local.codebuild_project_name
  description   = "My CodeBuild Project"
  service_role  = aws_iam_role.codebuild_role.arn

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:4.0"
    type                        = "LINUX_CONTAINER"

    environment_variable {
      name  = "VAR1"
      value = "value1"
    }

    environment_variable {
      name  = "VAR2"
      value = "value2"
    }
  }

  sources {
    type = "GITHUB"

    location = "https://github.com/my-org/my-repo.git"
    buildspec = "buildspec.yml"
  }

  sources {
    type = "S3"

    location = "s3://my-bucket/secondary-source.zip"
    buildspec = "secondary-buildspec.yml"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  artifacts {
    type = "S3"

    location = "s3://my-bucket/secondary-artifacts"
  }
}
```

This configuration creates an AWS CodeBuild project named `my-codebuild-project` in the `us-west-2` region. The project uses a custom IAM role for permissions, has two environment variables, a primary source from a GitHub repository, a secondary source from an S3 bucket, and two sets of artifacts, one for primary and one for secondary. The IAM role has the necessary permissions for CodeBuild to access the source and artifact locations.

