 Description: This Terraform configuration creates an Amazon Lex bot with a custom intent and utterances. It also sets up an IAM role for the bot to access AWS services.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lex_bot_name = "my-lex-bot"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "lex_bot_role" {
  name = "${local.lex_bot_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex-runtime.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lex_bot" "bot" {
  name                           = local.lex_bot_name
  locale_id                      = "en_US"
  voice_id                       = "Joanna"
  intents                        = [aws_lex_bot_intent.intent.id]
  session_attributes             = { "MySessionAttribute" = "MySessionAttributeValue" }
  session_expiration_hours       = 24
  session_timeout_seconds        = 300
  lambda_arn                     = module.lambda.lambda_function_arn
  dialog_code_hook_arn           = module.lambda.lambda_function_arn
  dialog_code_hook_input_transcript = "{\"user\": \"$input.intent.name\", \"intent\": \"$input.intent.name\", \"slots\": $input.currentIntent.slots}"
  dialog_code_hook_output_transcript = "{\"contentType\": \"PlainText\", \"content\": \"$output.text.content\"}"
  dialog_code_hook_input_transcript_types = ["IntentName", "IntentSlot"]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lex_bot_intent" "intent" {
  name            = "${local.lex_bot_name}-intent"
  slots           = ["MySlot"]
  sample_utterances = [
    "Tell me the weather",
    "What's the weather like today",
    "Weather forecast",
  ]
}

module "lambda" {
  source = "hashicorp/lambda-function-python3.8"

  function_name = "${local.lex_bot_name}-function"
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lex_bot_role.arn
  zip_file      = file("lambda_function.zip")
}
```

