          "lex-runtime:PostContent",
          "lex-runtime:PutSlot",
          "lex-runtime:GetSlot",
          "lex-runtime:DeleteSlot",
          "lex-runtime:PutSessionAttribute",
          "lex-runtime:GetSessionAttribute",
          "lex-runtime:Close"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
