  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

resource "aws_lex_bot" "lex_bot" {
  name = local.bot_name
  locale_id = "en-US"
  intents = [
    aws_lex_bot_intent.intent1.name,
    aws_lex_bot_intent.intent2.name
  ]
  slots = [
