  name = "intent1"
  sample_utterances = ["Tell me the weather"]
}

resource "aws_lex_bot_intent" "intent2" {
  name = "intent2"
  sample_utterances = ["What's the date today?"]
}

resource "aws_lex_bot_slot" "slot1" {
  name = "slot1"
  slot_type_name = "AWS_STANDARD_SLOT_TYPE_AMAZON.Number"
}

resource "aws_lex_bot_slot" "slot2" {
  name = "slot2"
  slot_type_name = "AWS_STANDARD_SLOT_TYPE_AMAZON.Date"
}

resource "aws_lex_bot_alias" "lex_bot_alias" {
  name = local.bot_name
  bot_id = aws_lex_bot.lex_bot.id
  version = "$LATEST"
}

output "bot_arn" {
  value = aws_lex_bot.lex_bot.arn
}
```

This configuration creates an AWS Lex bot named `my_lex_bot` with two intents (`intent1` and `intent2`) and two slots (`slot1` and `slot2`). The bot uses the `Joanna` voice and the `en-US` locale. The `intent1` and `intent2` have sample utterances defined, while the `slot1` and `slot2` are of type `AWS_STANDARD_SLOT_TYPE_AMAZON.Number` and `AWS_STANDARD_SLOT_TYPE_AMAZON.Date`, respectively. The bot also has an IAM role with the necessary policies attached. The ARN of the bot is outputted for further use.

