 **Description:**
This Terraform configuration will create an AWS Lex bot for booking a trip. The bot will be designed to handle user requests for booking flights, hotels, and rental cars. It will use Lambda functions for the bot's conversation logic and will be integrated with DynamoDB for storing user data.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bot_name" {
  default = "TripBookingBot"
}

variable "lambda_function_arn" {
  type    = string
  default = "arn:aws:lambda:us-west-2:123456789012:function:TripBookingBotFunction"
}

resource "aws_lex_bot" "trip_bot" {
  name        = var.bot_name
  locale_id   = "en_US"
  voice_id    = "Joanna"

  intents {
    name = "BookFlight"
    slots {
      name     = "DepartureCity"
      slot_type = "AMAZON.City"
    }
    slots {
      name     = "ArrivalCity"
      slot_type = "AMAZON.City"
    }
    slots {
      name     = "DepartureDate"
      slot_type = "AMAZON.Date"
    }
    slots {
      name     = "ReturnDate"
      slot_type = "AMAZON.Date"
    }
  }

  intents {
    name = "BookHotel"
    slots {
      name     = "City"
      slot_type = "AMAZON.City"
    }
    slots {
      name     = "CheckInDate"
      slot_type = "AMAZON.Date"
    }
    slots {
      name     = "CheckOutDate"
      slot_type = "AMAZON.Date"
    }
  }

  intents {
    name = "BookCar"
    slots {
      name     = "PickUpLocation"
      slot_type = "AMAZON.City"
    }
    slots {
      name     = "DropOffLocation"
      slot_type = "AMAZON.City"
    }
    slots {
      name     = "PickUpDate"
      slot_type = "AMAZON.Date"
    }
    slots {
      name     = "DropOffDate"
      slot_type = "AMAZON.Date"
    }
  }

  intent_slots {
    name     = "DepartureCity"
    slot_name = "DepartureCity"
  }
  intent_slots {
    name     = "ArrivalCity"
    slot_name = "ArrivalCity"
  }
  intent_slots {
    name     = "DepartureDate"
    slot_name = "DepartureDate"
  }
  intent_slots {
    name     = "ReturnDate"
    slot_name = "ReturnDate"
  }
  intent_slots {
    name     = "City"
    slot_name = "City"
  }
  intent_slots {
    name     = "CheckInDate"
    slot_name = "CheckInDate"
  }
  intent_slots {
    name     = "CheckOutDate"
    slot_name = "CheckOutDate"
  }
  intent_slots {
    name     = "PickUpLocation"
    slot_name = "PickUpLocation"
  }
  intent_slots {
    name     = "DropOffLocation"
    slot_name = "DropOffLocation"
  }
  intent_slots {
    name     = "PickUpDate"
    slot_name = "PickUpDate"
  }
  intent_slots {
    name     = "DropOffDate"
    slot_name = "DropOffDate"
  }

  fulfillment_activity {
    name = "AWS_LAMBDA_Invoke"
    activity_type = "AWS_LAMBDA_Invoke"
    version = "1"
    activity_data {
      resource = var.lambda_function_arn
    }
  }

  slot_type_mappings {
    name = "AMAZON.City"
    values = {
      "New York" = "New York"
      "Los Angeles" = "Los Angeles"
      "Chicago" = "Chicago"
      # Add more city values as needed
    }
  }

  slot_type_mappings {
    name = "AMAZON.Date"
    values = {
      "2023-03-01" = "2023-03-01"
      "2023-03-02" = "2023-03-02"
      # Add more date values as needed
    }
  }
}
```

This configuration creates an AWS Lex bot named `TripBookingBot` with three intents for booking flights, hotels, and rental cars. It also defines slot types for cities and dates, and maps some common values for those slot types. The bot uses a Lambda function for its conversation logic, specified by the `lambda_function_arn` variable.

