provider "aws" {
  region = "us-west-2"
}

locals {
  dynamodb_table_name = "pizza_preferences"
}

# Create DynamoDB table for storing user preferences
resource "aws_dynamodb_table" "preferences" {
  name           = local.dynamodb_table_name
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "user_id"

  attribute {
    name = "user_id"
    type = "S"
  }

  attribute {
    name = "preference"
    type = "S"
  }
}

# Create IAM role for the Lambda function
resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "lambda_basic_exec" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Create Lambda function
resource "aws_lambda_function" "pizza_bot" {
  function_name = "pizza_bot"
  runtime       = "nodejs14.x"
  handler       = "index.handler"
  role          = aws_iam_role.lambda_exec.arn

  source_code_hash = base64sha256(filebase64("function.zip"))

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = local.dynamodb_table_name
    }
  }
}

# Create AWS Lex bot
resource "aws_lex_bot" "pizza_bot" {
  name        = "pizza_bot"
  locale_id   = "en_US"
  locale_name = "English (US)"

  intents {
    name = "OrderPizza"
  }

  bot_settings {
    lambda_arn = aws_lambda_function.pizza_bot.arn
  }

  slot_type {
    name = "Size"
    values = [
      "Small",
      "Medium",
      "Large"
    ]
  }

  slot_type {
    name = "Topping"
    values = [
      "Pepperoni",
      "Mushrooms",
      "Olives",
      "Onions"
    ]
  }

  slot_type {
    name = "Crust"
    values = [
      "Thin",
      "Thick",
      "Hand-tossed"
    ]
  }
}
```

