This Terraform configuration creates an Amazon Lex V2 bot for children. It includes an IAM role for the bot, a Lambda function for bot's conversation logic, and an API Gateway to expose the bot's endpoint.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  bot_name = "children_bot"
  lambda_function_name = "${local.bot_name}_lambda"
  api_gateway_rest_api_name = "${local.bot_name}_api"
  api_gateway_deployment_stage_name = "${local.bot_name}_deployment"
}

data "aws_iam_policy_document" "bot_policy" {
  statement {
    actions = ["lambda:InvokeFunction"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "bot" {
  name = local.bot_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex-runtime.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "bot_policy_attachment" {
  role       = aws_iam_role.bot.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSAlexaPresentationLanguageServiceRole"
}

resource "aws_iam_role_policy_attachment" "bot_custom_policy_attachment" {
  role       = aws_iam_role.bot.name
  policy_arn = aws_iam_policy.bot.arn
}

resource "aws_iam_policy" "bot" {
  name = local.bot_name
  policy = data.aws_iam_policy_document.bot_policy.json
}

resource "aws_lambda_function" "bot" {
  function_name = local.lambda_function_name
  runtime = "nodejs14.x"
  role = aws_iam_role.bot.arn
  handler = "index.handler"
  source_code_hash = base64sha256(filebase64("function.zip"))

  environment {
    variables = {
      bot_name = local.bot_name
    }
  }
}

resource "aws_apigatewayv2_api" "bot" {
  name = local.api_gateway_rest_api_name
}

resource "aws_apigatewayv2_integration" "bot" {
  api_id = aws_apigatewayv2_api.bot.id
  integration_uri = aws_lambda_function.bot.invoke_arn
  integration_type = "AWS_PROXY"
  integration_method = "POST"
  payload_format_version = "2.0"
}

resource "aws_apigatewayv2_route" "bot" {
  api_id = aws_apigatewayv2_api.bot.id
  route_key = local.bot_name
  target = aws_apigatewayv2_integration.bot.id
}

resource "aws_apigatewayv2_stage" "bot" {
  api_id = aws_apigatewayv2_api.bot.id
  stage_name = local.api_gateway_deployment_stage_name
  auto_deploy = true
}

resource "aws_lexv2_bot" "bot" {
  name = local.bot_name
  bot_version = "1.0"
  intents {
    name = local.bot_name
    sample_utterances = ["Hello", "Hi", "Hello bot"]
  }
  lambda_arn = aws_lambda_function.bot.arn
  execution_arn = aws_apigatewayv2_stage.bot.execution_arn
}
