 Description: This Terraform configuration creates an AWS Connect instance and associates it with a SAMB bot using SAML. It also sets up the necessary IAM roles for the AWS Connect instance and the bot.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  connect_instance_name = "my-connect-instance"
  bot_name              = "my-bot"
}

data "aws_caller_identity" "current" {}

# IAM role for AWS Connect instance
resource "aws_iam_role" "connect_instance" {
  name = "${local.connect_instance_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

# IAM role for SAML bot
resource "aws_iam_role" "saml_bot" {
  name = "${local.bot_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${local.bot_name}"
        }
        Condition = {
          StringEquals = {
            "token.actions.saml.amazonaws.com:aud" = "https://saml.aws.amazon.com"
          }
        }
      }
    ]
  })
}

# Attach necessary policies to the roles
resource "aws_iam_role_policy_attachment" "connect_instance_policy" {
  role       = aws_iam_role.connect_instance.name
  policy_arn = "arn:aws:iam::aws:policy/AWSConnectInstanceFullAccess"
}

resource "aws_iam_role_policy_attachment" "saml_bot_policy" {
  role       = aws_iam_role.saml_bot.name
  policy_arn = "arn:aws:iam::aws:policy/AWSConnectBotFullAccess"
}

# AWS Connect instance
resource "aws_connect_instance" "connect_instance" {
  name           = local.connect_instance_name
  instance_type  = "small"
  region         = var.region
  vpc_id         = aws_vpc.main.id
  subnet_id      = aws_subnet.main.id
  role_arn       = aws_iam_role.connect_instance.arn
  call_recording_enabled = true
}

# SAML bot
resource "aws_connect_bot" "saml_bot" {
  name = local.bot_name
  role_arn = aws_iam_role.saml_bot.arn
}

# AWS Connect bot association
resource "aws_connect_bot_association" "saml_bot_association" {
  instance_id = aws_connect_instance.connect_instance.id
  bot_id      = aws_connect_bot.saml_bot.id
  role_arn    = aws_iam_role.connect_instance.arn
  association_type = "SAML"
  saml_provider_arn = aws_saml_provider.saml.arn
}

# SAML provider
resource "aws_saml_provider" "saml" {
  name = "my-saml-provider"
  description = "My SAML Provider"
  tags = {
    Environment = "prod"
  }

  # SAML metadata
  metadata_document = filebase64("path/to/your/saml-metadata.xml")
  metadata_document_type = "XML"

  # SAML attribute mappings
  attribute_mappings = {
    "email" = "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress"
  }
}
```

Please replace `path/to/your/saml-metadata.xml` with the actual path to your SAML metadata file.

This configuration assumes you have a VPC, subnet, and an IAM role for the AWS account already created. If not, you may need to add those resources as well.

