 Description: This Terraform configuration creates a basic Amazon Kinesis Data Stream in the specified AWS region. It includes an IAM role for the Kinesis service to assume for accessing the stream.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  kinesis_stream_name = "my-kinesis-stream"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "kinesis_stream_role" {
  name = "${local.kinesis_stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kinesis_stream" "main" {
  name             = local.kinesis_stream_name
  shard_count      = 1
  retention_period = 24 * 60 * 60

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords"
  ]

  encrypted       = true
  stream_encryption_type = "AES256"

  kms_key_id = "arn:aws:kms:us-west-2:${data.aws_caller_identity.current.account_id}:key/1234abcd-12ab-34cd-56ef-1234567890ab"

  tags = {
    Name = local.kinesis_stream_name
  }

  lifecycle {
    ignore_changes = [
      encrypted,
      stream_encryption_type,
      kms_key_id
    ]
  }
}

resource "aws_iam_policy_attachment" "kinesis_stream_to_stream_role" {
  role       = aws_iam_role.kinesis_stream_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisStreamsFullAccess"
}
```

Please note that you'll need to replace the `kms_key_id` with the actual ARN of a KMS key in your AWS account.

This configuration uses the `aws` provider with the `us-west-2` region. It creates an IAM role for the Kinesis service, a Kinesis data stream, and attaches the `AmazonKinesisStreamsFullAccess` policy to the IAM role. The Kinesis stream is encrypted using AES256 encryption and the specified KMS key. The configuration also includes a lifecycle block to ignore changes to the encryption settings.

