 Description:
This Terraform configuration will create a basic Amazon Kinesis Analytics Application with an input Kinesis Stream. It will also create the necessary IAM roles and policies for the application to function.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  application_name = "kinesis-analytics-app"
  kinesis_stream_name = "${local.application_name}-input"
}

data "aws_iam_policy_document" "kinesis_analytics_app_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kinesis.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "kinesis_analytics_app_role" {
  name = "${local.application_name}-role"
  assume_role_policy = data.aws_iam_policy_document.kinesis_analytics_app_assume_role_policy.json
}

data "aws_iam_policy_document" "kinesis_analytics_app_policy" {
  statement {
    actions = [
      "kinesis:DescribeStream",
      "kinesis:GetRecords",
      "kinesis:GetShardIterator",
      "kinesis:PutRecord",
      "kinesis:DescribeStreamSummary"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "kinesis_analytics_app_policy_attachment" {
  name = "${local.application_name}-policy"
  path = "/"

  policy = data.aws_iam_policy_document.kinesis_analytics_app_policy.json
}

resource "aws_iam_role_policy_attachment" "kinesis_analytics_app_role_policy_attachment" {
  role       = aws_iam_role.kinesis_analytics_app_role.name
  policy_arn = aws_iam_policy.kinesis_analytics_app_policy_attachment.arn
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name = local.kinesis_stream_name
  shard_count = 1
}

resource "aws_kinesis_analytics_application" "kinesis_analytics_app" {
  name = local.application_name
  input = {
    kinesis_stream_arn = aws_kinesis_stream.kinesis_stream.arn
  }

  output {
    elasticsearch_configuration {
      domain_arn = "your-elasticsearch-domain-arn"
      index = "your-index-name"
    }
  }

  role_arn = aws_iam_role.kinesis_analytics_app_role.arn
}
```

Please replace `"your-elasticsearch-domain-arn"` and `"your-index-name"` with your actual Elasticsearch domain ARN and index name respectively.

This configuration creates an IAM role for the Kinesis Analytics Application, a Kinesis Stream, and a Kinesis Analytics Application that uses the created stream as input. The Kinesis Analytics Application sends its output to an Elasticsearch domain.

