}

variable "bucket_name" {
  default = "my-kinesis-firehose-bucket"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn             = aws_s3_bucket.bucket.arn
    buffer_size           = 128
    compression_format    = "UNCOMPRESSED"
    encryption_configuration {
      encryption_type = "AES256"
    }
    role_arn              = aws_iam_role.firehose_role.arn
    dynamic_partitioning_configuration {
      enabled = true
    }
  }
}

resource "aws_s3_bucket" "bucket" {
  bucket = var.bucket_name
  acl    = "private"
}

resource "aws_iam_role" "firehose_role" {
  name = "my-kinesis-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "my-kinesis-firehose-policy"
  description = "Policy for Kinesis Firehose"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:AbortMultipartUpload",
          "s3:ListParts",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_to_s3" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}
```

This configuration creates an IAM role for Kinesis Firehose, an S3 bucket for the destination, and attaches the necessary policies to the role. The Kinesis Data Firehose delivery stream is then created with the specified configuration.

