 Description: This Terraform configuration will create a Kinesis Data Firehose delivery stream that delivers data to an OpenSearch domain. The configuration includes an IAM role for the Firehose service to assume, and it is deployable with Terraform v1.9.8 and AWS provider v5.75.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  firehose_role_name = "firehose-to-opensearch-role"
}

data "aws_iam_policy_document" "firehose_to_opensearch" {
  statement {
    actions = [
      "es:IndexDocument",
      "es:RefreshDocument",
      "es:GetIndexMapping",
      "es:GetIndexSettings",
    ]
    resources = [
      "arn:aws:es:us-west-2:123456789012:domain/opensearch-domain/*"
    ]
  }
}

resource "aws_iam_role" "firehose_to_opensearch" {
  name = local.firehose_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_to_opensearch" {
  role       = aws_iam_role.firehose_to_opensearch.name
  policy_arn = data.aws_iam_policy.opensearch_full_access.arn
}

data "aws_iam_policy" "opensearch_full_access" {
  path = "/"
  policy_id = "OpenSearchFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_to_opensearch" {
  name        = "firehose-to-opensearch"
  destination = "opensearch"

  kinesis_source_configuration {
    producer_configuration {
      compression_format = "UNCOMPRESSED"
    }
  }

  opensearch_destination_configuration {
    region = "us-west-2"
    domain_arn = "arn:aws:es:us-west-2:123456789012:domain/opensearch-domain"
    index_name = "firehose-index"
  }

  lifecycle {
    ignore_changes = [
      kinesis_source_configuration[0].producer_configuration[0].compression_format
    ]
  }
}
```

Please replace the `arn:aws:es:us-west-2:123456789012:domain/opensearch-domain` with the actual ARN of your OpenSearch domain. Also, make sure to update the `region` variable with the appropriate region where your OpenSearch domain and AWS resources are located.

