```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  firehose_role_name = "firehose_to_splunk"
  splunk_role_name   = "splunk_firehose_role"
}

data "aws_caller_identity" "current" {}

# IAM Role for Kinesis Data Firehose
resource "aws_iam_role" "firehose_role" {
  name = local.firehose_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Role for Splunk
resource "aws_iam_role" "splunk_role" {
  name = local.splunk_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "splunk.amazonaws.com"
        }
      }
    ]
  })
}

# Policy for Kinesis Data Firehose to access Splunk
resource "aws_iam_policy" "firehose_to_splunk" {
  name = "${local.firehose_role_name}_to_splunk"

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "splunk:PutEvent",
          "splunk:PutEventBatch"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach policy to Firehose role
resource "aws_iam_role_policy_attachment" "firehose_to_splunk_policy" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_to_splunk.arn
}

# Attach policy to Splunk role
resource "aws_iam_role_policy_attachment" "splunk_firehose_policy" {
  role       = aws_iam_role.splunk_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLogDeliveryFirehoseToSplunk"
}

# Kinesis Data Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = "firehose_to_splunk"
  destination = "splunk"

  kinesis_producer_configuration {
    region = var.region
  }

  splunk_configuration {
    region = var.region
    role_arn = aws_iam_role.splunk_role.arn
  }
}

variable "region" {
  default = "us-west-2"
}
