 Description:
This Terraform configuration will create an AWS Kinesis Data Firehose delivery stream with an HTTP endpoint destination, such as New Relic. The configuration includes the necessary IAM roles and policies for the Firehose and the HTTP endpoint.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  firehose_role_name = "firehose_to_newrelic"
  firehose_policy_name = "firehose_to_newrelic_policy"
  newrelic_role_name = "newrelic_firehose_role"
  newrelic_policy_name = "newrelic_firehose_policy"
}

data "aws_iam_policy_document" "firehose_policy" {
  statement {
    actions = ["kinesis:PutRecord"]
    resources = ["arn:aws:kinesis:us-west-2:123456789012:stream/*"]
    effect    = "Allow"
  }
}

resource "aws_iam_role" "firehose_role" {
  name = local.firehose_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name        = local.firehose_policy_name
  path        = "/"
  description = "Policy for Kinesis Firehose to New Relic"

  policy = data.aws_iam_policy_document.firehose_policy.json
}

resource "aws_iam_role_policy_attachment" "firehose_to_firehose_policy" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

data "aws_iam_policy_document" "newrelic_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::123456789012:role/NewRelic-Synthetics-Agent"]
    }
  }
}

resource "aws_iam_role" "newrelic_role" {
  name = local.newrelic_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "newrelic_policy" {
  name        = local.newrelic_policy_name
  path        = "/"
  description = "Policy for New Relic HTTP Endpoint"

  policy = data.aws_iam_policy_document.newrelic_policy.json
}

resource "aws_iam_role_policy_attachment" "newrelic_to_newrelic_policy" {
  role       = aws_iam_role.newrelic_role.name
  policy_arn = aws_iam_policy.newrelic_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "firehose" {
  name        = "firehose_to_newrelic"
  destination = "http"

  http_configuration {
    buffer_size = 16
    compression_format = "UNCOMPRESSED"
    content_encoding = "UTF-8"
    endpoint = "https://ingest.newrelic.com/ingest"
    region = "us-west-2"
    role_arn = aws_iam_role.newrelic_role.arn
  }
}
```

Please replace the `region` and `endpoint` values with your own AWS region and New Relic HTTP endpoint URL. Also, replace the `arn:aws:iam::123456789012:role/NewRelic-Synthetics-Agent` with the actual ARN of the New Relic IAM role that will be used as the principal for the Firehose delivery stream.

This configuration assumes that you have already created an IAM role for the New Relic Synthetics Agent with the necessary permissions to receive data from the Firehose delivery stream. If you haven't created it yet, you can create it using the AWS Management Console or another Terraform configuration.

