 Description: This Terraform configuration creates a Kinesis Video Stream in the specified AWS region. It also creates an IAM role with necessary permissions for the Kinesis Video Stream.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  kinesis_stream_name = "my-kinesis-video-stream"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "kinesis_video_stream_role" {
  name = "${local.kinesis_stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kinesis_video_stream" "main" {
  name = local.kinesis_stream_name

  data_retention_period_hours = 24
  encrypted = true

  media_format = "MPEG-TS"

  kms_key_id = aws_kms_key.kinesis_video_stream.arn

  role_arn = aws_iam_role.kinesis_video_stream_role.arn

  stream_encryption = "AES_128"

  tags = {
    Name = local.kinesis_stream_name
  }
}

resource "aws_kms_key" "kinesis_video_stream" {
  description = "Kinesis Video Stream Encryption Key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = "${data.aws_caller_identity.current.arn}"
        }
      }
    ]
  })
}
```

This configuration creates a Kinesis Video Stream with the specified name, data retention period, encryption settings, and media format. It also creates an IAM role with the necessary permissions for the Kinesis Video Stream and an AWS KMS key for encrypting the stream data. The Kinesis Video Stream and IAM role are created in the `us-west-2` region.

