 Description: This Terraform configuration creates an AWS Kinesis Stream Consumer. It includes the necessary IAM role for the consumer and sets up the AWS provider with a valid region.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  consumer_role_name = "kinesis-stream-consumer-role"
}

data "aws_iam_policy_document" "kinesis_consumer_policy" {
  statement {
    actions = ["kinesis:DescribeStream", "kinesis:GetRecords", "kinesis:GetShardIterator"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "kinesis_consumer_role" {
  name = local.consumer_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-west-2.amazonaws.com/id/<OIDC_ID>"
        }
        Condition = {
          StringEquals = {
            "token.actions.sts.amazonaws.com:sts:AssumeRoleWithWebIdentity" = "sts.amazonaws.com"
          }
          "token.expiration" > "2023-01-01T00:00:00Z"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_consumer_policy_attachment" {
  role       = aws_iam_role.kinesis_consumer_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisConsumer"
}

resource "aws_kinesis_consumer_config" "kinesis_consumer_config" {
  consumer_name = "my-kinesis-consumer"
  aws_region   = var.aws_region
  role_arn     = aws_iam_role.kinesis_consumer_role.arn

  streaming_configuration {
    enumerator_type = "aws-java-sdk"
    enumerator_properties = jsonencode({
      Enumerator_Properties_Version = "1.0"
      Enumerator_Properties_InitialPositionInStream = "TRIM_HORIZON"
      Enumerator_Properties_InitialPositionInStream_TrimHorizon = "LATEST"
      Enumerator_Properties_InitialPositionInStream_ShardIteratorType = "AT_SEQUENCE_NUMBER"
      Enumerator_Properties_InitialPositionInStream_ShardIterator = aws_kinesis_stream.my_kinesis_stream.shard_iterator_for_shard("0").id
    })
  }
}

resource "aws_kinesis_stream" "my_kinesis_stream" {
  name             = "my-kinesis-stream"
  shard_count      = 1
  retention_period = 24 * 60 * 60 * 7
}
```

In this configuration, replace `<OIDC_ID>` with the OIDC ID of your EKS cluster. Also, make sure to set the `aws_region` variable to the desired AWS region. If you don't provide a value for the `aws_region` variable, it will default to `us-west-2`.

