      {
        Action = "logs:CreateLogGroup"
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "logs:CreateLogStream"
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = "logs:PutLogEvents"
        Effect = "Allow"
        Resource = aws_cloudwatch_log_group.log_group.arn
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = local.log_group_name
  retention_in_days = 14
}

resource "aws_kinesis_analytics_application" "kinesis_analytics_app" {
  name = local.application_name

  function_code = filebase64("path/to/your/function-code.jar")

  input = {
    kinesis = {
      data_stream_arn = aws_kinesis_data_stream.data_stream.arn
    }
  }

  output = {
    elasticsearch = {
      domain_arn = aws_elasticsearch_domain.elasticsearch_domain.arn
    }
  }

  role_arn = aws_iam_role.kinesis_analytics_app_role.arn

  logging_configuration {
    include_execution_data = true
    log_group_name         = local.log_group_name
  }
}

resource "aws_kinesis_data_stream" "data_stream" {
  name        = "${local.application_name}-data-stream"
  shard_count = 1
}

resource "aws_elasticsearch_domain" "elasticsearch_domain" {
  domain_name           = "${local.application_name}-elasticsearch"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type = "m5.large.elasticsearch"
    instance_count = 2
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp2"
    volume_size = 10
  }

  advanced_options = {
    "rest.action.multi.allowexplicitindex" = "true"
  }
}
```

Please replace `path/to/your/function-code.jar` with the actual path to your Kinesis Analytics Application function code.

This configuration creates an Amazon Kinesis Data Stream, an Elasticsearch domain, and an Amazon Kinesis Analytics Application with a CloudWatch Log Stream. It also creates the necessary IAM roles for the application and the log stream. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

