  domain_id = aws_kendra_domain.kendra_domain.id
  name     = local.kendra_index_name
}

resource "aws_kendra_proxy_configuration" "kendra_proxy_config" {
  domain_id = aws_kendra_domain.kendra_domain.id

  proxy_protocol_version = "HTTP_1_1"
  proxy_protocol_port    = 80

  cname_configuration {
    cname_record_name = "kendra-proxy"
    cname_record_zone = "example.com"
  }
}

