 Description:
This Terraform configuration will set up an Active-Passive Failover policy using Amazon Route 53 resources. The health check resource will be named "primary_health_check" and will use a FQDN. The primary zone will be named "primary".

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  primary_zone_name = "primary"
  primary_health_check_fqdn = "example.com"
}

resource "aws_route53_zone" "primary" {
  name = local.primary_zone_name
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn = local.primary_health_check_fqdn
  type = "A"
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.primary.id
  name    = aws_route53_zone.primary.name
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary_health_check.id
    zone_id                = aws_route53_health_check.primary_health_check.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "secondary_record" {
  count = 2

  zone_id = aws_route53_zone.primary.id
  name    = "${local.primary_zone_name}.${aws_route53_zone.primary.name}"
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary_health_check.id
    zone_id                = aws_route53_health_check.primary_health_check.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_traffic_policy" "traffic_policy" {
  name = "${local.primary_zone_name}-traffic-policy"

  traffic_policy_version = 1

  traffic_policy_resource_record_sets {
    dns_name = aws_route53_zone.primary.name
    ttl     = 300

    traffic_policy_record {
      geo_location {
        type = "default"
      }

      weight = 100
      route_value = "Primary"
      record {
        type = "A"
        alias {
          name                   = aws_route53_record.primary_record.name
          zone_id                = aws_route53_record.primary_record.zone_id
          evaluate_target_health = true
        }
      }
    }

    traffic_policy_record {
      geo_location {
        type = "default"
      }

      weight = 0
      route_value = "Secondary"

      records {
        type = "A"
        alias {
          name                   = aws_route53_record.secondary_record[count.index].name
          zone_id                = aws_route53_record.secondary_record[count.index].zone_id
          evaluate_target_health = true
        }
      }
    }
  }
}

resource "aws_route53_traffic_policy_instance" "traffic_policy_instance" {
  name = "${local.primary_zone_name}-traffic-policy-instance"

  traffic_policy_id = aws_route53_traffic_policy.traffic_policy.id
  hosted_zone_id    = aws_route53_zone.primary.id
}
```

This configuration creates an AWS Route 53 zone, health check, records for the primary and secondary zones, a traffic policy, and a traffic policy instance to implement the Active-Passive Failover policy. The health check resource is named "primary_health_check" and uses the FQDN specified in the `local` block. The primary zone is named "primary". The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_route53_zone" "main" {
  name = "example53.com"
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = "primary.example53.com"
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "example53.com"
  type    = "A"
  ttl     = "60"
  records = ["192.0.2.101"]
  set_identifier = "primary-endpoint"

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.primary_health_check.id
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn              = "secondary.example53.com"
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
}

resource "aws_route53_record" "secondary_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "example53.com"
  type    = "A"
  ttl     = "60"
  records = ["192.0.2.102"] 
  set_identifier = "secondary-endpoint"

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.secondary_health_check.id
}

