    dns_name = aws_route53_zone.main.name
    traffic_policy_id = aws_route53_traffic_policy_instance.traffic_policy_instance.id
    weight = 100
  }
}

resource "aws_route53_traffic_policy_instance" "traffic_policy_instance" {
  name = "main_traffic_policy_instance"
  traffic_policy_id = aws_route53_traffic_policy.traffic_policy.id
  route_policy {
    route_policy_id = aws_route53_route_policy.route_policy.id
  }
}

resource "aws_route53_route_policy" "route_policy" {
