 Description:
This Terraform configuration will create an Amazon Route 53 zone named "primary" and set up a routing policy to navigate users to the least congested endpoint between the US East-1 and EU Central-1 regions.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "zone_name" {
  default = "primary"
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name
}

resource "aws_route53_health_check" "primary" {
  name = "${var.zone_name}_health_check"
  type = "IP"
  resource_path = "_internet"
  failure_threshold = 3
}

resource "aws_route53_record" "primary_us_east_1" {
  zone_id = aws_route53_zone.primary.id
  name    = aws_route53_health_check.primary.name
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary.id
    zone_id                = aws_route53_health_check.primary.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "primary_eu_central_1" {
  count = var.use_eu_central_1 == true ? 1 : 0

  zone_id = aws_route53_zone.primary.id
  name    = aws_route53_health_check.primary.name
  type    = "A"
  alias {
    name                   = aws_route53_health_check.primary.id
    zone_id                = aws_route53_health_check.primary.zone_id
    evaluate_target_health = true
  }
}

variable "use_eu_central_1" {
  default = false
}
```

In this configuration, the `aws` provider is set to the US East-1 region. A Route 53 zone named "primary" is created, and a health check resource is defined to monitor the endpoint's health. Two A records are created, one for the US East-1 region and another for the EU Central-1 region (if the `use_eu_central_1` variable is set to true). The A records use alias records to point to the health check resource, and they evaluate the target health to route users to the least congested endpoint.

