 Description:
This Terraform configuration will create an Amazon Route 53 zone named "primary" and set up a routing policy that utilizes a user's location to route them to the nearest endpoint within the US or EU continents.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "zone_name" {
  default = "primary"
}

variable "aliases" {
  type    = list(string)
  default = ["example.com"]
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name

  tags = {
    Name        = var.zone_name
    Environment = "production"
  }
}

resource "aws_route53_health_check" "example" {
  name = "example-health-check"
  type = "HTTP"

  resource_path = "/health"
  failure_threshold = 3

  request_interval = 15
  match_failure_response_code = "404"
}

resource "aws_route53_geolocation_config" "example" {
  name = "example-geolocation-config"

  geolocation_rule {
    name = "US-EU"

    priority = 1

    locations {
      name = "US"
      geolocation_weight = 10
    }

    locations {
      name = "EU"
      geolocation_weight = 90
    }
  }
}

resource "aws_route53_record" "primary" {
  count = length(var.aliases)

  zone_id = aws_route53_zone.primary.id
  name    = var.aliases[count.index]
  type    = "A"

  alias {
    name                   = aws_route53_traffic_flow.example.id
    zone_id                = aws_route53_traffic_flow.example.hosted_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_traffic_flow" "example" {
  name = "example-traffic-flow"

  geolocation_config_id = aws_route53_geolocation_config.example.id
  health_check_id      = aws_route53_health_check.example.id
}
```

This configuration creates an AWS provider in the `us-west-2` region, defines a Route 53 zone named "primary", and sets up a routing policy that prioritizes US locations with a weight of 10 and EU locations with a weight of 90. The configuration also creates health checks, geolocation configurations, and traffic flows to route traffic to the nearest endpoint within the US or EU continents.

