      weight = 5
    }
    traffic_distribution {
      id = aws_cloudfront_distribution.secondary.id
      weight = 5
    }
  }
}

resource "aws_route53_traffic_policy_instance" "primary" {
  name = "PrimaryTrafficPolicyInstance"
  traffic_policy_id = aws_route53_traffic_policy.primary.id
  route_53_record_set_ids = [aws_route53_record.example.id]
}

resource "aws_route53_record" "example" {
  zone_id = "ZONE_ID"
  name    = "example.com"
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.primary.domain_name
    zone_id                = aws_cloudfront_distribution.primary.hosted_zone_id
    evaluate_target_health = false
  }
}

data "aws_cloudfront_distribution" "primary" {
  id = var.cloudfront_distribution_id_primary
}

