    pod_subnet_range = "10.100.0.0/16"
    service_subnet_range = "10.96.0.0/12"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy
  ]
}

provider "kubectl" {
  host     = data.aws_eks_cluster.eks_cluster.endpoint
  token    = data.aws_eks_cluster_auth.eks_cluster.token
  version  = "1.21.0"
  client_certificate = base64decode(data.aws_eks_cluster.eks_cluster.certificate_authority.0.data)
  client_key     = base64decode(data.aws_eks_cluster.eks_cluster.service_account_private_key.0.private_key_pem)
}

data "aws_eks_cluster_auth" "eks_cluster" {
  name = aws_eks_cluster.eks_cluster.name
}

resource "null_resource" "create_kubeconfig" {
  provisioner "local-exec" {
    command = "kubectl config set-cluster ${local.eks_cluster_name} --server=${data.aws_eks_cluster.eks_cluster.endpoint} --certificate-authority=${data.aws_eks_cluster.eks_cluster.certificate_authority.0.data} --embed-certs=true"
  }

  provisioner "local-exec" {
    when    = create
    command = "kubectl config set-context ${local.eks_cluster_name} --cluster=${local.eks_cluster_name}"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "kubectl config delete-context ${local.eks_cluster_name}"
  }
}
```

