 Description:
This Terraform configuration sets up an AWS provider in the specified region, retrieves the current caller identity, fetches the latest stable ECR image, defines local variables, instantiates an EKS module for cluster setup, IAM policies, instance types, and node count, retrieves information about the created EKS cluster and its authentication data, configures Helm and Kubernetes providers using the EKS cluster's details for cluster communication.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

locals {
  image_tag = "stable"
  aws_tags   = {
    Name        = "eks-cluster"
    Terraform   = true
  }
  workspace_name = "eks-workspace"
}

module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "19.10.0"

  cluster_name    = local.workspace_name
  cluster_version = "1.23"

  subnets = [
    module.vpc.private_subnets[0]
    module.vpc.private_subnets[1]
  ]

  vpc_id     = module.vpc.vpc_id

  worker_groups_launch_template = {
    ami_type = "AL2_x86_64"

    default = {
      instance_type = "t3.medium"
      asg_desired_size = 3
      asg_min_size = 3
      asg_max_size = 3

      tags = local.aws_tags
    }
  }

  eks_managed_node_group_defaults = {
    ami_type = "AL2_x86_64"

    default_capacity_type = "ON_DEMAND"
    default_disk_size = 50
    default_instance_types = ["t3.medium"]
    default_node_group_size = 3
    default_subnets = [
      module.vpc.private_subnets[0]
      module.vpc.private_subnets[1]
    ]

    tags = local.aws_tags
  }

  eks_managed_node_groups = {
    default = {
      disk_size = 50
      instance_types = ["t3.medium"]
      node_group_name = "${local.workspace_name}-nodegroup"
      subnets = [
        module.vpc.private_subnets[0]
        module.vpc.private_subnets[1]
      ]
    }
  }

  eks_managed_node_group_defaults_disk_size = 50
  eks_managed_node_group_defaults_instance_types = ["t3.medium"]
  eks_managed_node_group_defaults_subnets = [
    module.vpc.private_subnets[0]
    module.vpc.private_subnets[1]
  ]

  eks_managed_node_group_defaults_tags = local.aws_tags

  cluster_enabled_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  cluster_addons = {
    coredns = {
      resolve_conflicts = "OVERWRITE"
      most_recent      = true
    }

    kube-proxy = {
      resolve_conflicts = "OVERWRITE"
      most_recent      = true
    }

    vpc-cni = {
      resolve_conflicts = "OVERWRITE"
      most_recent      = true
    }
  }

  cluster_tags = local.aws_tags
}

data "aws_ecr_repository" "repo" {
  name = "your-ecr-repo-name"
}

data "aws_ecr_image" "image" {
  repository_name = data.aws_ecr_repository.repo.name
  tag = local.image_tag
}

provider "helm" {
  kubernetes {
    host     = module.eks.cluster_endpoint
    token    = data.aws_eks_cluster_auth.this.token
    ca_cert  = base64decode(module.eks.cluster_certificate_authority_data)
    client_certificate = base64decode(module.eks.cluster_service_account_certificate)
    client_key = base64decode(module.eks.cluster_service_account_key)
  }
}

provider "kubernetes" {
  host     = module.eks.cluster_endpoint
  token    = data.aws_eks_cluster_auth.this.token
  client_certificate = base64decode(module.eks.cluster_certificate_authority_data)
  client_key = base64decode(module.eks.cluster_service_account_key)
}

data "aws_eks_cluster_auth" "this" {
  name = module.eks.cluster_id
}
```

