This Terraform configuration will create an IAM role for EKS Fargate profiles with the necessary policies for pod execution, attach the AmazonEKSFargatePodExecutionRolePolicy to the IAM role, define an AWS EKS Fargate profile for the 'kube-system' namespace, associate it with the EKS cluster, and specify the pod execution role ARN. Additionally, it will ensure that the specified subnets have the required resource tag for cluster association, and use a null_resource to patch the Kubernetes deployment 'coredns' in the 'kube-system' namespace, using the EKS cluster's endpoint, certificate authority, and authentication token for communication.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  cluster_name = "my-eks-cluster"
  pod_execution_role_name = "my-eks-fargate-pod-execution-role"
  subnets = ["subnet-12345678", "subnet-98765432"]
}

data "aws_eks_cluster" "cluster" {
  name = local.cluster_name
}

data "aws_eks_cluster_auth" "cluster" {
  name = local.cluster_name
}

resource "aws_iam_role" "fargate_profile_role" {
  name = local.pod_execution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "fargate_policy_attachment" {
  role       = aws_iam_role.fargate_profile_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
}

resource "aws_eks_fargate_profile" "fargate_profile" {
  cluster_name = data.aws_eks_cluster.cluster.name
  role = aws_iam_role.fargate_profile_role.arn
  selectors = {
    namespace = "kube-system"
  }
}

resource "aws_eks_subnet_id" "subnet_ids" {
  count = length(local.subnets)
  cluster_name = data.aws_eks_cluster.cluster.name
  subnet_id = local.subnets[count.index]
}

resource "aws_resource_tags" "eks_cluster_tag" {
  resources = aws_eks_subnet_id.subnet_ids.*.id

  tags = {
    Name = local.cluster_name
    kubernetes.io/cluster/${local.cluster_name} = "owned"
  }
}

provider "kubernetes" {
  host     = data.aws_eks_cluster.cluster.endpoint
  token    = data.aws_eks_cluster_auth.cluster.token
  client_certificate = base64decode(data.aws_eks_cluster.cluster.certificate_authority.0.data)
  client_key     = base64decode(data.aws_eks_cluster.cluster.service_account_private_key.0.private_key_pem)
}

resource "kubernetes_deployment" "coredns" {
  metadata {
    name = "kube-system/coredns"
  }

