      spec {
        container {
          name  = "coredns"
          image = "amazonecr-public.ecr.aws/dns-k8s-cache/coredns:1.8.4"
        }
      }
    }
  }
}

resource "null_resource" "patch_coredns" {
  provisioner "local-exec" {
    command = "kubectl apply -f patch-coredns.yaml"
  }

  triggers = {
    always_run = sha1(jsonencode([
      data.aws_eks_cluster.cluster.endpoint,
      data.aws_eks_cluster.cluster.certificate_authority.0.data,
      data.aws_eks_cluster.cluster.service_account_private_key.0.private_key_pem,
      aws_iam_role.fargate_profile_role.arn
    ]))
  }
}
