 Description:
This Terraform script will provision an AWS EKS cluster named "example" with specific VPC settings and associated IAM role. It will also include dependencies on IAM role policy attachments for proper resource management during creation and deletion. The script will output the cluster's endpoint and the kubeconfig certificate authority data.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  cluster_name = "example"
}

data "aws_caller_identity" "current" {}

data "aws_eks_cluster_policy_arns" "eks_cluster_policy_arns" {
  cluster_name = local.cluster_name
}

data "aws_iam_policy_document" "eks_cluster_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    effect  = "Allow"

    condition {
      audience = "https://sts.amazonaws.com/sessions/tokens.amazonaws.com"
      web_identity_token_source = "oidc.eks.us-west-2.amazonaws.com/id/{eks_cluster_arn}"
    }

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.eks_oidc_provider.arn]
    }
  }
}

resource "aws_iam_openid_connect_provider" "eks_oidc_provider" {
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [data.aws_eks_cluster.example.service_account_certificate_authority_data]
  url             = data.aws_eks_cluster.example.identity[0].oidc[0].issuer
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode(data.aws_iam_policy_document.eks_cluster_assume_role_policy.json)
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = data.aws_eks_cluster_policy_arns.eks_cluster_policy_arns.arns[0]
}

resource "aws_eks_cluster" "example" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = [
      "subnet-0123456789abcdef0",
      "subnet-0123456789abcdef1"
    ]
  }

  kubernetes_network_config {
    service_ipv4_cidr = "10.96.0.0/12"
  }

  depends_on = [
    aws_iam_openid_connect_provider.eks_oidc_provider,
    aws_iam_role_policy_attachment.eks_cluster_policy_attachment
  ]
}

output "cluster_endpoint" {
  value = aws_eks_cluster.example.endpoint
}

output "kubeconfig_ca_certificate" {
  value = base64encode(aws_eks_cluster.example.service_account_certificate_authority_data)
}
```

