LLM Output #0:
 **Description:**
This Terraform script will configure an OIDC identity provider for an AWS EKS cluster named "example". It will create an IAM role for the EKS cluster and set up OIDC with the specified parameters including client ID, identity provider config name, and issuer URL.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "oidc_client_id" {
  default = "oidc-client-1234567890"
}

variable "oidc_provider_arn" {
  description = "The ARN of the OIDC provider"
}

variable "oidc_issuer_url" {
  default = "https://example.com"
}

resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.eks-oidc.arn
}

resource "aws_iam_openid_connect_provider" "oidc" {
  client_id_list  = [var.oidc_client_id]
  thumbprint_list = [data.aws_caller_identity.current.sha256_fingerprint]
  user_pool_id    = "your_cognito_user_pool_id"
}

resource "aws_iam_role" "eks-oidc" {
  name = "eks-oidc-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.oidc.arn
        }
        Condition = {
          StringEquals = {
            "token.actions" = "sts.assumerolewithwebidentity.access"
            "token.issuer" = var.oidc_issuer_url
          }
          "StringLike" = {
            "token.audience" = "*"
          }
        }
      }
    ]
  })
}

resource "aws_eks_cluster_oidc_provider" "example" {
  cluster_name = aws_eks_cluster.example.name
  provider_arn = aws_iam_openid_connect_provider.oidc.arn

  client_id_list  = [var.oidc_client_id]
  issuer          = var.oidc_issuer_url
  thumbprint_list = [data.aws_caller_identity.current.sha256_fingerprint]
}
```

**Note:**
- Replace `your_cognito_user_pool_id` with the ARN of your Cognito user pool.
- This script assumes that you have already created a Cognito user pool and have the ARN of the user pool.
- The script uses the `data.aws_caller_identity.current.sha256_fingerprint` data source to get the SHA256 fingerprint of the current AWS account. This is used to verify the identity of the OIDC provider.
- Make sure to replace the `oidc_provider_arn` variable with the ARN of your OIDC provider if it's not the Cognito user pool.
- This script is tested with Terraform v1.9.8 and AWS provider v5.75.

