 Description:
This Terraform configuration will create an AWS IAM role named "demo" with the attribute name set to "eks-cluster-demo". The role will be designed to allow assuming roles for EKS services and will have the AmazonEKSClusterPolicy attached. Additionally, it will create an AWS EKS cluster named "demo" and configure its VPC with specified subnet IDs in the us-east-1 region.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  eks_cluster_name = "demo"
  eks_cluster_role_name = "eks-cluster-demo"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "eks_cluster" {
  name = local.eks_cluster_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_eks_cluster" "eks_cluster" {
  name = local.eks_cluster_name

  vpc_config {
    subnet_ids = [
      "subnet-0123456789abcdef0",
      "subnet-0123456789abcdef1"
    ]
  }

  role_arn = aws_iam_role.eks_cluster.arn

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]
}
```

In this configuration, the `aws` provider is set to the us-east-1 region. The IAM role "eks-cluster-demo" is created with the necessary policies and dependencies for the EKS cluster. The EKS cluster "demo" is created with the specified subnet IDs and the IAM role attached.

