This Terraform configuration will create an AWS IAM role named "example" for an Amazon EKS cluster. The IAM role will have an assume role policy that allows access for EKS services and will be attached to the AmazonEKSClusterPolicy. Additionally, an AWS EKS cluster named "example" will be created with a subnet and attached VPC, and the EKS cluster's endpoint private access will be set to false, while endpoint public access will be set to true.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  example_role_name = "example"
  example_cluster_name = "example"
}

data "aws_iam_policy" "eks_cluster_policy" {
  arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "eks_example_role" {
  name = local.example_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_example_role_policy_attachment" {
  role       = aws_iam_role.eks_example_role.name
  policy_arn = data.aws_iam_policy.eks_cluster_policy.arn
}

resource "aws_vpc" "example_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example_subnet" {
  vpc_id     = aws_vpc.example_vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_eks_cluster" "example_eks_cluster" {
  name     = local.example_cluster_name
  role_arn = aws_iam_role.eks_example_role.arn

  vpc_config {
    subnet_ids = [aws_subnet.example_subnet.id]
    security_group_ids = [aws_default_security_group.default.id]
  }

  endpoint_private_access = false
  endpoint_public_access = true
}
```

