LLM Output #0:
 Description:
This Terraform configuration sets up an AWS IAM role named 'eks-cluster' for an Amazon EKS cluster. The IAM role allows access for EKS services and attaches the AmazonEKSClusterPolicy to it. An AWS EKS cluster is created with a specified name and version, attached to a subnet and VPC in the us-east-1 region. The EKS cluster's endpoint private access is set to false, and endpoint public access is set to true.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  eks_cluster_name = "my-eks-cluster"
  eks_version      = "1.23"
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "default" {
  vpc_id = data.aws_vpc.default.id
}

resource "aws_iam_role" "eks-cluster" {
  name = local.eks_cluster_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks-cluster-AmazonEKSClusterPolicy" {
  role       = aws_iam_role.eks-cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_eks_cluster" "eks-cluster" {
  name     = local.eks_cluster_name
  version  = local.eks_version
  role_arn = aws_iam_role.eks-cluster.arn

  vpc_config {
    subnet_ids = data.aws_subnet_ids.default.ids
    security_group_ids = [aws_security_group.eks-cluster.id]
  }

  eks_managed_node_group_defaults {
    ami_type = "AL2_x86_64"
    instance_types = ["t3.medium"]
    disk_size = 50
  }

  tags = {
    Name = local.eks_cluster_name
  }

  endpoint_private_access = false
  endpoint_public_access = true
}

resource "aws_security_group" "eks-cluster" {
  name_prefix = local.eks_cluster_name
  vpc_id      = data.aws_vpc.default.id
}
```

Please note that this configuration assumes you have already created a VPC and security group in the us-east-1 region. If not, you can create them using the `aws_vpc` and `aws_security_group` resources respectively.

