This Terraform configuration will create an AWS S3 bucket named 'my_bucket' with forced destruction enabled, an S3 bucket metric named 'my_bucket_metric' to monitor the entire bucket's activity, and an S3 bucket object named 'my_object' with a specific key and content.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_name" {
  default = "my_bucket"
}

variable "object_key" {
  default = "my_object"
}

variable "object_content" {
  default = "This is my object content."
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = var.bucket_name
  force_destroy = true

  tags = {
    Name        = var.bucket_name
    Environment = "dev"
  }
}

resource "aws_s3_bucket_metric_configuration" "my_bucket_metric" {
  bucket = aws_s3_bucket.my_bucket.id

  metric_list {
    filter {
      prefix = ""
    }

    name = "ObjectCount"
    stat = "ObjectCount"
  }

  metric_list {
    filter {
      prefix = ""
    }

    name = "TotalSizeBytes"
    stat = "TotalSizeBytes"
  }
}

resource "aws_s3_object" "my_object" {
  bucket = aws_s3_bucket.my_bucket.id
  key    = var.object_key
  content = var.object_content
}
```

This configuration uses the AWS provider and creates an S3 bucket, S3 bucket metric, and an S3 bucket object within the specified region. The bucket and object are given default names, but these can be overridden by providing custom values for the `bucket_name`, `object_key`, and `object_content` variables. The S3 bucket is configured with forced destruction enabled for cleanup purposes. The S3 bucket metric is set up to monitor the entire bucket's activity by tracking the number of objects and the total size in bytes. Lastly, an S3 bucket object is created with the specified key and content.

