      "s3:ObjectCreated:*",
    ]

    filter_suffix {
      suffix = ".log"
    }
  }
}
```

Replace `your-unique-bucket-name` with a unique name for your S3 bucket. This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

