 **Description:**

This Terraform configuration sets up two AWS S3 buckets with specific access control and logging features. The first bucket will be private, while the second one will allow log delivery writes. Additionally, S3 bucket logging will be configured for the second bucket to send its logs to the first bucket, specifying a log file prefix.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
  version = "~> 5.75"
}

variable "bucket_name_private" {
  description = "Name of the private S3 bucket"
  default     = "private-bucket-terraform"
}

variable "bucket_name_log_delivery" {
  description = "Name of the S3 bucket for log delivery"
  default     = "log-delivery-bucket-terraform"
}

variable "log_file_prefix" {
  description = "Log file prefix for the log delivery bucket"
  default     = "s3-bucket-logs/"
}

resource "aws_s3_bucket" "private_bucket" {
  bucket = var.bucket_name_private
  acl    = "private"
}

resource "aws_s3_bucket" "log_delivery_bucket" {
  bucket = var.bucket_name_log_delivery
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_logging" "log_delivery_to_private" {
  bucket_name     = aws_s3_bucket.private_bucket.id
  target_bucket   = aws_s3_bucket.log_delivery_bucket.id
  target_prefix   = var.log_file_prefix
  filter_prefix   = ""
  filter_suffix   = ""
}
```

This configuration creates two S3 buckets with the specified names and access control settings. It also sets up S3 bucket logging for the log delivery bucket to send its logs to the private bucket with the provided log file prefix. The provider is configured for the `us-west-2` region and version `~> 5.75`.

