 Description:
This Terraform configuration will create a VPC with a public and private subnet, and an EC2 Fleet using Launch Templates for consistency. The Fleet will consist of 5 On-Demand and 4 Spot Instances running the latest AWS Linux 2.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  on_demand_count = 5
  spot_count      = 4
}

variable "ami" {
  default = "ami-0c94855ba95c574c8"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "terraform-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "terraform-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"

  tags = {
    Name = "terraform-private-subnet"
  }
}

resource "aws_iam_role" "ec2_launch_template" {
  name = "ec2_launch_template"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_launch_template" {
  name = "ec2_launch_template"
  role = aws_iam_role.ec2_launch_template.name
}

data "aws_ami" "aws_linux" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ami-ami-aws-linux-2-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["amazon"]
}

resource "aws_launch_template" "ec2_fleet" {
  name_prefix = "terraform-ec2-fleet"
  image_id     = data.aws_ami.aws_linux.id
  instance_type = "t3.small"
  key_name = "your-key-pair-name"
  iam_instance_profile = aws_iam_instance_profile.ec2_launch_template.name

  user_data = base64encode(<<-EOT
    #!/bin/bash
    yum update -y
    EOT
  )

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 8
      volume_type = "gp2"
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "terraform-ec2-instance"
    }
  }
}

resource "aws_ec2_fleet" "fleet" {
  launch_template {
    id = aws_launch_template.ec2_fleet.id
    version = aws_launch_template.ec2_fleet.latest_version
  }

  target_capacity_type = "spot"
  on_demand_target_capacity_basic = local.on_demand_count
  spot_target_capacity_basic = local.spot_count

  terminate_instances_prior_to_scale_in = true

  subnets = [aws_subnet.public.id, aws_subnet.private.id]
}
```

Please replace `"your-key-pair-name"` with the name of your existing AWS key pair.

This configuration assumes that you have already created an AWS key pair in the specified region. If not, you can create one using the AWS Management Console or Terraform.

