 Description:
This Terraform configuration will create a VPC with public and private subnets, and deploy three EC2 instances within an EC2 placement group using clustering. The VPC, subnets, and EC2 instances will be created in the us-west-2 region. IAM roles will be created as needed.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  private_subnets_cidr_blocks = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  public_subnets_cidr_blocks  = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "terraform-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnets_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(local.private_subnets_cidr_blocks, count.index)
  availability_zone = "${data.aws_availability_zones.available.names[count.index]}"

  tags = {
    Name = "terraform-private-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count             = length(local.public_subnets_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(local.public_subnets_cidr_blocks, count.index)
  availability_zone = "${data.aws_availability_zones.available.names[count.index]}"

  map_public_ip_on_launch = true

  tags = {
    Name = "terraform-public-subnet-${count.index + 1}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_eip" "eip" {
  count = 3

  vpc = true
}

resource "aws_placement_group" "pg" {
  name = "terraform-pg"
  strategy = "cluster"

  availability_zone_count = 3

  tags = {
    Name = "terraform-pg"
  }
}

resource "aws_instance" "ec2" {
  count         = 3
  ami           = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type - ami-0c94855ba95c574c8
  instance_type = "t2.micro"

  subnet_id              = element(aws_subnet.public.*.id, count.index)
  placement_group_id     = aws_placement_group.pg.id
  key_name               = "your-key-pair-name"
  associate_public_ip_address = true

  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              EOF

  tags = {
    Name = "terraform-ec2-${count.index + 1}"
  }

  connection {
    type        = "ssh"
    user        = "ec2-user"
    private_key = file("~/.ssh/your-private-key")
    host        = self.public_ip
  }

  provisioner "remote-exec" {
    inline = [
      "sudo yum install -y httpd",
      "sudo service httpd start",
      "sudo chkconfig httpd on"
    ]
  }

  provisioner "local-exec" {
    command = "echo ${self.public_ip} > ec2_ips.txt"
  }
}
```

Please replace `"your-key-pair-name"` with the name of your existing key pair in AWS, and `"~/.ssh/your-private-key"` with the path to your private key file on your local machine.

This configuration assumes that you have already created an IAM user with the necessary permissions to manage resources in the us-west-2 region. If you don't have an IAM user with the required permissions, you will need to create one and update the `aws_config.json` file accordingly.

