```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "production"
  }
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "available" {
  vpc_id = data.aws_vpc.default.id

  filters {
    tag:name
    values = ["memcached-subnet"]
  }
}

resource "aws_security_group" "memcached_sg" {
  name        = "memcached_sg"
  description = "Security group for Memcached cluster"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "memcached_sg" })
}

resource "aws_elasticache_subnet_group" "memcached_subnet_group" {
  name       = "memcached-subnet-group"
  subnet_ids = data.aws_subnet_ids.available.ids

  tags = merge(local.common_tags, { Name = "memcached-subnet-group" })
}

resource "aws_elasticache_cluster" "memcached_cluster" {
  cluster_id           = "memcached-cluster"
  engine               = "memcached"
  node_type            = "cache.t2.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.memcached1.6"
  port                 = 11211
  security_groups      = [aws_security_group.memcached_sg.id]
  subnet_group_name    = aws_elasticache_subnet_group.memcached_subnet_group.name

  tags = merge(local.common_tags, { Name = "memcached-cluster" })
}
```

This configuration creates a Memcached cluster in the `us-west-2` region with a single cache node. The Memcached cluster uses the default Memcached 1.6 parameter group and is accessible via port 11211. The security group allows incoming traffic from any IP address on port 11211. The VPC, subnet, and security group are determined by the available resources with the tag `memcached-subnet`.

