 Description: This Terraform configuration will create a Redshift cluster with 2 nodes and limit the concurrency scaling to 60 minutes. The configuration uses the AWS provider and includes IAM roles as needed.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  redshift_cluster_identifier = "my-redshift-cluster"
  redshift_cluster_subnet_group_name = "my-redshift-subnet-group"
  redshift_cluster_vpc_security_group_ids = ["sg-0123456789abcdef0"]
  redshift_cluster_master_username = "my-redshift-master-user"
  redshift_cluster_master_password = "MySecurePassword123!"
  redshift_cluster_node_type = "dc1.large"
  redshift_cluster_concurrency_scaling_max_number_of_nodes = 2
  redshift_cluster_concurrency_scaling_min_number_of_nodes = 2
  redshift_cluster_concurrency_scaling_time_interval_minutes = 60
}

data "aws_iam_role" "redshift_iam_for_logging" {
  name = "AWSServiceRoleForAmazonRedshift"
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = local.redshift_cluster_identifier
  database_name = "mydb"
  master_username = local.redshift_cluster_master_username
  master_password = local.redshift_cluster_master_password
  node_type = local.redshift_cluster_node_type
  cluster_type = "single-node"
  vpc_security_group_ids = local.redshift_cluster_vpc_security_group_ids
  cluster_subnet_group_name = local.redshift_cluster_subnet_group_name

  concurrency_scaling {
    max_number_of_nodes = local.redshift_cluster_concurrency_scaling_max_number_of_nodes
    min_number_of_nodes = local.redshift_cluster_concurrency_scaling_min_number_of_nodes
    time_interval_minutes = local.redshift_cluster_concurrency_scaling_time_interval_minutes
  }

  iam_roles {
    db = aws_iam_role.redshift_iam_for_logging
    logging = aws_iam_role.redshift_iam_for_logging
  }
}

resource "aws_redshift_cluster_parameter_group" "main" {
  name = "my-redshift-cluster-parameter-group"
  family = "redshift-default-latest"

  parameter {
    name = "work_mem"
    value = "256MB"
  }

  parameter {
    name = "maintenance_track_table_size_threshold"
    value = "10GB"
  }
}

resource "aws_redshift_cluster" "scaled_cluster" {
  count = aws_redshift_cluster.main.concurrency_scaling.max_number_of_nodes - aws_redshift_cluster.main.concurrency_scaling.min_number_of_nodes

  cluster_identifier = "${local.redshift_cluster_identifier}-${count.index + 1}"
  database_name = aws_redshift_cluster.main.database_name
  master_username = aws_redshift_cluster.main.master_username
  master_password = aws_redshift_cluster.main.master_password
  node_type = local.redshift_cluster_node_type
  vpc_security_group_ids = local.redshift_cluster_vpc_security_group_ids
  cluster_subnet_group_name = local.redshift_cluster_subnet_group_name

  iam_roles {
    db = aws_iam_role.redshift_iam_for_logging
    logging = aws_iam_role.redshift_iam_for_logging
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes = [
      cluster_identifier
    ]
  }
}
```

This configuration creates a Redshift cluster with the specified parameters and scales the number of nodes based on the concurrency scaling settings. It also creates a parameter group to modify some cluster parameters. The IAM role for logging is reused across all nodes.

