```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  redshift_cluster_identifier = "my-redshift-cluster"
  redshift_cluster_snapshot_identifier = "my-redshift-cluster-snapshot"
  redshift_cluster_snapshot_retention_period = 7
}

data "aws_iam_policy_document" "redshift_cluster_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "redshift_cluster_role" {
  name = "${local.redshift_cluster_identifier}-role"

  assume_role_policy = jsonencode(data.aws_iam_policy_document.redshift_cluster_assume_role_policy.json)
}

