  name = "${local.redshift_cluster_identifier}-policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:CreateCluster",
          "redshift:DeleteCluster",
          "redshift:DescribeClusters",
          "redshift:DescribeClusterParameters",
          "redshift:DescribeClusterSecurityGroups",
          "redshift:DescribeClusterSnapshots",
          "redshift:DescribeClusterSubnetGroups",
          "redshift:DescribeEventCategories",
          "redshift:DescribeEvents",
          "redshift:DescribeParameterGroups",
          "redshift:DescribeParameters",
          "redshift:DescribeReservedNodeOfferings",
          "redshift:DescribeReservedNodes",
          "redshift:DescribeSnapshots",
          "redshift:DescribeUserGroups",
          "redshift:DescribeUsers",
          "redshift:ModifyCluster",
          "redshift:ResetClusterPassword",
          "redshift:StartCluster",
          "redshift:StopCluster"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_cluster_role_policy_attachment" {
  role       = aws_iam_role.redshift_cluster_role.name
  policy_arn = aws_iam_policy.redshift_cluster_policy.arn
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier      = local.redshift_cluster_identifier
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = "password"
  node_type               = "dc1.large"
  cluster_type            = "single-node"
  vpc_security_group_ids   = [aws_security_group.redshift_cluster_sg.id]
  subnet_group_name       = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_cluster_parameter_group.main.name
