  cluster_snapshot_retention_period = local.redshift_cluster_snapshot_retention_period
  source_cluster_identifier = aws_redshift_cluster.main.id
}

resource "aws_redshift_cluster_parameter_group" "main" {
  name        = local.redshift_cluster_identifier
  family      = "redshift-high-memory-tx-heavy-2-node-64"
  description = "Parameter group for ${local.redshift_cluster_identifier}"
}

resource "aws_redshift_subnet_group" "main" {
  name        = local.redshift_cluster_identifier
  subnet_ids  = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
  tags = {
    Name = local.redshift_cluster_identifier
  }
