resource "aws_security_group" "redshift_cluster_sg" {
  name        = "${local.redshift_cluster_identifier}-sg"
  description = "Security group for ${local.redshift_cluster_identifier}"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
