 Description: This Terraform configuration sets up a highly available Amazon Redshift cluster in the us-east-1 region, spanning across two Availability Zones (us-east-1a and us-east-1b) for improved fault tolerance and data durability. The configuration includes an IAM role for the Redshift cluster, a VPC, a subnet in each Availability Zone, a Redshift cluster, and a security group.

```hcl
provider "aws" {
  region = "us-east-1"
  version = "~> 5.75"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "production"
  }
}

variable "redshift_cluster_identifier" {
  default = "my-redshift-cluster"
}

variable "redshift_cluster_master_username" {
  default = "my-redshift-user"
}

variable "redshift_cluster_master_password" {
  type = sensitivestring
}

variable "redshift_subnet_group_name" {
  default = "my-redshift-subnet-group"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = merge(local.common_tags, { Name = "my-vpc" })
}

resource "aws_subnet" "az1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = merge(local.common_tags, { Name = "subnet-az1" })
}

resource "aws_subnet" "az2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = merge(local.common_tags, { Name = "subnet-az2" })
}

resource "aws_redshift_subnet_group" "main" {
  name        = var.redshift_subnet_group_name
  subnet_ids  = [aws_subnet.az1.id, aws_subnet.az2.id]

  tags = local.common_tags
}

resource "aws_iam_role" "redshift" {
  name = "my-redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = var.redshift_cluster_identifier
  database_name = "mydb"
  master_username = var.redshift_cluster_master_username
  master_password = var.redshift_cluster_master_password
  node_type = "dc1.large"
  cluster_type = "single-node"
  vpc_security_group_ids = [aws_security_group.main.id]
  subnet_group_name = aws_redshift_subnet_group.main.name

  tags = local.common_tags
}

resource "aws_security_group" "main" {
  name_prefix = "my-redshift-sg"

  ingress {
    from_port = 5439
    to_port = 5439
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}
```

This configuration creates a VPC, two subnets in different Availability Zones, a Redshift subnet group, an IAM role for the Redshift cluster, a Redshift cluster, and a security group for the Redshift cluster. The Redshift cluster is a single-node cluster for simplicity, but you can modify the `cluster_type` to create a multi-node cluster if needed.

