  policy_arn = data.aws_iam_policy.redshift_cluster_policy.arn
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = local.redshift_cluster_name
  database_name = "mydb"
  master_username = "admin"
  master_password = "MySecretPassword123!"
  node_type = "dc1.large"
  cluster_type = "single-node"
  number_of_nodes = 2
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  cluster_security_groups = [aws_security_group.redshift_sg.name]
  iam_roles = [aws_iam_role.redshift_cluster_role.arn]
}

resource "aws_security_group" "redshift_sg" {
  name_prefix = local.redshift_cluster_name
  vpc_id = data.aws_vpc.default.id

  ingress {
    from_port = 5439
    to_port = 5439
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
}
```

In this configuration, the `aws_iam_role` resource creates an IAM role for the Redshift cluster, and the `aws_iam_role_policy_attachment` resource attaches the specified policy to the IAM role. The `aws_redshift_cluster` resource creates the Redshift cluster, and the `aws_security_group` resource creates a security group for the Redshift cluster. The `aws_security_group` resource allows incoming traffic on port 5439 from any IP address. The `data.aws_vpc.default` data source is used to get the default VPC ID for the region.

