 Description:
This Terraform configuration will create an AWS Lambda function named "example_lambda" and set up an API Gateway to invoke it. The Lambda function will be written in Python and will be triggered by an HTTP API.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lambda_name = "example_lambda"
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "lambda_function.py"
  output_path = "lambda_function_payload.zip"
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.lambda_name}_exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "example_lambda" {
  function_name = local.lambda_name
  runtime      = "python3.8"
  role         = aws_iam_role.lambda_exec.arn
  handler      = "lambda_function.lambda_handler"
  filename     = data.archive_file.lambda_zip.output_path

  environment {
    variables = {
      key1 = "value1"
      key2 = "value2"
    }
  }
}

resource "aws_api_gateway_rest_api" "example_api" {
  name        = "example_api"
  description = "API for example_lambda"
}

resource "aws_api_gateway_resource" "example_resource" {
  rest_api_id = aws_api_gateway_rest_api.example_api.id
  parent_id   = aws_api_gateway_rest_api.example_api.root_resource_id
  path_part   = "example"
}

resource "aws_api_gateway_method" "example_method" {
  rest_api_id   = aws_api_gateway_rest_api.example_api.id
  resource_id   = aws_api_gateway_resource.example_resource.id
  http_method   = "ANY"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "example_integration" {
  rest_api_id             = aws_api_gateway_rest_api.example_api.id
  resource_id             = aws_api_gateway_resource.example_resource.id
  http_method             = aws_api_gateway_method.example_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.example_lambda.invoke_arn
}

resource "aws_api_gateway_deployment" "example_deployment" {
  rest_api_id = aws_api_gateway_rest_api.example_api.id
  stage_name  = "prod"

  lifecycle {
    create_before_destroy = true
  }
}

output "api_gateway_url" {
  value = aws_api_gateway_deployment.example_deployment.invoke_url
}
```

This configuration creates an IAM role for the Lambda function, packages the Python script as a ZIP file, creates the Lambda function, sets up an API Gateway, and deploys the API Gateway to a production stage. The output variable `api_gateway_url` provides the URL to invoke the Lambda function through the API Gateway.

