 Description: This Terraform configuration creates an AWS Lambda function alias. The alias will point to an existing Lambda function.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "lambda_function_name" {
  default = "my-lambda-function"
}

variable "alias_name" {
  default = "my-alias"
}

resource "aws_lambda_alias" "lambda_alias" {
  function_name      = var.lambda_function_name
  name               = var.alias_name
  function_version   = aws_lambda_function_version.latest.version

  depends_on = [aws_lambda_function_version.latest]
}

resource "aws_lambda_function_version" "latest" {
  function_name = var.lambda_function_name
  qualifier    = "$LATEST"
}
```

This configuration assumes that the Lambda function with the name `my-lambda-function` already exists in the specified AWS region. If it doesn't, you'll need to create it separately using the AWS Management Console, AWS CLI, or another Terraform configuration. The alias `my-alias` will point to the latest version of the Lambda function.

