  policy_arn = aws_iam_policy.lambda_ec2_exec.arn
}

resource "aws_lambda_function" "test_lambda" {
  function_name = "test_lambda"
  runtime       = var.lambda_runtime
  handler       = var.lambda_handler
  role          = aws_iam_role.lambda_exec.arn

  filename      = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
}

resource "aws_ec2_instance" "test_ec2" {
  ami           = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type - ami-0c94855ba95c574c8
  instance_type = "t2.micro"

  lifecycle {
    ignore_changes = [
      ami
    ]
  }

  provisioner "local-exec" {
    command = "echo 'Triggering Lambda function for new EC2 instance' && aws lambda invoke --function-name ${aws_lambda_function.test_lambda.function_name} --payload '{}' output.json"

    when    = create
  }
}
