This Terraform configuration will create an Amazon Kinesis Data Stream that serves as a streaming destination for a specified DynamoDB table. It will also create the necessary IAM roles for the Kinesis and DynamoDB services to access each other.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "dynamodb_table_name" {
  description = "The name of the DynamoDB table to stream data to"
  default     = "my-dynamodb-table"
}

variable "kinesis_stream_name" {
  description = "The name of the Kinesis Data Stream"
  default     = "my-kinesis-stream"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "kinesis_to_dynamodb" {
  name = "kinesis_to_dynamodb"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_to_dynamodb_policy" {
  name = "kinesis_to_dynamodb"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:dynamodb:${aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/${var.dynamodb_table_name}"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kinesis_to_dynamodb_attachment" {
  role       = aws_iam_role.kinesis_to_dynamodb.name
  policy_arn = aws_iam_policy.kinesis_to_dynamodb_policy.arn
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name             = var.kinesis_stream_name
  shard_count      = 1
  encryption_type  = "AES256"
  retention_period = 24 * 60 * 60

  shard_level_consumer_configuration {
    max_consumer_count = 1
  }

  kinesis_firehose_destination_configuration {
    destination_arn = aws_dynamodb_table.dynamodb_table.id
    buffer_size     = 128
    compression_format = "UNCOMPRESSED"
  }
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = var.dynamodb_table_name
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}
```

This configuration creates an AWS Kinesis Data Stream and a DynamoDB table, and sets up the necessary IAM roles and policies for the Kinesis Data Stream to write data to the DynamoDB table. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

