provider "aws" {
  region = "us-east-1"
}

locals {
  table_name = "my_global_table"
  replica_region = "us-west-2"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "dynamodb_replicator" {
  name = "${local.table_name}_replicator_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_dynamodb_global_table" "global_table" {
  name = local.table_name
  hash_key = "id"

  replica_regions = [local.replica_region]

  attribute {
    name = "id"
    type = "S"
  }

  global_secondary_index {
    index_name = "gsi_1"
    partition_key_name = "partition_key"
    sort_key_name = "sort_key"

    projection_type = "ALL"

    attribute {
      name = "partition_key"
      type = "S"
    }

    attribute {
      name = "sort_key"
      type = "S"
    }
  }

  tags = {
    Name = local.table_name
  }
}

resource "aws_dynamodb_table_replica" "replica" {
  global_table_name = aws_dynamodb_global_table.global_table.name
  replica_table_name = "${local.table_name}_replica_${local.replica_region}"
  replica_region_name = local.replica_region

  replica_table_arn = aws_dynamodb_table.replica.arn

  replica_table_provisioned_throughput {
    read_capacity = 5
    write_capacity = 5
  }
}

resource "aws_dynamodb_table" "replica" {
  name = "${local.table_name}_replica_${local.replica_region}"
  read_capacity = 5
  write_capacity = 5
  hash_key = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${local.table_name}_replica_${local.replica_region}"
  }
}

resource "aws_dynamodb_table_replica_permissions" "replica_permissions" {
  global_table_name = aws_dynamodb_global_table.global_table.name
  replica_table_name = aws_dynamodb_table.replica.name

  replica_table_arn = aws_dynamodb_table.replica.arn

  actions = [
    "dynamodb:GetItem",
    "dynamodb:PutItem",
    "dynamodb:UpdateItem",
    "dynamodb:DeleteItem",
    "dynamodb:DescribeTable",
    "dynamodb:Query",
    "dynamodb:Scan",
    "dynamodb:BatchGetItem",
    "dynamodb:BatchWriteItem",
    "dynamodb:UpdateTable",
    "dynamodb:CreateTable",
    "dynamodb:DeleteTable"
  ]

  iam_role_arn = aws_iam_role.dynamodb_replicator.arn
}
```

This configuration creates a DynamoDB Global Table with a replica in the specified region, and also creates an IAM role for DynamoDB replicator to allow the necessary access. The Global Table has a single Global Secondary Index (GSI) defined. The replica table is created in the specified region and is provisioned with the same read and write capacity as the Global Table. The replica table permissions are set to allow all DynamoDB actions using the IAM role created for the replicator.

