 Description:
This Terraform configuration will create a DAX (Amazon DynamoDB Accelerator) cluster with one replica and node type `dax.r4.large` in the AWS US East (N. Virginia) region. It will also create IAM roles as needed.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  dax_cluster_name = "my-dax-cluster"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "dax_role" {
  name = "${local.dax_cluster_name}-dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_dax_cluster" "dax_cluster" {
  cluster_name          = local.dax_cluster_name
  replication_factor    = 1
  node_type             = "dax.r4.large"
  hash_key              = "AllItems"
  range_key             = "MyRangeKey"
  read_capacity         = 5
  write_capacity        = 5
  auto_discover_infra_stack_arn = aws_dax_workload_subscription.dax_workload.arn

  tags = {
    Name = local.dax_cluster_name
  }

  iam_role_arn = aws_iam_role.dax_role.arn
}

resource "aws_dax_workload_subscription" "dax_workload" {
  cluster_arn = aws_dax_cluster.dax_cluster.arn
  subscription_name = "default"

  tags = {
    Name = "default"
  }
}
```

This configuration uses the AWS provider and creates a DAX cluster with the specified parameters. It also creates an IAM role for the DAX cluster and a workload subscription. The default region is `us-east-1`. The `aws_caller_identity` data source is used to get the account ID for the IAM role ARN.

