  cidr_block = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
}

resource "aws_dax_subnet_group" "dax_subnet_group" {
  name        = local.dax_subnet_group_name
  subnet_ids  = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
}
```

This configuration creates a VPC with two subnets in different availability zones, and then creates a custom DAX subnet group using those subnets. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

