 Description:
This Terraform configuration creates an AWS SageMaker Domain. The domain will be named "my-sagemaker-domain" and will be located in the us-west-2 region. IAM roles will be created for the domain and the notebook instance.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "domain_name" {
  default = "my-sagemaker-domain"
}

resource "aws_sagemaker_domain" "domain" {
  name        = var.domain_name
  role_arn    = data.aws_iam_role.domain_role.arn

  tags = {
    Name        = var.domain_name
    Environment = "dev"
  }
}

data "aws_iam_role" "domain_role" {
  name = "AWSServiceRoleForSageMaker"
}

resource "aws_iam_role" "notebook_instance_role" {
  name = "my-sagemaker-notebook-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "notebook_instance_policy_attachment" {
  role       = aws_iam_role.notebook_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
}
```

This configuration creates an AWS SageMaker Domain named "my-sagemaker-domain" in the us-west-2 region. It also creates an IAM role for the domain and a separate IAM role for the notebook instance. The notebook instance role has the AmazonSageMakerFullAccess policy attached.

