```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  notebook_instance_name = "my-sagemaker-notebook"
}

variable "vpc_id" {
  default = "vpc-12345678"
}

variable "subnet_id" {
  default = "subnet-12345678"
}

variable "security_group_id" {
  default = "sg-12345678"
}

variable "iam_role_name" {
  default = "sagemaker-notebook-execution-role"
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "my-vpc"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id     = var.vpc_id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "my-subnet"
  }
}

resource "aws_security_group" "security_group" {
  name        = var.security_group_id
  description = "Security group for SageMaker Notebook Instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "iam_for_sagemaker" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_sagemaker_notebook_instance" "notebook_instance" {
  name_prefix          = local.notebook_instance_name
  instance_type        = "ml.t2.medium"
  vpc_id               = var.vpc_id
  subnet_id            = var.subnet_id
  security_group_ids   = [var.security_group_id]
  role_arn             = aws_iam_role.iam_for_sagemaker.arn

  lifecycle {
    create_before_destroy = true
  }
}
```

This configuration creates a VPC, Subnet, Security Group, IAM Role, and an AWS SageMaker Notebook Instance using the specified variables. The provider is set to AWS and the region is us-west-2. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

