 Description:
This Terraform configuration will create a VPC with two subnets (public and private), an EC2 Fleet with a mix of On-Demand and Spot Instances using the latest Amazon Linux 2 AMI. The VPC, subnets, and EC2 Fleet will be deployed in the us-west-2 region.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  ami_id = "ami-0c94855ba95c574c8" // Latest Amazon Linux 2 AMI ID
  on_demand_instances = 5
  spot_instances = 4
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2_fleet_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_fleet_profile" {
  name = "ec2_fleet_profile"
  role = aws_iam_role.ec2_fleet_role.name
}

resource "aws_launch_template" "ec2_fleet" {
  name = "ec2_fleet"
  image_id = local.ami_id
  instance_type = "t3.small"
  key_name = "your_key_pair_name"
  iam_instance_profile = aws_iam_instance_profile.ec2_fleet_profile.name

  user_data = base64encode(<<-EOT
    #!/bin/bash
    yum update -y
    EOT
  )
}

resource "aws_ec2_fleet" "fleet" {
  launch_template_specification {
    launch_template_id = aws_launch_template.ec2_fleet.id
    version = "$(aws_launch_template.ec2_fleet.latest_version)"
  }

  target_capacity_specification {
    on_demand_capacity_specification {
      maximum_capacity = local.on_demand_instances
      minimum_capacity = local.on_demand_instances
    }

    spot_capacity_specification {
      maximum_capacity = local.spot_instances
      minimum_capacity = local.spot_instances
    }
  }

  subnets = [aws_subnet.public.id, aws_subnet.private.id]
}
```

Please replace `"your_key_pair_name"` with the name of your existing key pair in AWS.

This configuration assumes that you have already created a key pair in your AWS account. If not, you can create one using the AWS Management Console or the AWS CLI.

