 Description:
This Terraform configuration will create an AWS VPC with one public subnet for a webserver, and two private subnets for an application server and a relational database. The VPC will have an Internet Gateway and NAT Gateways for the private subnets. IAM roles will be created for the webserver and database instances to allow them to access the necessary AWS resources.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block_1" {
  default = "10.0.2.0/24"
}

variable "private_subnet_cidr_block_2" {
  default = "10.0.3.0/24"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags       = merge(local.common_tags, { Name = "main-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
  tags       = local.common_tags
}

resource "aws_subnet" "private_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.private_subnet_cidr_block_1
  tags       = local.common_tags
}

resource "aws_subnet" "private_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.private_subnet_cidr_block_2
  tags       = local.common_tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = local.common_tags
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_nat_gateway" "nat_gateway_1" {
  subnet_id     = aws_subnet.private_1.id
  alloc_public_ip = true
  tags = local.common_tags
}

resource "aws_nat_gateway" "nat_gateway_2" {
  subnet_id     = aws_subnet.private_2.id
  alloc_public_ip = true
  tags = local.common_tags
}

resource "aws_route" "private_to_nat" {
  route_table_id         = aws_subnet.private_1.route_table_id
  nat_gateway_id         = aws_nat_gateway.nat_gateway_1.id
  destination_cidr_block = "0.0.0.0/0"
}

resource "aws_route" "private_to_nat_2" {
  route_table_id         = aws_subnet.private_2.route_table_id
  nat_gateway_id         = aws_nat_gateway.nat_gateway_2.id
  destination_cidr_block = "0.0.0.0/0"
}
```

This configuration creates the necessary resources to launch a webserver in the public subnet, an application server in the first private subnet, and a relational database in the second private subnet. The webserver and database instances will require IAM roles to be created, which can be added to this configuration by following the official AWS documentation on creating IAM roles for EC2 instances.

