 Description:
This Terraform configuration will create a Managed MSK (Apache Kafka) cluster with 3 broker nodes in the us-east1 region. It will include an IAM role for the MSK cluster and necessary AWS provider configuration.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  msk_cluster_name = "my-msk-cluster"
}

data "aws_iam_policy_document" "msk_cluster_policy" {
  statement {
    actions = ["kafka:*"]
    resources = [
      "*",
    ]
    effect = "Allow"
  }
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "${local.msk_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "managed-msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                 = local.msk_cluster_name
  kafka_version                = "2.8.0"
  number_of_broker_nodes       = 3
  open_monitoring_dashboard    = true
  open_mixed_network_access    = true
  vpc_id                       = data.aws_vpc.default.id
  subnet_ids                   = data.aws_subnet_ids.default.ids

  kafka_configs = {
    "zookeeper.connect.string" = "${aws_msk_zookeeper_connect.zookeeper.id}.${aws_msk_zookeeper_connect.zookeeper.zone_id}"
  }

  security_configuration_name = "MSK_SC_Standard_1_0_0"

  tags = {
    Name = local.msk_cluster_name
  }

  iam_role_arn = aws_iam_role.msk_cluster_role.arn

  depends_on = [
    aws_iam_role_policy_attachment.msk_cluster_policy_attachment
  ]
}

resource "aws_iam_role_policy_attachment" "msk_cluster_policy_attachment" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnet_ids" "default" {
  vpc_id = data.aws_vpc.default.id
}

data "aws_msk_zookeeper_connect" "zookeeper" {
  cluster_name = aws_msk_cluster.msk_cluster.id
}
```

This configuration assumes that you have a default VPC and subnets in the us-east1 region. If not, you will need to create them or modify the configuration accordingly.

