LLM Output #0:
 Description: This Terraform configuration will create a managed Apache Kafka MSK cluster in the us-east1 region, and set up logging to a CloudWatch Log Group.

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  msk_cluster_name = "my-msk-cluster"
  log_group_name   = "my-msk-cluster-log-group"
}

data "aws_iam_policy_document" "msk_cluster_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["arn:aws:kafka:us-east-1:${data.aws_caller_identity.current.account_id}:cluster/${local.msk_cluster_name}"]
    }
  }
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "${local.msk_cluster_name}-role"

  assume_role_policy = data.aws_iam_policy_document.msk_cluster_assume_role_policy.json
}

resource "aws_msk_cluster" "msk_cluster" {
  name                  = local.msk_cluster_name
  kafka_version         = "2.8.0"
  number_of_brokers     = 3
  number_of_replicas    = 1
  vpc_id                = module.vpc.vpc_id
  subnet_ids            = module.vpc.private_subnets
  security_group_ids    = [aws_security_group.msk_cluster_sg.id]
  open_monitoring       = true
  open_maintainance_window = true

  logging_info {
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.log_group.arn
  }
}

resource "aws_security_group" "msk_cluster_sg" {
  name_prefix = local.msk_cluster_name
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "3.0.0"

  name = local.msk_cluster_name
  cidr = "10.0.0.0/16"

  azs             = ["us-east-1a", "us-east-1b", "us-east-1c"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  public_subnets  = []
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = local.log_group_name
  retention_in_days = 14
}
```

In this configuration, we use the `terraform-aws-modules/vpc` module to create a VPC with the required subnets. The MSK cluster is created with the specified number of brokers and replicas, and logging is configured to send logs to a CloudWatch Log Group. An IAM role is created for the MSK cluster to allow it to assume the role. The security group allows incoming traffic on port 9092 from any IP address.

