 Description: This Terraform configuration will create a managed Apache Kafka MSK cluster in the `us-east1` region, with logging configured to send messages to an Amazon Kinesis Data Firehose stream.

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  firehose_name = "msk-logs-firehose"
  msk_cluster_id = "msk-cluster-1"
}

data "aws_iam_policy_document" "firehose_kafka_policy" {
  statement {
    actions = ["kinesis:PutRecord"]
    resources = ["arn:aws:kinesis:${data.aws_region.current.name}:*:stream/*"]

    principals {
      type        = "AWS"
      identifiers = [aws_msk_cluster.msk_cluster.arn]
    }
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose" {
  name        = local.firehose_name
  destination = "extended_s3"

  s3_configuration {
    role_arn           = aws_iam_role.firehose_to_s3.arn
    bucket_arn         = aws_s3_bucket.logs_bucket.arn
    buffer_size        = 128
    compression_format = "UNCOMPRESSED"
  }
}

resource "aws_iam_role" "firehose_to_s3" {
  name = "firehose_to_s3_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_kafka_policy" {
  name        = "firehose_kafka_policy"
  description = "Policy for Kinesis Firehose to put records to Kafka"
  path        = "/"

  policy = data.aws_iam_policy_document.firehose_kafka_policy.json
}

resource "aws_iam_role_policy_attachment" "firehose_to_s3_policy" {
  role       = aws_iam_role.firehose_to_s3.name
  policy_arn = aws_iam_policy.firehose_kafka_policy.arn
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                 = local.msk_cluster_id
  kafka_version                 = "2.7"
  create_iam_resources         = true
  open_monitoring_dashboard    = true
  open_messaging_endpoint      = true
  vpc_id                        = aws_vpc.main.id
  subnet_ids                   = [aws_subnet.private_subnet_1.id, aws_subnet.private_subnet_2.id]
  bootstrap_topics              = ["msk-logs-topic"]

  logging_configuration {
    log_type = "Broker"
    destination {
      firehose_delivery_stream_arn = aws_kinesis_firehose_delivery_stream.firehose.arn
    }
  }
}

resource "aws_s3_bucket" "logs_bucket" {
  bucket = "msk-logs-bucket"
  acl    = "private"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
}
```

This configuration creates an AWS VPC, two private subnets, an S3 bucket for Firehose logs, an IAM role for Firehose to write to S3, an IAM policy for Firehose to put records to Kafka, a Kinesis Data Firehose delivery stream, and an MSK cluster with logging configured to send messages to the Firehose stream.

