      partitions = 1
    }
  ]
  vpc_id                        = "vpc-xxxxxxxx"
  subnet_ids                    = ["subnet-xxxxxxxx", "subnet-xxxxxxxx"]
  security_group_ids            = ["sg-xxxxxxxx", "sg-xxxxxxxx"]
  bootstrap_brokers             = ["pk-xxxxxxxx.ap-southeast-2.amazonaws.com:6667"]
  authorization_type            = "IAM"
  iam_role_arn                  = aws_iam_role.msk_cluster_role.arn
  open_monitoring               = true
  monitoring_role_arn           = aws_iam_role.msk_cluster_role.arn
  monitoring_cluster_arn        = aws_cloudwatch_log_group.jmx_exporter.arn
  monitoring_namespace          = "Kafka"
  monitoring_log_group_name     = "KafkaLogs"
}

resource "aws_cloudwatch_log_group" "jmx_exporter" {
