  retention_in_days = 14
}

resource "aws_cloudwatch_log_group" "node_exporter" {
  name              = "/aws/kafka/msk-cluster/${local.msk_cluster_name}/node_exporter"
  retention_in_days = 14
}

data "aws_iam_policy" "cloudwatch_logs_read_only" {
  arn = "arn:aws:iam::aws:policy/AmazonCloudWatchLogsReadOnlyAccess"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_logs_read_only_attachment" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = data.aws_iam_policy.cloudwatch_logs_read_only.arn
}
