 Description: This Terraform configuration will create a serverless MSK (Managed Streaming for Kafka) cluster in the us-east1 region. It will include an IAM role for the MSK service to assume, and it will use the latest supported versions of Terraform and the AWS provider.

```hcl
provider "aws" {
  region = "us-east-1"
}

locals {
  msk_cluster_name = "tf-msk-cluster"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "msk_service_role" {
  name = "${local.msk_cluster_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  name                  = local.msk_cluster_name
  kafka_version         = "2.7"
  number_of_broker_nodes = 1
  number_of_consumer_groups = 1
  number_of_zookeeper_nodes = 1

  vpc_id                 = data.aws_vpc.default.id
  subnet_ids            = data.aws_subnets.default.ids
  security_group_ids    = [aws_security_group.msk_cluster.id]

  open_iam_auth_enabled = true

  client_broker_authorizer {
    name = "msk-iam-authorizer"
  }

  cloudwatch_log_group_arn = aws_cloudwatch_log_group.msk_logs.arn

  tags = {
    Name = local.msk_cluster_name
  }
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "/aws/msk/${local.msk_cluster_name}"
}

resource "aws_iam_role_policy_attachment" "msk_service_to_msk_cloudwatch" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKCloudWatchLogs"
}

resource "aws_iam_role_policy_attachment" "msk_service_to_msk_kms" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKEncryptionAtRestWithKMS"
}

resource "aws_security_group" "msk_cluster" {
  name_prefix = local.msk_cluster_name
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  vpc_id = data.aws_vpc.default.id
}
```

This configuration assumes that you have a default VPC and subnets in the us-east1 region. If you don't, you'll need to create them before running this Terraform configuration.

