  cluster_name = local.msk_cluster_name
  kafka_version = "2.8.0"

  vpc_config {
    subnet_id_1 = "subnet-xxxxxxxx"
    subnet_id_2 = "subnet-yyyyyyyy"
    subnet_id_3 = "subnet-zzzzzzzz"
  }

  broker_node_group_configs = [
    {
      instance_type = "m5.large"
      client_subnet_tag = "client"
      create_iam_instance_profile = true
      iam_instance_profile_arn = aws_iam_role.msk_service_role.arn
      zone_awareness_enabled = true
      zone_awareness_configuration {
        zone_awareness_state = "ENABLED"
        zonal_availability_properties {
          availability_zone_1 = "us-west-2a"
          availability_zone_2 = "us-west-2b"
          availability_zone_3 = "us-west-2c"
        }
      }
    }
  ]

  communication_encryption_config {
    encryption_in_transit_enabled = true
    encryption_at_rest_enabled = true
  }

  tags = {
    Name = local.msk_cluster_name
  }
}
