resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                 = local.msk_cluster_name
  kafka_version                = data.aws_msk_cluster_version.latest.version
  create_topic_config {
    number_of_partitions = 1
    replication_factor   = 3
  }

  broker_node_group_configs = [
    {
      instance_type = "m5.large"
      client_subnet_cidr_block = "10.0.0.0/24"
      security_group_ids = [aws_security_group.msk_sg.id]
      zone_awareness_enabled = true
      zone_awareness_configuration {
        zone_awareness_replica_placement_strategy = "ZONE_AWARE_PLACEMENT_STRATEGY_LATEST_IN_ZONE"
      }
    },
    {
      instance_type = "m5.large"
      client_subnet_cidr_block = "10.0.1.0/24"
      security_group_ids = [aws_security_group.msk_sg.id]
      zone_awareness_enabled = true
      zone_awareness_configuration {
        zone_awareness_replica_placement_strategy = "ZONE_AWARE_PLACEMENT_STRATEGY_LATEST_IN_ZONE"
      }
    },
    {
      instance_type = "m5.large"
      client_subnet_cidr_block = "10.0.2.0/24"
      security_group_ids = [aws_security_group.msk_sg.id]
      zone_awareness_enabled = true
      zone_awareness_configuration {
        zone_awareness_replica_placement_strategy = "ZONE_AWARE_PLACEMENT_STRATEGY_LATEST_IN_ZONE"
      }
    }
  ]

  vpc_config {
    subnet_ids = [
      aws_subnet.msk_subnet_1.id,
      aws_subnet.msk_subnet_2.id,
      aws_subnet.msk_subnet_3.id
    ]
  }

  kafka_configs = {
    broker_id = "0"
    listeners = {
      plain_host = "plainhost:9092"
    }
  }
}

resource "aws_iam_role" "msk_iam_role" {
  name = "${local.msk_cluster_name}-iam-for-msk"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "msk_policy_attachment" {
  role       = aws_iam_role.msk_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKReadOnlyAccess"
}

resource "aws_security_group" "msk_sg" {
  name_prefix = local.msk_cluster_name
  vpc_id      = aws_vpc.main.id
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "msk_subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.0.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "msk_subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "msk_subnet_3" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1c"
}
```

This configuration creates a VPC, three subnets, a security group, an IAM role, and an MSK cluster with three broker nodes in the us-east1 region. The MSK cluster uses the latest available version and creates a topic with one partition and a replication factor of 3. The broker nodes are of type m5.large and are configured for zone awareness. The IAM role grants read-only access to the MSK cluster.

