 Description: This Terraform configuration will create a serverless MSK (Managed Streaming for Kafka) cluster in the us-east2 region. It will include an IAM role for the MSK service to assume, and it will use the AWS provider version ~> 5.75 and Terraform version ~> 1.9.8.

```hcl
provider "aws" {
  region = "us-east-2"
}

locals {
  msk_cluster_name = "tf-msk-cluster"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "msk_service_role" {
  name = "${local.msk_cluster_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "msk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  name                      = local.msk_cluster_name
  kafka_version             = "2.7"
  number_of_broker_nodes    = 1
  number_of_zookeeper_nodes = 1

  vpc_id                     = module.vpc.vpc_id
  subnet_ids                = module.vpc.private_subnets

  open_iam_auth             = true
  open_monitoring           = true

  service_security_group_id = module.security_group.id

  kafka_configs = {
    "zookeeper.connect.string" = "${aws_msk_zookeeper_connect_string.zookeeper.id}:2181"
  }

  tags = {
    Name = local.msk_cluster_name
  }

  lifecycle {
    ignore_changes = [
      kafka_configs
    ]
  }
}

resource "aws_msk_zookeeper_connect_string" "zookeeper" {
  cluster_id = aws_msk_cluster.msk_cluster.id
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "3.0.0"

  name = local.msk_cluster_name
  cidr = "10.0.0.0/16"

  azs             = ["us-east-2a", "us-east-2b", "us-east-2c"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

module "security_group" {
  source  = "terraform-aws-modules/security-group/aws"
  version = "4.16.0"

  name        = local.msk_cluster_name
  description = "Security group for MSK cluster"
  vpc_id      = module.vpc.vpc_id

  ingress_with_cidr_blocks = [
    {
      from_port   = 9092
      to_port     = 9092
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  ]
}

resource "aws_iam_role_policy_attachment" "msk_service_to_msk_full_access" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
}
```

This configuration creates a VPC, a security group, and an IAM role for the MSK service. It then creates an MSK cluster with the specified configuration, including the IAM role for the service to assume. The configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75.

Rego intent:
package main

import future.keywords.in

default allow = false

# Check for MSK Cluster creation
msk_cluster_created(resources) {
some resource in resources
resource.type == "aws_msk_cluster"
resource.change.actions[_] == "create"
}

# Check if the MSK cluster is in us-east-1 (as defined in Terraform)
msk_cluster_region_valid(resource) {
resource.type == "aws_msk_cluster"
input.configuration.provider_config.aws.expressions.region.constant_value == "us-east-1"
}

# Check if the MSK cluster has 3 broker nodes (as defined in Terraform)
broker_node_count_valid(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.number_of_broker_nodes == 3
}

# Check if CloudWatch logging is enabled for broker logs
cloudwatch_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].cloudwatch_logs[_].enabled == true
}

# Check if S3 logging is enabled for broker logs
s3_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].s3[_].enabled == true
}

# Check if Kinesis Firehose logging is enabled for broker logs
firehose_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].firehose[_].enabled == true
}

# Check if encryption at rest is enabled
encryption_at_rest_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after_unknown.encryption_info[_].encryption_at_rest_kms_key_arn
}

# Check if both jmx_exporter and node_exporter are enabled
prometheus_exporters_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.open_monitoring[_].prometheus[_].jmx_exporter[_].enabled_in_broker == true
resource.change.after.open_monitoring[_].prometheus[_].node_exporter[_].enabled_in_broker == true
}

# Aggregate all checks
allow {
msk_cluster_created(input.resource_changes)
some resource in input.resource_changes
msk_cluster_region_valid(resource)
broker_node_count_valid(resource)
cloudwatch_logging_enabled(resource)
s3_logging_enabled(resource)
firehose_logging_enabled(resource)
encryption_at_rest_enabled(resource)
prometheus_exporters_enabled(resource)
}

