LLM Output #0:
 **Description:**

This Terraform configuration will create an Amazon MSK (Managed Streaming for Kafka) cluster with 3 broker nodes, enabling encryption at rest, open monitoring, and setting up logging to CloudWatch Log Group, an S3 bucket, and a Kinesis Firehose delivery stream.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
  version = "~> 5.75"
}

locals {
  msk_cluster_id = "my-msk-cluster"
  log_group_name = "my-msk-log-group"
  bucket_name    = "my-msk-s3-bucket"
  firehose_name  = "my-msk-firehose"
}

data "aws_iam_policy_document" "msk_cluster_assume_role_policy" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["arn:aws:kafka:us-west-2:123456789012:cluster/${local.msk_cluster_id}"]
    }
  }
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "${local.msk_cluster_id}-role"

  assume_role_policy = data.aws_iam_policy_document.msk_cluster_assume_role_policy.json
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name                     = local.msk_cluster_id
  kafka_version                    = "2.8.0"
  open_monitoring                  = true
  encryption_in_transit_enabled    = true
  encryption_at_rest_enabled       = true
  vpc_id                           = "vpc-12345678"
  subnet_ids                       = ["subnet-12345678", "subnet-23456789", "subnet-34567890"]
  security_group_ids               = ["sg-12345678"]
  authorizer_properties {
    authorizer_type_name = "IAM"
    iam_authorizer_properties {
      role_arn = aws_iam_role.msk_cluster_role.arn
    }
  }

  configuration_properties {
    property_name = "zookeeper.connect.string"
    property_value = "${aws_msk_zookeeper_connect.zookeeper.id}.${aws_msk_cluster.msk_cluster.id}.${aws_msk_zookeeper_connect.zookeeper.region}.amazonaws.com:2181,${aws_msk_zookeeper_connect.zookeeper.id}.${aws_msk_cluster.msk_cluster.id}.${aws_msk_zookeeper_connect.zookeeper.region}.amazonaws.com:2182,${aws_msk_zookeeper_connect.zookeeper.id}.${aws_msk_cluster.msk_cluster.id}.${aws_msk_zookeeper_connect.zookeeper.region}.amazonaws.com:2183"
  }

  configuration_properties {
    property_name = "broker.rack"
    property_value = "us-west-2a"
  }

  configuration_properties {
    property_name = "log4j.rootCategory"
    property_value = "INFO, CloudWatchLogAppender, ConsoleAppender"
  }

  configuration_properties {
    property_name = "log4j.appender.CloudWatchLogAppender"
    property_value = "com.amazonaws.services.log4j.awslogs.AWSLogAppender"
  }

  configuration_properties {
    property_name = "log4j.appender.CloudWatchLogAppender.layout"
    property_value = "com.amazonaws.services.log4j.awslogs.AWSLogLayout"
  }

  configuration_properties {
    property_name = "log4j.appender.CloudWatchLogAppender.logGroupName"
    property_value = local.log_group_name
  }

  configuration_properties {
    property_name = "log4j.appender.CloudWatchLogAppender.logStreamName"
    property_value = "${local.msk_cluster_id}-log-stream"
  }

  configuration_properties {
    property_name = "log4j.appender.ConsoleAppender"
    property_value = "org.apache.kafka.log4j.ConsoleAppender"
  }

  configuration_properties {
    property_name = "log4j.rootCategory.appender"
    property_value = "CloudWatchLogAppender, ConsoleAppender"
  }
}

resource "aws_msk_zookeeper_connect" "zookeeper" {
  cluster_id = aws_msk_cluster.msk_cluster.id
  region     = aws_msk_cluster.msk_cluster.region
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = local.bucket_name
  acl    = "private"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose" {
  name        = local.firehose_name
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.msk_s3_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "${local.firehose_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "${local.firehose_name}-policy"
  description = "Policy for Kinesis Firehose"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.msk_s3_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_to_s3" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}
```

**Note:**

- Replace `vpc-12345678`, `subnet-12345678`, `sg-12345678`, `123456789012` with your VPC ID, Subnet IDs, Security Group ID, and AWS account ID respectively.
- This configuration assumes that you have already created an IAM role with the necessary permissions for S3 and Kinesis Firehose. If not, you can create one using the `aws_iam_role` resource and appropriate policies.

