LLM Output #0:
 Description: This Terraform configuration will create an Amazon MSK (Managed Streaming for Kafka) cluster with 3 broker nodes, enabling encryption at rest, open monitoring, and logging to both CloudWatch Log Group and an S3 bucket via Kinesis Data Firehose. Additionally, it will create an MSK Connect custom plugin using a provided "debezium.zip" and an MSK Connect connector that utilizes the custom plugin to connect to the MSK cluster.

```hcl
provider "aws" {
  region = "us-west-2"
  version = "~> 5.75"
}

locals {
  msk_cluster_id = "my-msk-cluster"
  log_group_name = "my-msk-log-group"
  bucket_name    = "my-msk-s3-bucket"
  firehose_name  = "my-msk-firehose"
}

data "aws_iam_policy_document" "msk_cluster_policy" {
  statement {
    actions = ["kafka:*"]
    resources = ["*"]
    effect = "Allow"
  }
}

resource "aws_msk_cluster" "this" {
  cluster_name                     = local.msk_cluster_id
  kafka_version                    = "2.8.0"
  open_monitoring                  = true
  encryption_in_transit_enabled    = true
  encryption_at_rest_enabled       = true
  vpc_id                           = data.aws_vpc.default.id
  subnet_ids                       = data.aws_subnet_ids.default.ids

  configuration_properties = {
    "zookeeper.connect.string" = aws_msk_zookeeper_connect.this.zookeeper_connect_string
  }

  tags = {
    Name = local.msk_cluster_id
  }
}

resource "aws_msk_zookeeper_connect" "this" {
  cluster_id = aws_msk_cluster.this.id
  zookeeper_connect_string = aws_msk_zookeeper_connect_instance.this.zookeeper_connect_string
}

resource "aws_msk_zookeeper_connect_instance" "this" {
  cluster_id = aws_msk_cluster.this.id
  instance_type = "m5.large"
  instance_count = 1

  tags = {
    Name = local.msk_cluster_id
  }
}

resource "aws_msk_broker" "this" {
  count = 3
  cluster_id = aws_msk_cluster.this.id
  broker_id = "${local.msk_cluster_id}-broker-${count.index + 1}"
}

resource "aws_iam_role" "msk_role" {
  name = "${local.msk_cluster_id}-msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_policy" {
  name = "${local.msk_cluster_id}-msk-policy"
  policy = data.aws_iam_policy_document.msk_cluster_policy.json
}

resource "aws_iam_role_policy_attachment" "msk_role_policy_attachment" {
  role       = aws_iam_role.msk_role.name
  policy_arn = aws_iam_policy.msk_policy.arn
}

resource "aws_msk_cluster_iam_policy" "this" {
  cluster_arn = aws_msk_cluster.this.arn
  policy_arn  = aws_iam_policy.msk_policy.arn
}

resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name
  acl    = "private"

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_cloudwatch_log_group" "this" {
  name = local.log_group_name
  retention_in_days = 14
}

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = local.firehose_name
  destination = "extended_s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.this.arn
    role_arn   = aws_iam_role.firehose_role.arn
  }

  cloudwatch_logging_option {
    log_group_name = local.log_group_name
    log_stream_prefix = "firehose"
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "${local.firehose_name}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_policy" {
  name = "${local.firehose_name}-firehose-policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetObject",
          "s3:GetObjectAcl",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_role_policy_attachment" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

