```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  cluster_name = "my-mysql-cluster"
  replica_count = 3
  storage_size = 100
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "rds_assume_role" {
  name = "${local.cluster_name}-rds-assume-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "rds_instance_profile" {
  name = "${local.cluster_name}-rds-instance-profile"
  role = aws_iam_role.rds_assume_role.name
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier = local.cluster_name
  engine              = "mysql"
  engine_version      = "8.0.27"
  availability_zones  = ["us-west-2a", "us-west-2b", "us-west-2c"]
  master_username     = "admin"
  master_password     = "MySecretPassword123!"
  skip_final_snapshot = true

  backup_window         = "03:00-06:00"
  maintenance_window   = "mon:00:00-mon:03:00"
  preferred_backup_window = "03:00-06:00"
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = local.cluster_name
  }

  database_subnet_group_name = aws_db_subnet_group.subnet_group.name

  master_instance_count = 1
  master_instance_type   = "db.t3.medium"

  replication_configuration {
    replication_source_identifier = aws_rds_cluster.mysql_cluster.id
    availability_zone_id          = elements(aws_availability_zones.available.names, 1)
    role_arn                       = aws_iam_role.rds_replica_role.arn
    db_instance_identifier         = aws_rds_db_instance.replica.*.id[0]
  }

  replication_configuration {
    replication_source_identifier = aws_rds_cluster.mysql_cluster.id
    availability_zone_id          = elements(aws_availability_zones.available.names, 2)
    role_arn                       = aws_iam_role.rds_replica_role.arn
    db_instance_identifier         = aws_rds_db_instance.replica.*.id[1]
  }

  replication_configuration {
    replication_source_identifier = aws_rds_cluster.mysql_cluster.id
    availability_zone_id          = elements(aws_availability_zones.available.names, 3)
    role_arn                       = aws_iam_role.rds_replica_role.arn
    db_instance_identifier         = aws_rds_db_instance.replica.*.id[2]
  }

  dynamic "replica" {
    for_each = range(local.replica_count)

    content {
      replica_identifier = "${local.cluster_name}-replica-${replica.index}"
      replica_instance_type   = "db.t3.medium"
      storage_encrypted       = true
      storage_type            = "gp2"
      storage_size            = local.storage_size
    }
  }
}

resource "aws_iam_role" "rds_replica_role" {
  name = "${local.cluster_name}-rds-replica-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_db_subnet_group" "subnet_group" {
  name       = local.cluster_name
  subnet_ids = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id, aws_subnet.subnet_3.id]

