  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "subnet_c" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.3.0/24"
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "mysql_sg" {
  name        = "${var.mysql_cluster_name}-sg"
  description = "Security group for MySQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "mysql_subnet_group" {
  name       = "${var.mysql_cluster_name}-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id, aws_subnet.subnet_c.id]
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = var.mysql_cluster_name
  master_username         = "my_master_user"
  master_password         = "my_master_password"
  database_name           = "my_database"
  replication_method      = "multi-az"
  skip_final_snapshot     = true
  vpc_security_group_ids   = [aws_security_group.mysql_sg.id]
