 Description: This Terraform configuration creates a DynamoDB table named `my-dynamodb-table` in the AWS region `us-west-2`. The table has a primary key named `id` with a string data type and a sort key named `timestamp` with a number data type.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "dynamodb_table_name" {
  default = "my-dynamodb-table"
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = var.dynamodb_table_name
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"
  attribute {
    name = "id"
    type = "S"
  }
  attribute {
    name = "timestamp"
    type = "N"
  }
}
```

This configuration creates an IAM role named `dynamodb-table-role` with the necessary permissions for the DynamoDB table.

```hcl
resource "aws_iam_role" "dynamodb_table_role" {
  name = "dynamodb-table-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "dynamodb_table_policy" {
  name = "dynamodb-table-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:Query",
          "dynamodb:Scan"
        ]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.dynamodb_table.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dynamodb_table_role_policy_attachment" {
  role       = aws_iam_role.dynamodb_table_role.name
  policy_arn = aws_iam_policy.dynamodb_table_policy.arn
}
```

Finally, the DynamoDB table is associated with the IAM role.

```hcl
resource "aws_dynamodb_table_iam_policy" "dynamodb_table_iam_policy" {
  table_name = aws_dynamodb_table.dynamodb_table.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "dynamodb:PutItem"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.dynamodb_table_role.arn
        }
      }
    ]
  })
}
```

