 Description:
This Terraform configuration will create an Amazon S3 bucket with a custom Time to Live (TTL) attribute for data expiration. It will also create an IAM role for the S3 bucket to allow Terraform to manage it.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_name" {
  default = "my-s3-bucket"
}

variable "ttl_seconds" {
  default = 300
}

resource "aws_s3_bucket" "bucket" {
  bucket = var.bucket_name
  acl    = "private"

  lifecycle {
    prevent_destroy = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  versioning {
    enabled = true
  }

  tags = {
    Name        = var.bucket_name
    Environment = "dev"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "bucket_lifecycle" {
  bucket = aws_s3_bucket.bucket.id

  rule {
    id     = "object_expiration"
    status = "Enabled"

    expiration {
      days = var.ttl_seconds / 86400
    }

    noncurrent_version_expiration {
      days = var.ttl_seconds / 86400
    }
  }
}

resource "aws_iam_role" "s3_bucket_role" {
  name = "${var.bucket_name}-s3-bucket-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_bucket_policy" {
  name = "${var.bucket_name}-s3-bucket-policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.bucket.arn}/*"
      },
      {
        Action = [
          "s3:PutBucketLifecycle"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.bucket.arn}"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_bucket_policy_attachment" {
  role       = aws_iam_role.s3_bucket_role.name
  policy_arn = aws_iam_policy.s3_bucket_policy.arn
}
```

This configuration creates an S3 bucket with a custom TTL of 300 seconds (5 minutes) for data expiration. The IAM role and policy are set up to allow Terraform to manage the S3 bucket. The bucket name can be customized using the `bucket_name` variable.

