Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  neptune_cluster_id = "my-neptune-cluster"
  neptune_subnet_id  = "my-neptune-subnet"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "neptune_cluster" {
  name = "${local.neptune_cluster_id}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "neptune.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_vpc" "neptune_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "neptune_subnet" {
  vpc_id     = aws_vpc.neptune_vpc.id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "${local.neptune_cluster_id}-subnet"
  }
}

resource "aws_security_group" "neptune_sg" {
  name_prefix = "${local.neptune_cluster_id}-sg"
  vpc_id      = aws_vpc.neptune_vpc.id

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

