This Terraform configuration will create an AWS Chime Voice Connector and set up a media streaming pipeline to Amazon Kinesis. The configuration includes creating necessary IAM roles and policies, as well as setting up the required AWS resources.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  chime_voice_connector_name = "chime-voice-connector"
  kinesis_stream_name        = "chime-kinesis-stream"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "chime_voice_connector_role" {
  name = "${local.chime_voice_connector_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "chime_voice_connector_policy" {
  name = "${local.chime_voice_connector_name}-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutMedia"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "chime_voice_connector_kinesis" {
  role       = aws_iam_role.chime_voice_connector_role.name
  policy_arn = aws_iam_policy.chime_voice_connector_policy.arn
}

resource "aws_chime_voice_connector" "chime_voice_connector" {
  name               = local.chime_voice_connector_name
  region             = var.region
  voice_connector_type = "MEDIA_STREAM"
  media_stream_configuration = {
    kinesis_stream_arn = aws_kinesis_stream.chime_kinesis_stream.arn
  }
  role_arn = aws_iam_role.chime_voice_connector_role.arn
}

resource "aws_kinesis_stream" "chime_kinesis_stream" {
  name             = local.kinesis_stream_name
  shard_count      = 1
  retention_period = 24 * 60 * 60
}

variable "region" {
  description = "The AWS region where the resources will be created."
  default     = "us-west-2"
}
```

This configuration creates an IAM role for the Chime Voice Connector, attaches a policy that allows putting media to Kinesis, and sets up an AWS Chime Voice Connector with a media streaming configuration that uses the created Kinesis stream.

