resource "aws_iam_role" "lambda_role" {
  name = "lambda_s3_inventory_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_access" {
  name = "s3_access_for_lambda"

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.inventory_bucket.arn}"
      },
      {
        Action = [
          "s3:ListAllMyBuckets",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject",
          "s3:ListObjectVersions",
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.bucket.arn}/*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_to_s3_access" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_s3_bucket" "bucket" {
  bucket = local.bucket_name
  acl    = "private"
}

resource "aws_s3_bucket" "inventory_bucket" {
  bucket = local.inventory_bucket_name
  acl    = "private"
}

resource "aws_lambda_function" "inventory_function" {
  filename      = "inventory.zip"
  function_name = "s3_inventory"
  role          = aws_iam_role.lambda_role.arn
  handler       = "exports.handler"
  runtime       = "nodejs14.x"

  environment {
    variables = {
      bucket_name = local.bucket_name
      inventory_bucket_name = local.inventory_bucket_name
    }
  }
}

resource "aws_cloudwatch_event_rule" "inventory_rule" {
  name                = "s3-inventory-rule"
  description         = "Trigger weekly S3 inventory report"
  schedule_expression = "rate(1 week)"
}

resource "aws_cloudwatch_event_target" "inventory_target" {
  rule      = aws_cloudwatch_event_rule.inventory_rule.name
  target_id = "LambdaFunction"
  arn       = aws_lambda_function.inventory_function.arn
  role_arn  = aws_iam_role.lambda_role.arn
}
```

