This Terraform configuration will create an AWS S3 bucket and set up an SNS topic subscription to send a notification whenever a new .log object is created in the S3 bucket. The configuration uses the AWS provider and does not include any IAM policies.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  bucket_name = "my-log-bucket-${random_id.id.hex}"
  topic_name = "my-log-topic"
}

resource "random_id" "id" {
  byte_length = 4
}

resource "aws_s3_bucket" "bucket" {
  bucket = local.bucket_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_object" "object" {
  for_each = {
    for f in fileset(".", "*.log") : f => f
    }

  bucket = aws_s3_bucket.bucket.id
  key    = each.value
  content = file(each.value)
  etag   = md5(file(each.value))
}

resource "aws_sns_topic" "topic" {
  name = local.topic_name
}

resource "aws_sns_topic_subscription" "subscription" {
  topic_arn = aws_sns_topic.topic.arn
  protocol  = "email"
  endpoint  = "your-email@example.com"
