```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  logs_bucket_name = "server-access-logs-${random_id.suffix.hex}"
  data_bucket_name = "server-access-data-${random_id.suffix.hex}"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "logs_bucket" {
  bucket = local.logs_bucket_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = local.data_bucket_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_policy" "logs_bucket_policy" {
  bucket = aws_s3_bucket.logs_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource   = "${aws_s3_bucket.logs_bucket.arn}/*/*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = "vpc-12345678"
          }
        }
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "logs" {
  name = "/aws/elasticbeanstalk/default-applications-logs"
}

resource "aws_elasticbeanstalk_application_version" "app_version" {
  application_name = "my-app"
  version_label    = "v1"
  source_bundle    = "path/to/my-app.zip"
}

resource "aws_elasticbeanstalk_environment" "env" {
  name                = "my-env"
  application          = aws_elasticbeanstalk_application.app
  solution_stack_name = "64bit Amazon Linux 2 v3.0.3 running PHP 7.4"
  region              = aws_s3_bucket.logs_bucket.region
  template_name       = "64bit Amazon Linux 2 v3.0.3 running PHP 7.4"
  version_label       = aws_elasticbeanstalk_application_version.app_version.version_label

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "LOGFILE"
    value     = "s3://${aws_s3_bucket.logs_bucket.bucket_regional_domain_name}/${aws_elasticbeanstalk_environment.env.id}/elasticbeanstalk-logs.log"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "S3BucketName"
    value     = aws_s3_bucket.data_bucket.bucket_regional_domain_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "S3LogGroupName"
    value     = aws_cloudwatch_log_group.logs.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "S3LogStreamPrefix"
    value     = "elasticbeanstalk-logs/"
  }
}
```

This configuration creates two S3 buckets, sets up a CloudWatch log group, creates an Elastic Beanstalk application version, and an environment for the application. The environment is configured to store server access logs in the logs bucket and server data in the data bucket. The logs bucket policy allows only traffic from the specified VPC to put objects into the logs bucket.

