 Description:
This Terraform configuration will set up an infrastructure for an autograder for a Computer Science class. It will utilize AWS S3 for storing students' code and the results of the grading, and AWS CodeBuild for running the grading process. Additionally, it will create IAM roles and policies as needed for secure access to these services.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  autograder_name = "cs-autograder"
}

data "aws_caller_identity" "current" {}

# IAM Role for CodeBuild service
resource "aws_iam_role" "codebuild_role" {
  name = "${local.autograder_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild service
resource "aws_iam_policy" "codebuild_policy" {
  name = "${local.autograder_name}-codebuild-policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${local.autograder_name}-bucket/*"
      },
      {
        Action = "codebuild:BatchGetBuilds"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = "codebuild:StartBuild"
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the CodeBuild role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# S3 Bucket for storing students' code and grading results
resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "${local.autograder_name}-bucket"
  acl    = "private"
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder_project" {
  name          = local.autograder_name
  description   = "Autograder for CS class"
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts = {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/standard:4.0"
    type = "LINUX_CONTAINER"
  }

  source {
    type = "GITHUB"
    location = "https://github.com/your-org/your-repo.git"
    buildspec = "buildspec.yml"
  }
}
