 Description:
This Terraform configuration will set up an infrastructure for an autograder in a CS class using AWS CodeBuild and AWS VPC. The autograder will run students' code stored on GitHub in a specific environment, store the results, and prevent the students' code from reaching the internet.

Terraform HCL (main.tf):

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  subnet_cidr = "10.0.1.0/24"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block = local.vpc_cidr
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id     = aws_vpc.autograder_vpc.id
  cidr_block = local.subnet_cidr
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route_table" "autograder_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.autograder_igw.id
  }
}

resource "aws_route_table_association" "autograder_subnet_association" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_route_table.id
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder_codebuild_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "autograder_codebuild_policy" {
  name = "autograder_codebuild_policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:aws:codebuild:${data.aws_caller_identity.current.account_id}:${data.aws_caller_identity.current.account_id}:project/autograder"
          }
        }
      },
      {
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:GetRepositoryPolicy",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "autograder_codebuild_policy_attachment" {
  role       = aws_iam_role.autograder_codebuild_role.name
  policy_arn = aws_iam_policy.autograder_codebuild_policy.arn
}

resource "aws_codebuild_project" "autograder" {
  name          = "autograder"
  description   = "CS Class Autograder"
  service_role  = aws_iam_role.autograder_codebuild_role.arn

  source {
    type      = "GITHUB"
    location  = "https://github.com/your_github_username/autograder.git"
    buildspec = file("buildspec.yml")
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:3.0"
    type         = "LINUX_CONTAINER"

    environment_variable {
      name  = "VPC_ID"
      value = aws_vpc.autograder_vpc.id
    }

    environment_variable {
      name  = "SUBNET_ID"
      value = aws_subnet.autograder_subnet.id
    }
  }
}
```

This configuration creates a VPC and a subnet for the autograder, an internet gateway, and a route table to allow internet access only for the CodeBuild service. It also creates an IAM role for CodeBuild with the necessary permissions to access S3 and ECR, and sets up a CodeBuild project that pulls its source code from a GitHub repository. The environment variables VPC_ID and SUBNET_ID are passed to the CodeBuild project to ensure the autograder runs within the specified VPC and subnet.

