This Terraform configuration will create an infrastructure for an autograder in AWS, allowing the secure storage and execution of students' code. The setup includes an S3 bucket for storing the code, a CodeBuild project for executing the code, a VPC for network isolation, VPC subnets, and a security group to control access and prevent internet access for the students' code.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "autograder"
  }
}

variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  default = "10.0.1.0/24"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block       = local.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "autograder_vpc" })
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id     = aws_vpc.autograder_vpc.id
  cidr_block = var.subnet_cidr_block

  tags = merge(local.common_tags, { Name = "autograder_subnet" })
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder_sg"
  description = "Security group for autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "autograder_sg" })
}

resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "autograder-bucket"
  acl    = "private"

  tags = merge(local.common_tags, { Name = "autograder_bucket" })
}

resource "aws_codebuild_project" "autograder_project" {
  name          = "autograder-project"
  description   = "CodeBuild project for autograder"
  service_role  = aws_iam_role.autograder_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/standard:4.0"
    type = "LINUX_CONTAINER"
  }

  source {
    type = "GITHUB"
    location = "https://github.com/your-github-username/autograder.git"
  }

  tags = merge(local.common_tags, { Name = "autograder_project" })
}

resource "aws_iam_role" "autograder_role" {
  name = "autograder_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "autograder_policy"
    path = "/"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Effect   = "Allow"
          Resource = aws_s3_bucket.autograder_bucket.arn
        }
      ]
    })
  }
}
```

Replace `your-github-username` with your GitHub username. This configuration creates a VPC, subnet, security group, S3 bucket, CodeBuild project, and IAM role for the autograder. The CodeBuild project is configured to use the specified GitHub repository, and the IAM role allows the CodeBuild service to access the S3 bucket. The security group is set up to allow all incoming and outgoing traffic, but this can be adjusted as needed to further secure the environment.

