 Description:
This Terraform configuration will set up an AWS service that allows users to upload cat pictures and retrieve random cat pictures on demand. The service consists of an S3 bucket for storing the cat pictures, a DynamoDB table for metadata, a Lambda function to handle the upload and retrieval of images, an API Gateway REST API to expose the functionality, and necessary permissions for the Lambda function to interact with the other resources.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  cat_pics_bucket_name = "cat-pics-bucket-${random_id.bucket_id.hex}"
  table_name           = "CatPicsMetadata"
}

resource "random_id" "bucket_id" {
  byte_length = 4
}

resource "aws_s3_bucket" "cat_pics_bucket" {
  bucket = local.cat_pics_bucket_name
  acl    = "private"
}

resource "aws_dynamodb_table" "cat_pics_table" {
  name           = local.table_name
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "ImageId"

  attribute {
    name = "ImageId"
    type = "S"
  }
}

data "aws_iam_policy_document" "lambda_s3_access" {
  statement {
    actions = ["s3:PutObject", "s3:GetObject", "s3:ListBucket"]

    resources = [
      aws_s3_bucket.cat_pics_bucket.arn,
      "${aws_s3_bucket.cat_pics_bucket.arn}/*"
    ]
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_cat_pics_exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_cat_pics_policy" {
  name = "lambda_cat_pics_policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem"
        ]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.cat_pics_table.arn
      },
      {
        Action = "s3:*"
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_cat_pics_exec_to_policy" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_cat_pics_policy.arn
}

resource "aws_iam_policy_attachment" "lambda_s3_access_to_exec" {
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = data.aws_iam_policy.lambda_s3_access.arn
}

resource "aws_lambda_function" "cat_pics_function" {
  filename      = "cat_pics_function.zip"
  function_name = "CatPicsFunction"
  role          = aws_iam_role.lambda_exec.arn
  handler       = "main"
  runtime       = "python3.8"

  environment {
    variables = {
      table_name = local.table_name
      bucket_name = local.cat_pics_bucket_name
    }
  }
}

resource "aws_api_gateway_rest_api" "cat_pics_api" {
  name        = "CatPicsAPI"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "cat_pics_upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pics_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pics_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "cat_pics_upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pics_api.id
  resource_id   = aws_api_gateway_resource.cat_pics_upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "cat_pics_upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pics_api.id
  resource_id             = aws_api_gateway_resource.cat_pics_upload_resource.id
  http_method             = aws_api_gateway_method.cat_pics_upload_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.cat_pics_function.invoke_arn
}

resource "aws_api_gateway_deployment" "cat_pics_api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_pics_api.id
  stage_name  = "prod"

  lifecycle {
    create_before_destroy = true
  }
}

output "cat_pics_api_url" {
  value = aws_api_gateway_deployment.cat_pics_api_deployment.invoke_url
}
```

This configuration creates the necessary AWS resources for the cat picture service, including an S3 bucket, DynamoDB table, Lambda function, API Gateway REST API, and necessary permissions. The Lambda function is packaged as a zip file named `cat_pics_function.zip`. You will need to replace the contents of this file with your own Python 3.8 code to handle the uploading and retrieval of cat pictures. The configuration also outputs the URL for the API Gateway deployment.

