 Description:
This Terraform configuration will create an AWS EC2 instance and set up an AWS Backup service to perform daily backups at midnight. It will also create the necessary IAM roles and policies for the EC2 instance to interact with the AWS Backup service.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  backup_role_name = "ec2-backup-role"
  backup_policy_name = "ec2-backup-policy"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["099720109477"] # Canonical
}

resource "aws_iam_role" "ec2_backup_role" {
  name = local.backup_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "ec2_backup_policy" {
  name = local.backup_policy_name

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "backup:CreateBackup",
          "backup:GetBackupVault",
          "backup:ListBackupVaults",
          "backup:ListRecoveryPoints",
          "backup:StartBackupJob"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_backup_to_backup" {
  role       = aws_iam_role.ec2_backup_role.name
  policy_arn = aws_iam_policy.ec2_backup_policy.arn
}

resource "aws_iam_instance_profile" "ec2_backup_profile" {
  name = "ec2-backup-profile"
  role = aws_iam_role.ec2_backup_role.name
}

resource "aws_launch_configuration" "ec2_backup_launch_config" {
  name_prefix          = "ec2-backup-launch-config"
  image_id             = data.aws_ami.ubuntu.id
  instance_type        = "t2.micro"
  key_name             = "your-key-pair-name"
  security_groups      = ["your-security-group-id"]
  iam_instance_profile = aws_iam_instance_profile.ec2_backup_profile.name

  user_data = base64encode(<<-EOT
    #!/bin/bash
    # Install AWS CLI
    curl "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip" -o "awscliv2.zip"
    unzip awscliv2.zip
    sudo ./aws/install

    # Configure AWS CLI
    aws configure --profile backup
    aws --profile backup configure set region us-west-2
    aws --profile backup s3 cfpputbucket --bucket your-backup-bucket --region us-west-2
    EOT
  )
}

resource "aws_autoscaling_group" "ec2_backup_asg" {
  name                 = "ec2-backup-asg"
  launch_configuration = aws_launch_configuration.ec2_backup_launch_config.name
  vpc_zone_identifier  = ["your-subnet-id"]

  min_size            = 1
  max_size            = 1

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_backup_vault" "ec2_backup_vault" {
  name = "ec2-backup-vault"
}

resource "aws_backup_plan" "ec2_backup_plan" {
  name              = "ec2-backup-plan"
  rule_type         = "BACKUP_Vault"
  backup_vault_arn  = aws_backup_vault.ec2_backup_vault.arn

  schedule {
    time         = "00:00"
    days_of_week = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"]
  }

  selection_criteria {
    lifecycle {
      create_protection_across_regions = false
    }

    include_resource_type = "EC2_INSTANCE"
  }
}

resource "aws_backup_selection" "ec2_backup_selection" {
  name              = "ec2-backup-selection"
  backup_plan_id    = aws_backup_plan.ec2_backup_plan.id
  resource_type     = "EC2_INSTANCE"
  resource_id       = aws_autoscaling_group.ec2_backup_asg.id
}
```

Please replace `your-key-pair-name`, `your-security-group-id`, and `your-subnet-id` with your actual AWS key pair name, security group ID, and subnet ID respectively. Also, replace `your-backup-bucket` with the name of an existing S3 bucket in the same region where you want to store the backups.

