 Description:
This Terraform configuration will create an AWS service that runs a code everyday at 7 UTC using AWS EventBridge. It will include an IAM role for the Lambda function, a Lambda function, and a Rule in EventBridge to trigger the Lambda function daily at the specified time.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lambda_function_name = "daily_task_lambda"
  rule_name            = "daily_task_rule"
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "main.py"
  output_path = "main.zip"
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.lambda_function_name}_exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name = "${local.lambda_function_name}_policy"

  path   = "/"
  policy = data.aws_iam_policy_document.lambda_policy_doc.json
}

data "aws_iam_policy_document" "lambda_policy_doc" {
  statement {
    effect = "Allow"
    action = "logs:CreateLogGroup"
    resource = "*"
  }

  statement {
    effect = "Allow"
    action = "logs:CreateLogStream"
    resource = "*"
  }

  statement {
    effect = "Allow"
    action = "logs:PutLogEvents"
    resource = "*"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_to_policy" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "aws_lambda_function" "daily_task" {
  function_name = local.lambda_function_name
  filename      = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  handler       = "main.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_exec.arn

  environment {
    variables = {
      MY_VAR = "my_value"
    }
  }
}

resource "aws_eventbridge_rule" "daily_task_rule" {
  name                = local.rule_name
  description         = "Trigger the daily task Lambda function"
  event_bus_name      = "default"
  schedule_expression = "rate(1 day)"

  target {
    arn      = aws_lambda_function.daily_task.arn
    id       = aws_lambda_function.daily_task.function_name
    role_arn = aws_iam_role.lambda_exec.arn
  }
}
```

This configuration creates an IAM role for the Lambda function, a Lambda function with a Python 3.8 runtime, and an EventBridge Rule that triggers the Lambda function daily at midnight UTC. The Lambda function is given an environment variable named `MY_VAR` with a default value of `my_value`. The provider is set to the `us-west-2` region.

