 Description:
This Terraform configuration will create an AWS EventBridge event rule named "cron" with a schedule that triggers the event every day at 7 UTC. It will also create an AWS Lambda function named "cron-lambda-function" and set up the necessary permissions for the EventBridge event rule to invoke the Lambda function.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "lambda_function_name" {
  default = "cron-lambda-function"
}

variable "lambda_function_zip_file" {
  default = "./supplement/lambda_func.zip"
}

variable "lambda_function_handler" {
  default = "lambda_func.lambda_handler"
}

variable "lambda_function_runtime" {
  default = "python3.12"
}

variable "event_rule_name" {
  default = "cron"
}

variable "schedule_expression" {
  default = "rate(1 day) at 7 UTC"
}

resource "aws_iam_role" "lambda_to_eventbridge" {
  name = "${var.event_rule_name}_to_lambda"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "cron" {
  function_name = var.lambda_function_name
  filename      = var.lambda_function_zip_file
  handler       = var.lambda_function_handler
  runtime       = var.lambda_function_runtime
  role          = aws_iam_role.lambda_to_eventbridge.arn
}

resource "aws_eventbridge_event_rule" "cron" {
  name        = var.event_rule_name
  description = "Cron event rule"
  schedule_expression = var.schedule_expression
}

resource "aws_eventbridge_event_target" "cron" {
  rule = aws_eventbridge_event_rule.cron.name
  arn  = aws_lambda_function.cron.arn
}

resource "aws_lambda_permission" "cron" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_eventbridge_event_rule.cron.arn
}
```

