 Description:
This Terraform configuration will set up a video streaming site on AWS, utilizing CloudFront, Route53, and S3 for content distribution and management. It will also include necessary IAM roles and policies for secure access.

Terraform HCL for VPC and IAM:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "s3_access" {
  name = "s3_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "s3_access_role" })
}

resource "aws_iam_policy" "s3_bucket_policy" {
  name = "s3_bucket_policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_bucket_policy_attachment" {
  role       = aws_iam_role.s3_access.name
  policy_arn = aws_iam_policy.s3_bucket_policy.arn
}
```

Terraform HCL for VPC, Internet Gateway, Route Tables, and Subnets:

```hcl
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = merge(local.common_tags, { Name = "main_vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "main_igw" })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "main_route_table" })
}

resource "aws_subnet" "subnet_1" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = merge(local.common_tags, { Name = "subnet_1" })
}

resource "aws_subnet" "subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"

  tags = merge(local.common_tags, { Name = "subnet_2" })
}

resource "aws_route_table_association" "subnet_1_association" {
  subnet_id      = aws_subnet.subnet_1.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "subnet_2_association" {
  subnet_id      = aws_subnet.subnet_2.id
  route_table_id = aws_route_table.main.id
}
```

Terraform HCL for S3 Bucket and CloudFront Distribution:

```hcl
resource "aws_s3_bucket" "video_bucket" {
  bucket = "video-streaming-bucket-${data.aws_caller_identity.current.account_id}"
  acl    = "private"

  tags = merge(local.common_tags, { Name = "video_bucket" })
}

resource "aws_s3_bucket_policy" "video_bucket_policy" {
  bucket = aws_s3_bucket.video_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Principal = "*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/s3_access_role"
          }
        }
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "Origin Access Identity for CloudFront"

  tags = merge(local.common_tags, { Name = "origin_access_identity" })
}

resource "aws_cloudfront_distribution" "distribution" {
  origin {
    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.video_bucket.id
    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled      = true
  comment             = "CloudFront Distribution for Video Streaming"
  default_root_object = "index.html"

  aliases = [
    "${aws_route53_record.a_record.fqdn}"
  ]

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_s3_bucket.video_bucket.id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  price_class = "PriceClass_All"

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations = [
        "US",
        "EU",
        "AP"
      ]
    }
  }

  tags = merge(local.common_tags, { Name = "cloudfront_distribution" })
}
```

Terraform HCL for Route53:

```hcl
resource "aws_route53_zone" "primary" {
  name = "example.com"

  tags = merge(local.common_tags, { Name = "primary_zone" })
}

resource "aws_route53_record" "a_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_cloudfront_distribution.distribution.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.distribution.domain_name
    zone_id                = aws_cloudfront_distribution.distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

