 Description:
This Terraform configuration will set up a video streaming site on AWS with multiple EC2 instances for load balancing. It will create an VPC, subnets, security groups, an Auto Scaling Group, a Launch Configuration, a Load Balancer, and necessary IAM roles.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["amazon"]
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = merge(local.common_tags, { Name = "video-streaming-vpc" })
}

resource "aws_subnet" "public" {
  count = 3

  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  vpc_id     = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "video-streaming-subnet-${count.index + 1}" })
}

resource "aws_security_group" "allow_all_inbound" {
  name        = "allow_all_inbound"
  description = "Allow all inbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2_profile"
  role = aws_iam_role.ec2_role.name
}

resource "aws_iam_policy" "ec2_policy" {
  name = "ec2_policy"

  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "elasticloadbalancing:Describe*",
          "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
          "elasticloadbalancing:RegisterInstancesWithLoadBalancer"
        ]
        Effect   = "Allow"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_to_ec2_policy" {
  role       = aws_iam_role.ec2_role.name
  policy_arn = aws_iam_policy.ec2_policy.arn
}

resource "aws_key_pair" "deployer" {
  key_name   = "deployer"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_launch_configuration" "web" {
  name_prefix          = "web-"
  image_id             = data.aws_ami.amazon_linux_2.id
  instance_type        = "t2.micro"
  key_name             = aws_key_pair.deployer.key_name
  security_groups      = [aws_security_group.allow_all_inbound.id]
  user_data            = filebase64("userdata.sh")
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "web" {
  name                 = "web-asg"
  launch_configuration = aws_launch_configuration.web.name
  vpc_zone_identifier  = [aws_subnet.public[0].id, aws_subnet.public[1].id, aws_subnet.public[2].id]

  min_size            = 2
  max_size            = 10
  desired_capacity    = 2

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_elb" "web" {
  name            = "web-elb"
  subnets         = [aws_subnet.public[0].id, aws_subnet.public[1].id, aws_subnet.public[2].id]
  security_groups = [aws_security_group.allow_all_inbound.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    target              = "HTTP:80/"
    interval            = 30
  }

  tags = merge(local.common_tags, { Name = "web-elb" })
}

resource "aws_autoscaling_attachment" "web" {
  autoscaling_group_name = aws_autoscaling_group.web.name
  elb_name               = aws_elb.web.name
}
```

This configuration creates a VPC, subnets, security groups, an Auto Scaling Group, a Launch Configuration, and a Load Balancer for a video streaming site on AWS. It also creates an IAM role and instance profile for the EC2 instances to allow them to interact with the load balancer. The user data script for the EC2 instances is not included in this example, but it should be added to handle the actual video streaming functionality.

