This Terraform configuration will create an AWS VPC with a specified CIDR block, three subnets within the VPC, an IAM role for EC2 instances, an AWS security group with ingress and egress rules, an AWS Application Load Balancer (ALB), an ALB target group, an ALB listener, an ALB target group attachment for an EC2 instance, and an AWS Route53 zone with alias records for the ALB.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  subnet_cidrs = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = local.vpc_cidr
}

resource "aws_iam_role" "ec2_role" {
  name = "ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2_profile"
  role = aws_iam_role.ec2_role.name
}

resource "aws_security_group" "allow_http" {
  name        = "allow_http"
  description = "Allow HTTP inbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" “subnet1” {
  cidr_block = local.subnet_cidrs[0]
  vpc_id     = aws_vpc.main.id
}

resource "aws_subnet" “subnet2” {
  cidr_block = local.subnet_cidrs[1]
  vpc_id     = aws_vpc.main.id
}

resource "aws_subnet" “subnet3” {
  cidr_block = local.subnet_cidrs[2]
  vpc_id     = aws_vpc.main.id
}

resource "aws_alb" "application_alb" {
  name            = "application-alb"
  internal        = false
  security_groups = [aws_security_group.allow_http.id]
  subnets = [
    aws_subnet.subnet1.id,
    aws_subnet.subnet2.id,
    aws_subnet.subnet3.id
  ]

  tags = {
    Name = "application-alb"
  }
}

resource "aws_alb_target_group" "http_tg" {
  name     = "http_tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_alb_listener" "http_listener" {
  load_balancer_arn = aws_alb.application_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.http_tg.arn
  }
}

resource "aws_alb_target_group_attachment" "ec2_attachment" {
  target_group_arn = aws_alb_target_group.http_tg.arn
  target_id        = aws_instance.ec2_instance.id
  port             = 80
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c94855ba95c574c8" # Latest Ubuntu AMI
  instance_type = "t2.micro"
  key_name      = "your_key_pair_name"
  subnet_id     = aws_subnet.subnet1.id
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name
}

resource "aws_route53_zone" "primary" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "alb" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "lb.test-video-stream.com"
  type    = "A"

  alias {
    name                   = aws_alb.application_alb.dns_name
    zone_id                = aws_alb.application_alb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "a_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"

  alias {
    name                   = aws_alb.application_alb.dns_name
    zone_id                = aws_alb.application_alb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "aaaa_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "AAAA"

  alias {
    name                   = aws_alb.application_alb.dns_name
    zone_id                = aws_alb.application_alb.zone_id
    evaluate_target_health = true
  }
}
