  }
}

resource "aws_db_subnet_group" "example" {
  name       = "example-subnet-group"
  subnet_ids = [aws_subnet.example_subnet_1.id, aws_subnet.example_subnet_2.id]

  tags = {
    Name = "example-subnet-group"
  }
}

resource "aws_security_group" "example" {
  name        = "example-security-group"
  description = "Security group for RDS instance"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_assume_role" {
  name = "rds_assume_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "rds_profile" {
  name = "rds_profile"
  role = aws_iam_role.rds_assume_role.name
}

resource "aws_rds_cluster_instance" "example" {
  count = length(aws_subnet.example_subnet_1.id)

  cluster_identifier      = aws_rds_cluster.example.id
  engine                  = aws_rds_cluster.example.engine
  instance_class          = "db.t2.micro"
  db_subnet_group_name    = aws_db_subnet_group.example.name
  vpc_security_group_ids   = [aws_security_group.example.id]
  iam_database_authentication_enabled = true
  instance_profile         = aws_iam_instance_profile.rds_profile.name

  tags = {
    Name = "example-cluster-instance-${count.index + 1}"
  }
}

resource "aws_subnet" "example_subnet_1" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "example-subnet-1"
  }
}

resource "aws_subnet" "example_subnet_2" {
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"

  tags = {
    Name = "example-subnet-2"
  }
}
```

