 Description:
This Terraform configuration will provision a secure PostgreSQL database instance within an AWS VPC, utilizing AWS services such as RDS, subnets, KMS, and a custom parameter group for PostgreSQL settings. A security group will be created to manage access, and the database instance will be configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  vpc_id = "your_vpc_id"
  kms_key_alias = "alias/terraform-rds"
}

data "aws_vpc" "selected" {
  id = local.vpc_id
}

data "aws_kms_key" "selected" {
  alias = local.kms_key_alias
}

resource "aws_subnet" "subnet1" {
  vpc_id     = data.aws_vpc.selected.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_subnet" "subnet2" {
  vpc_id     = data.aws_vpc.selected.id
  cidr_block = "10.0.2.0/24"
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "terraform-rds-subnet-group"
  subnet_ids = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]
}

resource "aws_security_group" "rds_security_group" {
  name        = "terraform-rds-security-group"
  description = "Security group for RDS instances"
  vpc_id      = data.aws_vpc.selected.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "postgresql_cluster" {
  cluster_identifier      = "terraform-postgresql-cluster"
  engine                  = "postgres"
  engine_version          = "13.2"
  master_username         = "admin"
  master_password         = "Your_Strong_Password_Here"
  skip_final_snapshot     = true
  vpc_security_group_ids   = [aws_security_group.rds_security_group.id]
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  backup_window           = "03:00-06:00"
  maintenance_window      = "mon:00:00-mon:03:00"
  multi_az                = true
  storage_encrypted       = true
  kms_key_id              = data.aws_kms_key.selected.id

  tags = {
    Name = "Terraform PostgreSQL Cluster"
  }
}

resource "aws_rds_cluster_instance" "postgresql_instance" {
  count              = aws_rds_cluster.postgresql_cluster.instance_count
  cluster_identifier = aws_rds_cluster.postgresql_cluster.id
  instance_class     = "db.t3.small"
}

resource "aws_rds_cluster_parameter_group" "postgresql_parameter_group" {
  name        = "terraform-postgresql-parameter-group"
  family      = "postgres13"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "shared_buffers"
    value = "256MB"
  }
}

resource "aws_rds_cluster_instance" "postgresql_instance" {
  count              = aws_rds_cluster.postgresql_cluster.instance_count
  cluster_identifier = aws_rds_cluster.postgresql_cluster.id
  instance_class     = "db.t3.small"

  # Associate the cluster instance with the parameter group
  parameter_group_name = aws_rds_cluster_parameter_group.postgresql_parameter_group.name
}
```

Please replace `"Your_Strong_Password_Here"` with a strong password for the master_password variable. Also, replace `"your_vpc_id"` with the ID of your desired VPC.

This configuration is deployable with Terraform ~> 1.9.8 and hashicorp/aws ~> 5.75. It creates the necessary IAM roles as needed for RDS operations.

