 Description:
This Terraform configuration will provision a secure PostgreSQL database instance within an AWS VPC. It utilizes AWS services such as RDS, subnets, KMS, and creates a custom parameter group for PostgreSQL settings, a security group for access management, and a KMS key for encryption. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, instance class "db.t3.micro", and backup retention period 7.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  db_subnet_ids = [
    "subnet-0a1b2c3d4ef5",
    "subnet-6789abcdef012",
  ]
  kms_key_alias = "alias/terraform-rds-key"
}

data "aws_kms_key" "rds_key" {
  alias = local.kms_key_alias
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "terraform-rds-subnet-group"
  subnet_ids = local.db_subnet_ids
}

resource "aws_security_group" "rds_security_group" {
  name        = "terraform-rds-security-group"
  description = "Security group for RDS instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "terraform-rds-cluster"
  engine                  = "postgres"
  engine_version          = "13.2"
  availability_zones      = ["us-west-2a", "us-west-2b"]
  master_username         = "my_username"
  master_password         = "my_password"
  backup_retention_period = 7
  skip_final_snapshot     = true

  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  subnet_group_name      = aws_db_subnet_group.rds_subnet_group.name

  storage_encrypted       = true
  kms_key_id              = data.aws_kms_key.rds_key.arn

  tags = {
    Name = "terraform-rds-cluster"
  }
}

resource "aws_rds_cluster_instance" "main" {
  count = aws_rds_cluster.main.instance_count

  cluster_identifier      = aws_rds_cluster.main.id
  engine                  = aws_rds_cluster.main.engine
  engine_version          = aws_rds_cluster.main.engine_version
  instance_class          = "db.t3.micro"
  availability_zone       = elements(aws_rds_cluster.main.availability_zones, count.index)

  tags = {
    Name = "terraform-rds-cluster-instance-${count.index + 1}"
  }
}

resource "aws_rds_cluster_parameter_group" "main" {
  name        = "terraform-rds-cluster-parameter-group"
  family      = "postgres13"
  description = "Custom parameter group for PostgreSQL settings"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  parameter {
    name  = "shared_buffers"
    value = "256MB"
  }
}

resource "aws_rds_cluster_instance_parameter_group_association" "main" {
  count = aws_rds_cluster.main.instance_count

  db_cluster_instance_identifier = aws_rds_cluster_instance.main[count.index].id
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.main.name
}
```

