 Description:
This Terraform configuration will provision a secure PostgreSQL database instance within an AWS VPC, utilizing AWS services such as RDS, subnets, KMS for encryption, and a custom parameter group for PostgreSQL settings. A security group will be created to manage access, and the database instance will be configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. The database instance will be named "pgsql-instance" and will have a final snapshot identifier of "pgsnapshot".

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  db_subnet_ids = [
    "subnet-0a1b2c3d4ef5",
    "subnet-6789abcdef012",
    "subnet-3456ghijklmno"
  ]
  kms_key_alias = "alias/pgsql-kms-key"
}

variable "db_instance_identifier" {
  default = "pgsql-instance"
}

variable "db_engine_version" {
  default = "13.2"
}

variable "db_allocated_storage" {
  default = 20
}

variable "db_max_allocated_storage" {
  default = 50
}

variable "db_master_username" {
  type = string
}

variable "db_master_password" {
  type = string
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_db_subnet_group" "main" {
  name       = "main-subnet-group"
  subnet_ids = local.db_subnet_ids
}

resource "aws_kms_key" "main" {
  alias = local.kms_key_alias
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = var.db_instance_identifier
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  availability_zones      = ["us-west-2a", "us-west-2b"]
  master_username         = var.db_master_username
  master_password         = var.db_master_password
  backup_window           = "03:00-06:00"
  maintenance_window      = "mon:00:00-mon:03:00"
  db_subnet_group_name    = aws_db_subnet_group.main.name
  vpc_security_group_ids   = [aws_security_group.main.id]
  skip_final_snapshot     = false
  final_snapshot_identifier = "pgsnapshot"
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.main.arn
  backup_automated_window = "daily"
  backup_retention_period = 7

  tags = {
    Name = var.db_instance_identifier
  }
}

resource "aws_security_group" "main" {
  name_prefix = var.db_instance_identifier
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster_parameter_group" "main" {
  name        = "${var.db_instance_identifier}-pg-params"
  family      = "postgres13"

  parameters = {
    max_connections = "100"
    shared_buffers  = "128MB"
  }
}

resource "aws_rds_cluster_instance" "main" {
  count              = length(aws_rds_cluster.main.replicas)
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = "db.t3.small"
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version
  availability_zone  = elements(aws_rds_cluster.main.availability_zones, count.index + 1)

  tags = {
    Name = "${var.db_instance_identifier}-replica-${count.index + 1}"
  }
}
```

This configuration creates an AWS VPC, a DB subnet group, a KMS key, an RDS cluster with a multi-AZ deployment, a security group, and an RDS cluster parameter group. It also creates RDS cluster instances for the replicas. The database instance is encrypted using the specified KMS key, and a final snapshot is taken with the identifier "pgsnapshot". The configuration also includes variables for the database instance identifier, engine version, allocated storage, max allocated storage, master username, and master password.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region  = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"

  name = "main-vpc"
  cidr = "10.0.0.0/16"

  azs                  = data.aws_availability_zones.available.names
  public_subnets       = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

resource "aws_db_subnet_group" "db-subnet-group" {
  name       = "db-subnet-group"
  subnet_ids = module.vpc.public_subnets
}

resource "aws_security_group" "db-sg" {
  name = "db-sg"
  vpc_id = module.vpc.vpc_id
}

resource "aws_vpc_security_group_ingress_rule" "db-sg-ingress-rule" {
  from_port       = 5432
  to_port         = 5432
  ip_protocol     = "tcp"
  cidr_ipv4       = "0.0.0.0/0"
  security_group_id = aws_security_group.db-sg.id
}

resource "aws_vpc_security_group_egress_rule" "db-sg-egress-rule" {
  from_port       = 5432
  to_port         = 5432
  ip_protocol     = "tcp"
  cidr_ipv4       = "0.0.0.0/0"
  security_group_id = aws_security_group.db-sg.id
}

resource "aws_db_parameter_group" "postgre-param-group" {
  name   = "pgparamgrp15"
  family = "postgres15"

  parameter {
    name  = "password_encryption"
    value = "scram-sha-256"
  }

  parameter {
    name  = "rds.force_ssl"
    value = "0"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_kms_key" "rds-key" {
  description             = "kmsrds"
  deletion_window_in_days = 14
}

resource "aws_db_instance" "postgres" {
  identifier                      = "pg"
  skip_final_snapshot             = true
  allocated_storage               = 5
  backup_retention_period         = 7
  db_subnet_group_name            = aws_db_subnet_group.db-subnet-group.id
  parameter_group_name            = aws_db_parameter_group.postgre-param-group.name
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]
  engine                          = "postgres"
  engine_version                  = "15"
  instance_class                  = "db.t3.micro"
  db_name                         = "postgres" # Initial database name
  username                        = "myusername"
  password                        = "mypassword"
  vpc_security_group_ids          = [aws_security_group.db-sg.id]
  # Other security settings
  publicly_accessible             = true
  multi_az                        = true
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.rds-key.arn
  # Default daily backup window
  # https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_WorkingWithAutomatedBackups.html#USER_WorkingWithAutomatedBackups.BackupWindow
}

