This Terraform configuration will set up a PostgreSQL 15 instance on AWS RDS within specific public subnets for running Airbyte connector test cases. The RDS instance will be managed with minimal configuration for low maintenance.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_name" {
  default = "airbyte_test_db"
}

variable "db_username" {
  default = "airbyte_test_user"
}

variable "db_password" {
  sensitive = true
  default = "airbyte_test_password"
}

variable "vpc_id" {
  default = "vpc-1234567890abcdef0"
}

variable "subnet_ids" {
  type    = list(string)
  default = ["subnet-1234567890abcdef1", "subnet-1234567890abcdef2"]
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "airbyte_test_rds_subnet_group"
  subnet_ids = var.subnet_ids
}

resource "aws_iam_role" "rds_role" {
  name = "airbyte_test_rds_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_rds_cluster" "airbyte_test_cluster" {
  cluster_identifier      = var.db_name
  engine                  = "postgres"
  engine_version          = "15.1"
  master_username         = var.db_username
  master_password         = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.airbyte_test_rds_sg.id]

  skip_final_snapshot     = true

  tags = {
    Name = var.db_name
  }
}

resource "aws_security_group" "airbyte_test_rds_sg" {
  name_prefix = "airbyte_test_rds_sg"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_instance_profile" "rds_instance_profile" {
  name = "airbyte_test_rds_instance_profile"
  role = aws_iam_role.rds_role.name
}

resource "aws_iam_instance_profile_association" "rds_instance_profile_association" {
  instance_profile_id = aws_iam_instance_profile.rds_instance_profile.id
  roles               = [aws_rds_cluster.airbyte_test_cluster.master_username]
}
```

