  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "${local.private_subnet_azs[0]}"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "${local.private_subnet_azs[1]}"
}

resource "aws_security_group" "db_access" {
  name        = "db_access"
  description = "Security group for database access"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = "mysql-cluster"
  engine                  = "mysql"
  engine_version          = "8.0.27"
  master_username         = "admin"
  master_password         = var.db_password
  backup_window           = "03:00-06:00"
  preferred_backup_window = "03:00-06:00"
  skip_final_snapshot     = true

  vpc_security_group_ids = [aws_security_group.db_access.id]
  subnet_group_name      = aws_rds_subnet_group.subnet_group.name

  tags = {
    Name = "mysql-cluster"
  }
}

resource "aws_rds_subnet_group" "subnet_group" {
  name       = "subnet-group"
  subnet_ids = [aws_subnet.private_subnet_1.id, aws_subnet.private_subnet_2.id]

  tags = {
    Name = "subnet-group"
  }
}

output "database_endpoint" {
  value = aws_rds_cluster.mysql_cluster.endpoint
}
