LLM Output #0:
 **Description:**
This Terraform configuration sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also deploys a 500 GB 5.7 MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  private_subnet_azs = ["us-west-2a", "us-west-2b"]
  public_subnet_azs  = slice(local.private_subnet_azs, 0, 1)
  private_subnet_ids = []
  public_subnet_ids  = []
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_azs)

  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[local.private_subnet_azs[count.index]]
  vpc_id                  = aws_vpc.main.id
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${local.private_subnet_azs[count.index]}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_azs)

  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, local.public_subnet_azs[count.index] + length(local.private_subnet_azs))
  availability_zone       = data.aws_availability_zones.available.names[local.public_subnet_azs[count.index]]
  vpc_id                  = aws_vpc.main.id
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${local.public_subnet_azs[count.index]}"
  }

  lifecycle {
    create_before_destroy = true
  }
}

locals {
  private_subnet_ids = concat(aws_subnet.private.*.id, aws_subnet.public.*.id)
}

resource "aws_security_group" "db_access" {
  name        = "db-access"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "db-access"
  }
}

resource "aws_rds_cluster" "mysql" {
  cluster_identifier      = "mysql-cluster"
  engine                  = "mysql"
  engine_version          = "5.7"
  availability_zones      = local.private_subnet_azs
  master_username         = "admin"
  master_password         = "YourSecretPassword"
  backup_window           = "03:00-06:00"
  maintenance_window      = "mon:00:00-mon:03:00"
  skip_final_snapshot     = true
  vpc_security_group_ids   = [aws_security_group.db_access.id]
  subnet_group_name       = aws_db_subnet_group.subnet_group.name
  database_name           = "mydb"
  master_port             = 3306
  backup_retention_period = 0
  publicly_accessible     = true

  tags = {
    Name = "mysql-cluster"
  }
}

output "database_endpoint" {
  value = aws_rds_cluster.mysql.endpoint
}

resource "aws_db_subnet_group" "subnet_group" {
  name       = "subnet-group"
  subnet_ids = local.private_subnet_ids

  tags = {
    Name = "subnet-group"
  }
}
```

**Note:** Replace `YourSecretPassword` with a secure password for the RDS master user. This configuration assumes that you have the necessary AWS credentials configured in your environment.

