This Terraform configuration sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also deploys a 20GB PostgreSQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  private_subnet_azs = ["us-west-2a", "us-west-2b"]
  public_subnet_azs  = slice(local.private_subnet_azs, 0, 1)
  public_subnet_azs  = [local.public_subnet_azs[1], local.private_subnet_azs[1]]
}

variable "db_password" {
  default = "YourDatabasePassword"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnet_azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = elements(local.private_subnet_azs, count.index)[0]

  tags = {
    Name = "private-subnet-${elements(local.private_subnet_azs, count.index)}"
  }
}

resource "aws_subnet" "public" {
  count             = length(local.public_subnet_azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + length(local.private_subnet_azs))
  availability_zone = elements(local.public_subnet_azs, count.index)[0]

  tags = {
    Name = "public-subnet-${elements(local.public_subnet_azs, count.index)}"
  }
}

resource "aws_security_group" "db_access" {
  name        = "db-access-sg"
  description = "Security group for database access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "postgresql" {
  cluster_identifier      = "postgresql-cluster"
  engine                  = "postgres"
  engine_version          = "15.3"
  availability_zones      = local.public_subnet_azs
  master_username         = "postgres"
  master_password         = var.db_password
  backup_window           = "03:00-06:00"
  maintenance_window      = "mon:00:00-mon:03:00"
  db_subnet_group_name    = aws_db_subnet_group.subnet_group.name
  vpc_security_group_ids   = [aws_security_group.db_access.id]
  skip_final_snapshot      = true

  node_type = "db.t2.small"

  tags = {
    Name = "postgresql-cluster"
  }
}

resource "aws_db_subnet_group" "subnet_group" {
  name       = "subnet-group"
  subnet_ids = [for subnet in aws_subnet.public : subnet.id]

  tags = {
    Name = "subnet-group"
  }
}

output "db_endpoint" {
  value = aws_rds_cluster.postgresql.endpoint
}
```

