  tags = local.common_tags
}

resource "aws_rds_cluster_parameter_group" "aurora_parameter_group" {
  name        = "terraform-rds-aurora-parameter-group"
  family      = "aurora-mysql5.7"
  description = "Parameter group for RDS Aurora MySQL 5.7"

  parameter {
    name  = "rds.proxy.idle_client_timeout"
    value = "1800"
