}

resource "aws_rds_cluster_instance" "aurora_instance" {
  count = 2

  cluster_identifier      = aws_rds_cluster.aurora.id
  engine                  = aws_rds_cluster.aurora.engine
  engine_version          = aws_rds_cluster.aurora.engine_version
  instance_class          = "db.t3.small"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  db_subnet_group_name    = aws_rds_subnet_group.subnet_group.name
  publicly_accessible     = false

  tags = local.common_tags
}

resource "aws_rds_cluster_parameter_group" "aurora_parameter_group" {
  name        = "rds-aurora-parameter-group"
  family      = "aurora-mysql8.0"

  parameter {
    name  = "max_connections"
    value = "100"
  }

  tags = local.common_tags
}

resource "aws_rds_cluster_instance_parameter_group_association" "aurora_instance_parameter_group" {
  count = length(aws_rds_cluster_instance.aurora_instance)

  db_cluster_identifier = aws_rds_cluster.aurora.id
  db_instance_identifier = aws_rds_cluster_instance.aurora_instance[count.index].id
  parameter_group_name  = aws_rds_cluster_parameter_group.aurora_parameter_group.name
}

resource "aws_iam_role" "rds_proxy" {
