 Description: This Terraform configuration will create an AWS Lightsail instance with a managed MySQL database. It will also create an IAM role for the Lightsail instance to assume for accessing AWS resources.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lightsail_instance_name = "my-lightsail-instance"
  database_name           = "my-database"
  database_username       = "my-database-user"
  database_password       = "my-database-password"
}

data "aws_iam_policy_document" "lightsail_instance_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lightsail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "${local.lightsail_instance_name}-role"

  assume_role_policy = data.aws_iam_policy_document.lightsail_instance_assume_role.json
}

resource "aws_iam_instance_profile" "lightsail_instance_profile" {
  name = "${local.lightsail_instance_name}-profile"
  role = aws_iam_role.lightsail_instance_role.name
}

resource "aws_lightsail_instance" "main" {
  name              = local.lightsail_instance_name
  blueprint_id      = "wp-al2-xen-s-1vcpu-1.5gb-50gb-linux"
  bundle_id         = "al2.medium"
  region            = aws_region.us_west_2.name
  instance_plan_id  = "512mb"

  tags = {
    Name = local.lightsail_instance_name
  }

  availability_zone = "us-west-2a"

  user_data = filebase64("user-data.sh")

  key_pair_name = aws_key_pair.ssh_key.key_name

  blueprint_options {
    database_password = local.database_password
    database_username = local.database_username
    database_name     = local.database_name
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_key_pair" "ssh_key" {
  key_name   = "my-ssh-key"
  public_key = file("~/.ssh/id_rsa.pub")
}

data "aws_region" "us_west_2" {
  name = "us-west-2"
}
```

