  mysql_db_name           = "my-mysql-db"
  backup_start_time       = "16:00"
  backup_end_time         = "16:30"
  maintenance_start_time  = "17:00"
  maintenance_end_time    = "17:30"
  maintenance_day         = "TUESDAY"
}

resource "aws_lightsail_static_ip" "static_ip" {
  lightsail_blueprint_id = "ebs-optimized-linux-2-0-2-0"
}

resource "aws_lightsail_instance" "instance" {
  name              = local.lightsail_instance_name
  blueprint_id      = "ebs-optimized-linux-2-0-2-0"
  static_ip_name    = aws_lightsail_static_ip.static_ip.name
  region            = aws_region.us_west_2.name

  tags = {
    Name = local.lightsail_instance_name
  }
}

resource "aws_lightsail_database" "database" {
  instance_name = aws_lightsail_instance.instance.name
  engine        = "mysql"
  name          = local.mysql_db_name
  root_password = "my-secret-password"
}

resource "aws_lightsail_database_backup_policy" "backup_policy" {
  instance_name = aws_lightsail_instance.instance.name

  backup_days = 7
  start_time = local.backup_start_time
  end_time   = local.backup_end_time
}

resource "aws_lightsail_instance_action" "maintenance" {
  instance_name = aws_lightsail_instance.instance.name

  action_type = "REBOOT"

  schedule {
    days = [local.maintenance_day]
    start_time = local.maintenance_start_time
    end_time   = local.maintenance_end_time
  }
}
```

Please note that this configuration uses a hardcoded MySQL root password. In a production environment, it is recommended to use a secure method for storing and managing sensitive data such as passwords.

Also, this configuration does not include a VPC and subnet for the Lightsail instance. If you need to specify a VPC and subnet, you can create them using the `aws_vpc` and `aws_subnet` resources and then reference them in the `aws_lightsail_instance` resource.

 **Description:**
This Terraform configuration will create an AWS Lightsail instance with a PostgreSQL database. The Lightsail instance will be configured to automatically create a final snapshot of the database upon deletion.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lightsail_instance_name = "my-lightsail-instance"
  database_name           = "my-database"
  database_username       = "my-database-user"
  database_password       = "my-database-password"
}

data "aws_iam_policy_document" "lightsail_instance_policy" {
  statement {
    actions = ["lightsail:CreateSnapshot", "lightsail:DeleteSnapshot"]
    resources = [
      "arn:aws:lightsail:${data.aws_region.current.name}:*:snapshot/*"
    ]
  }
}

resource "aws_iam_instance_profile" "lightsail_instance_profile" {
  name = "${local.lightsail_instance_name}-instance-profile"
  role = aws_iam_role.lightsail_instance_role.name
}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "${local.lightsail_instance_name}-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_instance_policy_attachment" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = data.aws_iam_policy.lightsail_instance_policy.arn
}

data "aws_region" "current" {}

resource "aws_lightsail_instance" "example" {
  name         = local.lightsail_instance_name
  blueprint_id = "ebs:ubuntu-20-04:latest"
  bundle_id    = "ls-blp-1gb-1-0-0-2023030100"

  availability_zone = "us-west-2a"
  region            = data.aws_region.current.name

  tags = {
    Name = local.lightsail_instance_name
  }

  instance_profile = aws_iam_instance_profile.lightsail_instance_profile.name
}

resource "aws_lightsail_relational_database" "example" {
  instance_name = aws_lightsail_instance.example.name
  engine        = "postgresql"
  engine_version = "13.3"
  master_username = local.database_username
  master_password = local.database_password
  database_name = local.database_name

  snapshot_id = aws_lightsail_instance.example.snapshot_id

  allocation_tier = "db-compute-optimized"
  backup_days      = 7
  backup_window    = "03:00-06:00"

  tags = {
    Name = local.database_name
  }

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [snapshot_id]
  }
}

output "database_endpoint" {
  value = aws_lightsail_relational_database.example.endpoint
}
```

**Note:**
- Replace `my-lightsail-instance`, `my-database`, `my-database-user`, `my-database-password` with your desired values.
- This configuration uses the `aws` provider with the `us-west-2` region. You can change the region by modifying the `region` attribute in the `provider` block.
- The configuration creates an IAM instance profile and role to allow the Lightsail instance to create and delete database snapshots.
- The Lightsail instance is created with an Ubuntu 20.04 blueprint and a 1 GB RAM, 1 vCPU, 20 GB SSD storage bundle.
- The PostgreSQL database is created with the specified engine version, username, password, and database name. The snapshot ID is set to the Lightsail instance's snapshot ID.
- The `prevent_destroy` lifecycle setting ensures that the database is not deleted when the Terraform configuration is destroyed, and the `ignore_changes` setting allows the database to be recreated with a new snapshot ID if the Lightsail instance is updated.
- The output `database_endpoint` provides the endpoint for the created PostgreSQL database.

 **Description:**
This Terraform configuration will create an AWS Lightsail instance with a PostgreSQL database. The Lightsail instance will be launched in the specified region, and the PostgreSQL database will be configured to allow immediate application of changes. IAM roles will be created as needed to grant the necessary permissions.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lightsail_instance_name = "my-lightsail-instance"
  db_name                 = "my-db"
  db_username             = "my-db-user"
  db_password             = "my-db-password"
}

data "aws_iam_policy_document" "lightsail_instance_policy" {
  statement {
    actions = ["lightsail:CreateInstance", "lightsail:DeleteInstance", "lightsail:GetInstance", "lightsail:GetInstanceState", "lightsail:ListInstances"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "${local.lightsail_instance_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_instance_policy" {
  name        = "${local.lightsail_instance_name}-policy"
  path        = "/"
  description = "Policy for Lightsail instance"
  policy      = data.aws_iam_policy_document.lightsail_instance_policy.json
}

resource "aws_iam_role_policy_attachment" "lightsail_instance_policy_attachment" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = aws_iam_policy.lightsail_instance_policy.arn
}

resource "aws_lightsail_instance" "example" {
  name         = local.lightsail_instance_name
  blueprint_id = "aws_ubuntu_20_04_lts"
  bundle_id    = "ls-blp-1gb-1-0-0-2022030101"
  region       = var.region

  tags = {
    Name = local.lightsail_instance_name
  }
}

resource "aws_db_instance" "example" {
  engine           = "postgres"
  engine_version   = "13.2"
  instance_class   = "db.t2.micro"
  name             = local.db_name
  username         = local.db_username
  password         = local.db_password
  publicly_accessible = true
  vpc_security_group_ids = [aws_security_group.example.id]

  tags = {
    Name = local.db_name
  }
}

resource "aws_security_group" "example" {
  name        = "allow_all_traffic"
  description = "Allow all inbound traffic"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

output "db_endpoint" {
  value = aws_db_instance.example.endpoint
}
```

**Variables:**
- `region`: The AWS region where the resources will be created. Default value: `us-west-2`.

**Note:**
This configuration assumes that you have already set up your AWS credentials and configured the Terraform provider accordingly. It also assumes that you have the necessary permissions to create Lightsail instances, databases, and security groups in the specified region. The PostgreSQL database is publicly accessible for simplicity, but you should secure it in a production environment.

