This Terraform configuration will create an Amazon Lightsail instance and a storage unit, and link the storage unit with the Lightsail instance. The configuration includes IAM roles as needed and is deployable with Terraform v1.9.8 and AWS provider v5.75.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  instance_name = "my-lightsail-instance"
  storage_name  = "my-lightsail-storage"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "${local.instance_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "lightsail_instance_profile" {
  name = "${local.instance_name}-profile"
  role = aws_iam_role.lightsail_instance_role.name
}

resource "aws_lightsail_instance" "example" {
  name         = local.instance_name
  blueprint_id = "aws_ubuntu_20_04_1_x64"
  bundle_id    = "ls-blp-1a2-linux-sles-12-sp3-x64-2020-08-01"

  availability_zone = "us-west-2a"

  tags = {
    Name = local.instance_name
  }

  user_data = filebase64("user_data.sh")

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lightsail_static_ip" "example" {
  instance_name = aws_lightsail_instance.example.name
}

resource "aws_lightsail_instance_network_interface" "example" {
  instance_name = aws_lightsail_instance.example.name
  static_ip_name = aws_lightsail_static_ip.example.name
}

resource "aws_lightsail_storage_block" "example" {
  name          = local.storage_name
  instance_name = aws_lightsail_instance.example.name
  size          = 50
}

output "instance_public_ip" {
  value = aws_lightsail_instance.example.primary_network_interface.primary_ip_address
}
```

In this configuration, the `aws_lightsail_instance` resource creates an Amazon Lightsail instance with the specified blueprint and bundle. The `aws_lightsail_static_ip` resource assigns a static IP to the instance, and the `aws_lightsail_instance_network_interface` resource connects the static IP to the instance. The `aws_lightsail_storage_block` resource creates a storage unit for the instance. The `aws_iam_role` and `aws_iam_instance_profile` resources are used to grant the Lightsail instance permissions to access the storage unit. The user data script (`user_data.sh`) should be provided in the same directory as the Terraform configuration file.

