 **Description:**
This Terraform configuration will create an S3 Glacier vault and set up an AWS Data Lifecycle Manager policy for the vault. The vault will be encrypted at rest using a customer-managed key (CMK). An IAM role will be created to allow the Data Lifecycle Manager to manage the S3 Glacier vault.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  glacier_vault_name = "my-glacier-vault"
  data_lifecycle_policy_name = "my-data-lifecycle-policy"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "glacier_vault_key" {
  description             = "CMK for S3 Glacier Vault"
  deletion_window_in_days = 7
}

resource "aws_iam_role" "dlm_role" {
  name = "dlm_role_for_glacier_vault"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "data-lifecycle-manager.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "dlm_policy" {
  name = local.data_lifecycle_policy_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:AbortMultipartUpload",
          "glacier:CreateMultipartUpload",
          "glacier:CompleteMultipartUpload",
          "glacier:GetMultipartUploadPart",
          "glacier:ListMultipartUploadParts",
          "glacier:UploadPart"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.glacier_vault_key.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dlm_to_glacier_vault_role" {
  role       = aws_iam_role.dlm_role.name
  policy_arn = aws_iam_policy.dlm_policy.arn
}

resource "aws_s3_bucket" "glacier_vault" {
  bucket = local.glacier_vault_name
  acl    = "private"
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
        kms_master_key_id = aws_kms_key.glacier_vault_key.id
      }
    }
  }
}

resource "aws_glacier_vault" "glacier_vault" {
  account_id = data.aws_caller_identity.current.account_id
  bucket     = aws_s3_bucket.glacier_vault.id
  region     = aws_s3_bucket.glacier_vault.region
  kms_key_id = aws_kms_key.glacier_vault_key.arn
}

resource "aws_dlm_lifecycle_policy" "glacier_policy" {
  policy_id = local.data_lifecycle_policy_name

  rule {
    id = "move-to-glacier"

    filter {
      tag {
        key   = "stage"
        type  = "STRING_EQUALS"
        value = "archive"
      }
    }

    transition {
      storage_class = "GLACIER"
      days          = 30
    }
  }
}

resource "aws_dlm_lifecycle_policy_description" "glacier_policy_description" {
  lifecycle_policy_id = aws_dlm_lifecycle_policy.glacier_policy.id
  description = "Data Lifecycle Policy for Glacier Vault"
}

resource "aws_dlm_lifecycle_policy_schedule" "glacier_policy_schedule" {
  lifecycle_policy_id = aws_dlm_lifecycle_policy.glacier_policy.id
  schedule_expression = "cron(0 0 * * ? *)"
}

resource "aws_dlm_lifecycle_policy_target" "glacier_policy_target" {
  lifecycle_policy_id = aws_dlm_lifecycle_policy.glacier_policy.id
  target_id          = aws_s3_bucket.glacier_vault.id
}
```

This configuration creates an S3 Glacier vault, sets up an AWS Data Lifecycle Manager policy for the vault, and attaches the policy to an IAM role that allows the Data Lifecycle Manager to manage the S3 Glacier vault. The vault is encrypted at rest using a customer-managed key (CMK). The Data Lifecycle Manager policy moves objects with the "archive" tag to the Glacier storage class after 30 days. The policy is scheduled to run every day at midnight.

