```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  glacier_vault_name = "my-glacier-vault"
}

resource "aws_s3_bucket" "glacier_vault" {
  bucket = local.glacier_vault_name
  acl    = "private"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_glacier_vault" "glacier_vault" {
  account_id = aws_caller_identity.current.account_id
  bucket     = aws_s3_bucket.glacier_vault.id
}

resource "aws_s3_bucket_policy" "glacier_vault_policy" {
  bucket = aws_s3_bucket.glacier_vault.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action    = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.glacier_vault.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = "vpc-12345678"
          }
        }
      }
    ]
  })
}
```

In this configuration, an S3 bucket is created and converted into a Glacier vault. An S3 bucket policy is also defined to allow access to the vault from a specific VPC (vpc-12345678). Make sure to replace the VPC ID with the appropriate value for your environment.

