}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = "${aws_region}a" # Replace with the desired availability zone
}

resource "aws_security_group" "alb_security_group" {
  name        = "alb_security_group"
  description = "Security group for the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "alb" {
  name            = "alb"
  internal        = false
  security_groups = [aws_security_group.alb_security_group.id]
  subnets         = [aws_subnet.subnet[0].id, aws_subnet.subnet[1].id]
}

resource "aws_alb_target_group" "target_group" {
  name     = "target_group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_launch_configuration" "launch_config" {
  name_prefix          = "launch_config"
  image_id             = "ami-0c94855ba95c574c8" # Replace with the desired AMI ID
  instance_type        = "t2.micro"
  security_groups      = [aws_security_group.alb_security_group.id]
  key_name             = "your_key_pair_name" # Replace with the name of your key pair
  user_data            = <<-EOF
                          #!/bin/bash
                          yum update -y
                          yum install httpd -y
                          systemctl start httpd
                          systemctl enable httpd
                          EOF
}

resource "aws_autoscaling_group" "asg" {
  name                 = "asg"
  launch_configuration = aws_launch_configuration.launch_config.name
  vpc_zone_identifier  = [aws_subnet.subnet[0].id, aws_subnet.subnet[1].id]

  min_size            = 2
  max_size            = 10
}

resource "aws_alb_target_group_attachment" "target_group_attachment" {
  count = length(aws_autoscaling_group.asg.instances)

  target_group_arn = aws_alb_target_group.target_group.arn
  target_id        = aws_autoscaling_group.asg.instances[count.index].id
  port             = 80
}
