 Description: This Terraform configuration will create an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB) in the AWS region specified. The NLB will be associated with a target group containing EC2 instances launched from an Amazon Machine Image (AMI).

```hcl
provider "aws" {
  region = "us-west-2"
}

data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
  owners = ["099726089698"] # Canonical
}

data "aws_availability_zones" "available" {}

locals {
  instance_type = "t2.micro"
  key_name      = "my-key-pair"
  subnet_ids    = [for az in data.aws_availability_zones.available.names : cidrsubnet(aws_vpc.main.cidr_block, 4, data.aws_availability_zones.available.names.index(az) + 1)]
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  count = length(local.subnet_ids)
  cidr_block = local.subnet_ids[count.index]
  vpc_id     = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "alb_sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "nlb_sg" {
  name        = "nlb_sg"
  description = "Security group for NLB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "my-key-pair" {
  key_name   = local.key_name
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_instance" "ec2" {
  count = 2

  ami           = data.aws_ami.ubuntu.id
  instance_type = local.instance_type
  key_name      = local.key_name
  subnet_id     = element(local.subnet_ids, count.index)
  security_groups = [aws_security_group.nlb_sg.id]

  user_data = <<-EOF
              #!/bin/bash
              sudo apt-get update -y
              sudo apt-get install -y nginx
              sudo systemctl start nginx
              sudo systemctl enable nginx
              EOF

  tags = {
    Name = "ec2-instance-${count.index + 1}"
  }
}

resource "aws_alb" "alb" {
  name            = "alb"
  internal        = false
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = local.subnet_ids

  tags = {
    Name = "alb"
  }
}

resource "aws_alb_target_group" "tg" {
  name     = "tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    unhealthy_threshold = 2
  }
}

resource "aws_alb_listener" "listener" {
  load_balancer_arn = aws_alb.alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.tg.arn
  }
}

resource "aws_nlb" "nlb" {
  name            = "nlb"
  internal        = false
  subnets         = local.subnet_ids
  security_groups = [aws_security_group.nlb_sg.id]

  tags = {
    Name = "nlb"
  }
}

resource "aws_nlb_target_group" "nlb_tg" {
  name     = "nlb_tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    port     = "80"
    protocol = "HTTP"
  }
}

resource "aws_autoscaling_group" "asg" {
  name                 = "asg"
  launch_configuration = aws_launch_configuration.lc.name
  vpc_zone_identifier  = local.subnet_ids

  min_size            = 2
  max_size            = 2
  desired_capacity    = 2

  tags = {
    Name = "asg"
  }
}

resource "aws_launch_configuration" "lc" {
  name          = "lc"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = local.instance_type
  key_name      = local.key_name
  security_groups = [aws_security_group.nlb_sg.id]

  user_data = <<-EOF
              #!/bin/bash
              sudo apt-get update -y
              sudo apt-get install -y nginx
              sudo systemctl start nginx
              sudo systemctl enable nginx
              EOF
}

resource "aws_autoscaling_attachment" "asg_nlb" {
  autoscaling_group_name = aws_autoscaling_group.asg.name
  lb_target_group_arn   = aws_nlb_target_group.nlb_tg.arn
}

resource "aws_alb_target_group_attachment" "alb_tg_attachment" {
  count = length(aws_instance.ec2)
  target_group_arn = aws_alb_target_group.tg.arn
  target_id        = aws_instance.ec2[count.index].id
  port             = 80
}
```

This configuration creates an Amazon Virtual Private Cloud (VPC), subnets, security groups, key pair, EC2 instances, an Application Load Balancer (ALB), a Network Load Balancer (NLB), target groups for both ALB and NLB, and sets up autoscaling for the EC2 instances. The ALB forwards traffic to the NLB, which distributes the traffic to the EC2 instances.

