 Description: This Terraform configuration will create an AWS Application Load Balancer (ALB) with a redirect action. The ALB will be configured to listen on a specific port and route traffic to a target group. The redirect action will redirect HTTP traffic to HTTPS.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  alb_name = "my-alb"
  target_group_name = "${local.alb_name}-tg"
  listener_name = "${local.alb_name}-listener"
  redirect_action_name = "${local.alb_name}-redirect-action"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count = 3
  cidr_block = "10.0.${count.index}.0/24"
  vpc_id = aws_vpc.main.id
}

resource "aws_security_group" "alb_sg" {
  name_prefix = local.alb_name
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "alb" {
  name            = local.alb_name
  internal        = false
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = aws_subnet.subnet.*.id

  listener {
    action_mapping {
      default = "redirect"
    }

    action {
      type             = "redirect"
      redirect {
        port        = "443"
        protocol    = "HTTPS"
        status_code = "HTTP_301"
      }
    }

    protocol = "HTTP"
    port     = "80"
  }

  listener {
    action {
      type             = "forward"
      target_group_arn = aws_alb_target_group.tg.arn
    }

    protocol = "HTTPS"
    port     = "443"
  }
}

resource "aws_alb_target_group" "tg" {
  name     = local.target_group_name
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
}

resource "aws_alb_target_group_attachment" "tg_attachment" {
  count = 3

  target_group_arn = aws_alb_target_group.tg.arn
  target_id        = aws_instance.web_server.id[count.index]
  port             = 80
}

resource "aws_instance" "web_server" {
  count = 3

  ami           = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t2.micro"

  subnet_id = aws_subnet.subnet.id[count.index]

  tags = {
    Name = "${local.alb_name}-web-server-${count.index}"
  }
}
```

This configuration creates a VPC, subnets, a security group for the ALB, an Application Load Balancer, a target group, and three EC2 instances. The ALB is configured to listen on port 80 for HTTP traffic and redirect it to port 443 for HTTPS traffic. The ALB also forwards traffic to the target group, which consists of the three EC2 instances.

