 In this example, we will create an AWS Application Load Balancer (ALB) with a fixed-response action. The ALB will be configured to respond with a custom message when a request is made.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  custom_response = {
    content_type = "text/plain"
    message_body  = "Hello, World!"
    status_code   = 200
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count = 2

  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.${count.index + 1}.0/24"
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
}

resource "aws_route_table_association" "subnet_association" {
  count = length(aws_subnet.subnet)

  subnet_id      = aws_subnet.subnet[count.index].id
  route_table_id = aws_route_table.route_table.id
}

resource "aws_security_group" "alb_security_group" {
  name        = "alb_security_group"
  description = "Security group for the Application Load Balancer"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "alb" {
  name            = "alb"
  internal        = false
  security_groups = [aws_security_group.alb_security_group.id]
  subnets         = aws_subnet.subnet.*.id

  tags = {
    Name = "alb"
  }
}

resource "aws_alb_target_group" "target_group" {
  name     = "target_group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_alb_listener" "listener" {
  load_balancer_arn = aws_alb.alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = local.custom_response.content_type
      message_body  = local.custom_response.message_body
      status_code   = local.custom_response.status_code
    }
  }
}

resource "aws_alb_target_group_attachment" "target_group_attachment" {
  target_group_arn = aws_alb_target_group.target_group.arn
  target_id        = aws_instance.example.id
  port             = 80
}
```

In this configuration, we first set up the AWS provider and define a custom response for the fixed-response action. We then create a VPC, subnets, an internet gateway, and a route table for network connectivity. After that, we create a security group for the ALB and an ALB itself.

We also create an ALB target group, an ALB listener, and attach the target group to an instance (assuming you have an instance with the ID `aws_instance.example.id` defined elsewhere in your configuration). The ALB listener is configured to use the fixed-response action with the custom response we defined earlier.

