 Description: This Terraform configuration will create an Amazon Web Services (AWS) Application Load Balancer (ALB) with an authenticated Cognito user pool. The ALB will be configured to call a specific Lambda function after successful authentication.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  cognito_user_pool_id = "your_cognito_user_pool_id"
  cognito_client_id    = "your_cognito_client_id"
}

data "aws_iam_policy_document" "alb_policy" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    effect  = "Allow"

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [local.cognito_user_pool_id]
    }

    principal {
      type = "Federated"
      uri  = "arn:aws:identitypools:us-west-2:123456789012:oidc-provider/9876543210"
    }
  }
}

resource "aws_iam_role" "alb_role" {
  name = "alb_role"

  assume_role_policy = data.aws_iam_policy_document.alb_policy.json
}

resource "aws_iam_policy" "alb_policy" {
  name = "alb_policy"

  path   = "/"
  policy = <<EOF
{
    "Version": "2012-10-17",
    "Statement": [
        {
            "Effect": "Allow",
            "Action": "lambda:InvokeFunction",
            "Resource": "arn:aws:lambda:us-west-2:123456789012:function:your_lambda_function"
        }
    ]
}
EOF
}

resource "aws_iam_role_policy_attachment" "alb_to_alb_role" {
  role       = aws_iam_role.alb_role.name
  policy_arn = aws_iam_policy.alb_policy.arn
}

resource "aws_alb" "example" {
  name            = "example-alb"
  internal        = false
  security_groups = [aws_security_group.example.id]
  subnets         = [aws_subnet.example_subnet_1.id, aws_subnet.example_subnet_2.id]

  tags = {
    Name = "example-alb"
  }
}

resource "aws_alb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id

  health_check {
    path                = "/health"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_alb_listener" "example" {
  load_balancer_arn = aws_alb.example.arn
  port              = "443"
  protocol          = "HTTPS"
  certificate_arn   = "arn:aws:acm:us-west-2:123456789012:certificate/your_acm_certificate_arn"

  default_action {
    type             = "authenticate-cognito"
    authenticate_cognito {
      user_pool_arn = local.cognito_user_pool_id
      user_pool_client_id = local.cognito_client_id
      session_cookie_name = "session-cookie-name"
      remember = "remember-me-duration"
    }

    target_group_arn = aws_alb_target_group.example.arn
  }
}
