LLM Output #0:
 **Description:**
This Terraform configuration will create an AWS Gateway Load Balancer with a target group and a listener. The load balancer will be configured to use HTTPS and will be associated with a security group for network access control. An IAM role will be created for the load balancer to assume for tasks such as scaling and health checks.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  lb_name = "my-gateway-load-balancer"
}

data "aws_iam_policy_document" "lb_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticloadbalancing.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lb" {
  name               = "${local.lb_name}-role"
  assume_role_policy = data.aws_iam_policy_document.lb_assume_role.json
}

resource "aws_iam_policy" "lb" {
  name   = "${local.lb_name}-policy"
  path   = "/"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:CreateLoadBalancerListeners",
          "elasticloadbalancing:CreateLoadBalancerTargetGroup",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancerListeners",
          "elasticloadbalancing:DeleteLoadBalancerTargetGroup",
          "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeLoadBalancerPolicies",
          "elasticloadbalancing:DescribeLoadBalancerTags",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
          "elasticloadbalancing:SetWebACL",
          "elasticloadbalancing:TestSecurityGroup"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lb" {
  role       = aws_iam_role.lb.name
  policy_arn = aws_iam_policy.lb.arn
}

resource "aws_security_group" "lb" {
  name        = "${local.lb_name}-sg"
  description = "Security group for the Gateway Load Balancer"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "gateway" {
  name            = local.lb_name
  internal        = false
  security_groups = [aws_security_group.lb.id]
  subnets         = data.aws_subnets.default.ids

  tags = {
    Name = local.lb_name
  }
}

resource "aws_alb_target_group" "gateway" {
  name     = "${local.lb_name}-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = data.aws_vpc.default.id

  health_check {
    path                = "/health"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_alb_listener" "gateway" {
  load_balancer_arn = aws_alb.gateway.arn
  port              = "443"
  protocol          = "HTTPS"
  certificate_arn   = data.aws_acm_certificate.example.arn
  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.gateway.arn
  }
}
```

**Note:**
- Replace `data.aws_acm_certificate.example.arn` with the ARN of your ACM certificate.
- This configuration assumes that you have a default VPC and subnets in the specified region. If not, you will need to create them or modify the configuration accordingly.
- The `data.aws_subnets.default` data source is used to get the default subnets in the current region. If you want to use specific subnets, you can replace the `subnets` attribute in the `aws_alb` resource with your desired subnet IDs.

