LLM Output #0:
 In this example, we will create an AWS Elastic Load Balancer (ELB) with a target group using Terraform. The ELB will be of type Application Load Balancer (ALB) and will be configured to listen on HTTP and HTTPS traffic.

Here is the Terraform HCL configuration for the given instruction:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count = 3
  cidr_block = "${cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)}"
  vpc_id     = aws_vpc.main.id
  tags       = local.common_tags
}

resource "aws_security_group" "allow_http_traffic" {
  name        = "allow_http_traffic"
  description = "Allow HTTP inbound traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "example" {
  name            = "example-alb"
  internal        = false
  security_groups = [aws_security_group.allow_http_traffic.id]
  subnets         = [aws_subnet.subnet[0].id, aws_subnet.subnet[1].id, aws_subnet.subnet[2].id]

  tags = local.common_tags
}

resource "aws_alb_target_group" "example" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    interval            = 30
    timeout             = 5
    unhealthy_threshold = 2
  }
}

resource "aws_alb_target_group_attachment" "example" {
  count = 3

  target_group_arn = aws_alb_target_group.example.arn
  target_id        = aws_instance.example[count.index].id
  port             = 80
}

resource "aws_instance" "example" {
  count = 3

  ami           = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI (HVM), SSD Volume Type - US West Oregon
  instance_type = "t2.micro"
  key_name      = "your-key-pair-name"
  subnet_id     = aws_subnet.subnet[count.index].id

  tags = local.common_tags
}
```

This configuration creates an AWS VPC, subnets, a security group, an Application Load Balancer (ALB), a target group, and three EC2 instances. The ALB is configured to listen on HTTP traffic and the target group is associated with the EC2 instances. The configuration also includes common tags for easier management.

Please replace `"ami-0c94855ba95c574c8"` with the appropriate Amazon Linux 2 AMI ID for your desired region and `"your-key-pair-name"` with the name of your existing key pair.

Before running the Terraform configuration, make sure to initialize the Terraform working directory:

```sh
terraform init
```

Then, apply the configuration:

```sh
terraform apply
```

