This Terraform configuration will create an Amazon Web Services (AWS) Application Load Balancer (ALB) with a Lambda function as the target. The Lambda function will be invoked for each incoming request to the load balancer.

```hcl
provider "aws" {
  region = "us-west-2"
  version = "~> 5.75"
}

locals {
  lambda_function_name = "my-lambda-function"
}

data "aws_iam_policy_document" "lambda_exec" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.lambda_function_name}-exec"
  assume_role_policy = jsonencode(data.aws_iam_policy_document.lambda_exec.json)
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "lambda_function.py"
  output_path = "lambda_function_payload.zip"
}

resource "aws_lambda_function" "lambda_function" {
  filename      = data.archive_file.lambda_zip.output_path
  function_name = local.lambda_function_name
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.8"
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
}

resource "aws_iam_role_policy_attachment" "lambda_to_alb" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_alb" "alb" {
  name            = "my-alb"
  internal        = false
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = data.aws_subnets.default.ids
}

resource "aws_alb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.vpc.id
}

resource "aws_alb_listener" "listener" {
  load_balancer_arn = aws_alb.alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.target_group.arn
  }
}

resource "aws_alb_target_group_attachment" "attachment" {
  target_group_arn = aws_alb_target_group.target_group.arn
  target_id        = aws_lambda_function.lambda_function.id
  port             = 80
}
```

In this configuration, we first define the AWS provider and set the region. We then create an IAM role for the Lambda function to execute with. The Lambda function is defined using a Python script, which is archived and uploaded to AWS. The IAM role for the Lambda function is attached to the AWS Lambda Basic Execution Role policy.

Next, we create an Application Load Balancer (ALB) with the specified name, security group, and subnets. We then create a target group for the ALB and configure a listener to forward incoming requests to the target group. Finally, we attach the Lambda function to the target group.

