 Description: This Terraform configuration will create an Application Load Balancer (ALB) with a target group in the specified AWS region. The ALB will be configured with a listener and security groups for network access.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  alb_name = "example-alb"
  target_group_name = "${local.alb_name}-target-group"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_security_group" "alb_sg" {
  name        = "${local.alb_name}-sg"
  description = "Security group for the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb" "main" {
  name            = local.alb_name
  security_groups = [aws_security_group.alb_sg.id]
  subnets         = aws_subnet.default.*.id

  tags = {
    Name = local.alb_name
  }
}

resource "aws_alb_target_group" "main" {
  name     = local.target_group_name
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    interval            = 30
    timeout             = 5
    unhealthy_threshold = 2
  }
}

resource "aws_alb_listener" "main" {
  load_balancer_arn = aws_alb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.main.arn
  }
}
```

This configuration assumes that you have already created default subnets in the specified region. If not, you can create them using the `aws_subnet` resource. Additionally, you may need to create EC2 instances or other resources to serve as targets for the ALB target group.

