LLM Output #0:
 Description: This Terraform configuration will create an Amazon Web Services (AWS) Application Load Balancer (ALB) with a target group. The ALB will be configured to listen on HTTP and HTTPS protocols, and the target group will contain EC2 instances.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  common_tags = {
    Terraform = "true"
    Environment = "dev"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private_subnet" {
  count = 3

  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "private-subnet-${count.index + 1}"
  })
}

resource "aws_security_group" "alb_security_group" {
  name        = "alb_security_group"
  description = "Security group for the application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "deployer" {
  key_name   = "deployer"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_launch_configuration" "web" {
  name_prefix          = "web-"
  image_id             = "ami-0c94855ba95c574c8" # Amazon Linux 2 AMI ID
  instance_type        = "t2.micro"
  key_name             = aws_key_pair.deployer.key_name
  security_groups      = [aws_security_group.alb_security_group.id]
  user_data            = filebase64("userdata.sh")

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "web" {
  name                 = aws_launch_configuration.web.name_prefix
  launch_configuration = aws_launch_configuration.web.name
  vpc_zone_identifier  = [aws_subnet.private_subnet.*.id]

  min_size            = 2
  max_size            = 10
  desired_capacity    = 2

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_alb" "application" {
  name            = "application-alb"
  internal        = false
  security_groups = [aws_security_group.alb_security_group.id]
  subnets         = aws_subnet.private_subnet.*.id

  tags = merge(local.common_tags, {
    Name = "application-alb"
  })
}

resource "aws_alb_target_group" "web" {
  name     = "web-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_alb_target_group_attachment" "web" {
  count = aws_autoscaling_group.web.desired_capacity

  target_group_arn = aws_alb_target_group.web.arn
  target_id        = aws_autoscaling_group.web.id
  port             = 80
}

resource "aws_alb_listener" "http" {
  load_balancer_arn = aws_alb.application.id
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.web.arn
  }
}

resource "aws_alb_listener" "https" {
