Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  rds_db_subnet_group_name = "rds-subnet-group"
  rds_security_group_name  = "rds-security-group"
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count = length(data.aws_availability_zones.available.names)

  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
  vpc_id = aws_vpc.main.id
}

resource "aws_db_subnet_group" "subnet_group" {
  name = local.rds_db_subnet_group_name
  subnet_ids = [aws_subnet.subnet[0].id, aws_subnet.subnet[1].id]
}

resource "aws_security_group" "security_group" {
  name        = local.rds_security_group_name
  description = "RDS security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "rds_profile" {
  name = "rds-profile"
  role = aws_iam_role.rds_role.name
}

resource "aws_rds_cluster" "cluster" {
  cluster_identifier = "my-rds-cluster"
  engine = "postgres"
  engine_version = "13.2"
  availability_zones = [data.aws_availability_zones.available.names[0], data.aws_availability_zones.available.names[1]]
  database_name = "mydb"
  master_username = "myuser"
  master_password = "mypassword"
  vpc_security_group_ids = [aws_security_group.security_group.id]
  db_subnet_group_name = local.rds_db_subnet_group_name
  skip_final_snapshot = true

  tags = {
    Name = "My RDS Cluster"
  }
}

resource "aws_rds_cluster_instance" "cluster_instance" {
  count = length(aws_rds_cluster.cluster.replicas)

  cluster_identifier = aws_rds_cluster.cluster.id
  instance_class = "db.t2.small"
  engine = aws_rds_cluster.cluster.engine
  engine_version = aws_rds_cluster.cluster.engine_version
  availability_zone = element(aws_rds_cluster.cluster.availability_zones, count.index)
  db_subnet_group_name = local.rds_db_subnet_group_name
  publicly_accessible = true
  iam_database_authentication_enabled = true
  apply_immediately = true

  tags = {
    Name = "My RDS Cluster Instance"
  }
}
```

This configuration creates a VPC, subnets, a DB subnet group, a security group, an IAM role, an IAM instance profile, and an RDS cluster with replicas in two availability zones. The RDS cluster instance assumes the IAM role for necessary AWS actions. The RDS cluster and instances are publicly accessible for simplicity, but you should secure them in a production environment.

