```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  db_name  = "mydb"
  username = "myusername"
  password = "mypassword"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "rds_access" {
  name = "rds_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_rds_db_instance" "default" {
  allocated_storage      = 20
  storage_type           = "gp2"
  engine                 = "sqlserver-ex"
  engine_version         = "15.00.2000.1"
  instance_class         = "db.t2.micro"
  name                   = local.db_name
  username               = local.username
  password               = local.password
  parameter_group_name   = "default.sqlserver-ex-15.0"
  skip_final_snapshot    = true
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  publicly_accessible    = false

  tags = {
    Name = local.db_name
  }
}

resource "aws_security_group" "rds_sg" {
  name_prefix = "rds_sg"

  ingress {
    from_port   = 1433
    to_port     = 1433
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role_policy_attachment" "rds_access_policy" {
  role       = aws_iam_role.rds_access.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
}

output "db_endpoint" {
  value = aws_rds_db_instance.default.endpoint
}
```

In this configuration, we create an RDS SQL Database instance with the specified parameters, including an IAM role for network access. The security group allows inbound traffic on port 1433 from the VPC and outbound traffic to any IP. The output variable `db_endpoint` provides the endpoint for the created database instance.

