  region = "us-west-2"
}

variable "db_name" {
  default = "mydb"
}

variable "username" {
  default = "myuser"
}

variable "password" {
  default = "mypassword"
}

variable "allocated_storage" {
  default = 20
}

resource "aws_db_instance" "rds_instance" {
  engine = "mysql"
  instance_class = "db.t2.micro"
  name = var.db_name
  username = var.username
  password = var.password
  allocated_storage = var.allocated_storage
  skip_final_snapshot = true

  tags = {
    Name = "MyRDSInstance"
  }
}
```

This configuration creates an AWS MySQL RDS instance with the specified DB name, username, password, and allocated storage in the `us-west-2` region. The `skip_final_snapshot` attribute is set to `true` to avoid creating a final snapshot when the RDS instance is deleted. The RDS instance will be tagged with the name "MyRDSInstance".

