Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_password" {
  default = "YourDBPassword"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = "10.0.1.0/24"

  tags = {
    Name = "private"
  }
}

resource "aws_security_group" "mysql" {
  name        = "mysql"
  description = "Security group for MySQL instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.private.cidr_block]
  }
}

resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-subnet-group"
  subnet_ids = [aws_subnet.private.id]
}

resource "aws_db_instance" "mysql" {
  engine                  = "mysql"
  engine_version          = "5.7"
  instance_class          = "db.t2.micro"
  allocated_storage       = 20
  storage_type            = "gp2"
  db_subnet_group_name    = aws_db_subnet_group.mysql.name
  vpc_security_group_ids  = [aws_security_group.mysql.id]
  skip_final_snapshot     = true
  password                  = var.db_password
  username                  = "myuser"
  parameter_group_name = "default.mysql5.7"
  publicly_accessible = false
}
```

This Terraform configuration creates an AWS VPC, a private subnet, a security group, a DB subnet group, and an RDS MySQL instance with the specified parameters. The MySQL instance is not publicly accessible and skips the final snapshot.

