This Terraform configuration will create an AWS RDS instance with the gp3 storage type. It includes the necessary IAM roles and a valid provider configuration within the us-west-2 region.

Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  rds_password = "YourRDSPassword"
}

data "aws_caller_identity" "current" {}

resource "aws_iam_role" "rds_access" {
  name = "rds_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "rds_access_profile" {
  name = "rds_access_profile"
  role = aws_iam_role.rds_access.name
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds_subnet_group"
  subnet_ids = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_1" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_subnet" "subnet_2" {
  vpc_id     = aws_vpc.vpc.id
  cidr_block = "10.0.2.0/24"
}

resource "aws_security_group" "rds_security_group" {
  name        = "rds_security_group"
  description = "Security group for RDS instance"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "rds_cluster" {
  cluster_identifier      = "rds_cluster"
  engine                  = "mysql"
  engine_version          = "8.0.27"
  master_username         = "admin"
  master_password         = local.rds_password
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_security_group.id]
  skip_final_snapshot     = true

  storage_encrypted       = true
  kms_key_id              = aws_kms_key.rds_key.arn

  tags = {
    Name = "rds_cluster"
  }
}

resource "aws_rds_cluster_instance" "rds_cluster_instance" {
  count = length(aws_rds_cluster.rds_cluster.replicas)

  cluster_identifier      = aws_rds_cluster.rds_cluster.id
  instance_class          = "db.t3.small"
  engine                  = aws_rds_cluster.rds_cluster.engine
  engine_version          = aws_rds_cluster.rds_cluster.engine_version
  identifier              = "${aws_rds_cluster.rds_cluster.cluster_identifier}-${count.index + 1}"
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_security_group.id]
  availability_zone       = element(aws_subnet.subnet_1.availability_zones, count.index)
  publicly_accessible     = true

  tags = {
    Name = "${aws_rds_cluster.rds_cluster.cluster_identifier}-${count.index + 1}"
  }
}

resource "aws_kms_key" "rds_key" {
  description             = "RDS KMS key"
  deletion_window_in_days = 7
}
```

Please replace `YourRDSPassword` with a secure password for your RDS instance. This configuration creates a VPC, two subnets, a security group, an RDS cluster, and RDS cluster instances within the specified region. It also creates an IAM role and instance profile for RDS access, a DB subnet group, and a KMS key for storage encryption.

