Terraform HCL:

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_engine" {
  default = "postgres"
}

variable "db_engine_version" {
  default = "13.2"
}

variable "instance_class" {
  default = "db.t3.micro"
}

