  instance_class          = var.instance_class
  allocated_storage       = var.allocated_storage
  storage_type            = "io1"
  engine                  = var.db_engine
  engine_version          = var.db_engine_version
  db_subnet_group_name    = aws_db_subnet_group.subnet_group.name
  vpc_security_group_ids   = [aws_security_group.rds_sg.id]
  identifier              = "rds-instance-${count.index}"

  tags = {
    Name = "rds-instance-${count.index}"
  }
}

resource "aws_security_group" "rds_sg" {
  name_prefix = "rds-sg"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

This configuration creates a VPC with two subnets, an RDS subnet group, an IAM role for RDS, an RDS cluster with a specified engine, version, and instance class, and RDS cluster instances in each subnet. It also creates a security group that allows incoming traffic on port 5432 (PostgreSQL default port).

