 **Description:**
This Terraform configuration will create an AWS RDS instance with storage autoscaling enabled. The RDS instance will be deployed in the `us-west-2` region, and it will use a MySQL engine. IAM roles will be created as needed.

**Terraform HCL:**

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  rds_subnet_group_name = "rds-subnet-group"
  rds_security_group_name = "rds-security-group"
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id     = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_db_subnet_group" "subnet_group" {
  name        = local.rds_subnet_group_name
  subnet_ids  = [aws_subnet.subnet[0].id, aws_subnet.subnet[1].id]
}

resource "aws_security_group" "security_group" {
  name        = local.rds_security_group_name
  description = "RDS security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_role" {
  name = "rds_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_rds_cluster" "cluster" {
  cluster_identifier = "my-rds-cluster"
  engine             = "mysql"
  master_username    = "my_username"
  master_password    = "my_password"
  skip_final_snapshot = true

  vpc_security_group_ids = [aws_security_group.security_group.id]
  subnet_group_name      = aws_db_subnet_group.subnet_group.name

  scaling_configuration {
    min_capacity = 2
    max_capacity = 10
  }

  tags = {
    Name = "My RDS Cluster"
  }
}
```

**Note:**
Replace `my_username` and `my_password` with your desired MySQL username and password. This configuration assumes that you have already set up your AWS credentials and configured the Terraform provider.

