 Title: Terraform Configuration for an AWS RDS Database with Managed Master Passwords via Secrets Manager and a default KMS Key

Below is a Terraform HCL configuration that creates an Amazon RDS database with managed master passwords via AWS Secrets Manager and a default KMS key. The configuration uses the `aws` provider and is compatible with Terraform v1.9.8 and the `hashicorp/aws` provider version `~> 5.75`.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  db_name      = "mydb"
  db_username  = "myusername"
  db_password  = "my_password"
  kms_key_alias = "alias/my-kms-key"
}

data "aws_caller_identity" "current" {}

resource "aws_secretsmanager_secret" "rds_password" {
  name = "${local.db_name}-password"
}

resource "aws_secretsmanager_secret_version" "rds_password" {
  secret_id     = aws_secretsmanager_secret.rds_password.id
  secret_string = local.db_password
}

resource "aws_kms_key" "default" {
  description             = "Default KMS key for RDS"
  deletion_window_in_days = 7
  alias                   = local.kms_key_alias
}

resource "aws_rds_db_instance" "default" {
  allocated_storage      = 20
  storage_type           = "gp2"
  engine                 = "postgres"
  engine_version         = "13.2"
  instance_class         = "db.t2.micro"
  db_name                = local.db_name
  username               = local.db_username
  password               = aws_secretsmanager_secret_version.rds_password.arn
  vpc_security_group_ids  = [aws_security_group.rds.id]
  skip_final_snapshot    = true
  publicly_accessible    = false
  kms_key_id             = aws_kms_key.default.arn

  tags = {
    Name = local.db_name
  }
}

resource "aws_security_group" "rds" {
  name_prefix = "rds-sg-"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
  default = true
}
```

This configuration creates an RDS instance with the specified parameters, uses a default KMS key, and stores the master password in AWS Secrets Manager. The security group allows incoming traffic on port 5432 from any IP address.

