 Instruction 1: Create an AWS RDS MySQL database with Managed Master Passwords via Secrets Manager and a specific KMS Key.

```hcl
provider "aws" {
  region = "us-west-2"
}

locals {
  kms_key_alias = "RDS-MySQL-DB-Key"
}

data "aws_kms_key" "rds_key" {
  key_id = aws_kms_key.rds_key.id
}

resource "aws_kms_key" "rds_key" {
  description             = "RDS MySQL DB KMS Key"
  deletion_window_in_days = 7
  policy                  = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action    = "Decrypt"
        Resource   = "*"
      },
      {
        Effect   = "Allow"
        Principal = aws_iam_role.rds_role.arn
        Action    = "KMS:*"
        Resource   = aws_kms_key.rds_key.arn
      }
    ]
  })
}

resource "aws_iam_role" "rds_role" {
  name = "RDS-MySQL-DB-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = "MySQL-Cluster"
  engine                  = "mysql"
  engine_version          = "8.0.27"
  availability_zones      = ["us-west-2a", "us-west-2b"]
  master_username         = "admin"
  master_password         = random_password.password.result
  database_name           = "mydb"
  vpc_security_group_ids   = [aws_security_group.rds_sg.id]
  backup_window           = "03:00-06:00"
  maintenance_window      = "mon:00:00-mon:03:00"
  skip_final_snapshot     = true
  kms_key_id              = data.aws_kms_key.rds_key.arn

  tags = {
    Name = "MySQL-Cluster"
  }
}

resource "aws_secretsmanager_secret" "rds_password" {
  name = "MySQL-Cluster-Password"
}

resource "aws_secretsmanager_secret_version" "rds_password_version" {
  secret_id     = aws_secretsmanager_secret.rds_password.id
  secret_string = jsonencode({
    password = aws_rds_cluster.mysql_cluster.master_password
  })
}

resource "aws_secretsmanager_secret_rotation_schedule" "rds_password_rotation" {
  secret_id     = aws_secretsmanager_secret.rds_password.id
  rotation_lambda_arn = aws_lambda_function.rotate_rds_password.arn
  rotation_rules = [
    {
      automatic_after_days = 30
    }
  ]
}

resource "aws_lambda_function" "rotate_rds_password" {
  function_name = "RotateRDSMySQLPassword"
  runtime       = "python3.8"
  handler       = "lambda_function.lambda_handler"
  role          = aws_iam_role.lambda_role.arn

  source_code_hash = base64sha256(filebase64("rotate_rds_password.zip"))

  environment {
    variables = {
      RDS_CLUSTER_ID = aws_rds_cluster.mysql_cluster.id
      RDS_SECRET_ARN  = aws_secretsmanager_secret.rds_password.arn
    }
  }
}

resource "aws_iam_role" "lambda_role" {
  name = "Lambda-RotateRDSMySQLPassword-Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name        = "Lambda-RotateRDSMySQLPassword-Policy"
  path        = "/"
  description = "Policy for Lambda function to rotate RDS MySQL password"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action    = "secretsmanager:GetSecretValue"
        Resource   = aws_secretsmanager_secret.rds_password.arn
      },
      {
        Effect   = "Allow"
        Action    = "secretsmanager:PutSecretValue"
        Resource   = aws_secretsmanager_secret.rds_password.arn
      },
      {
        Effect   = "Allow"
        Action    = "rds:DescribeDBClusters"
        Resource   = "*"
      },
      {
        Effect   = "Allow"
        Action    = "rds:ModifyDBCluster"
        Resource   = aws_rds_cluster.mysql_cluster.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_to_policy" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "random_password" "password" {
  length  = 16
  special = true
}

resource "aws_security_group" "rds_sg" {
  name        = "RDS-MySQL-DB-Security-Group"
  description = "Security group for RDS MySQL DB"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

data "aws_vpc" "default" {
  default = true
}
```

This Terraform configuration creates an AWS RDS MySQL database with Managed Master Passwords via Secrets Manager and a specific KMS Key. It also includes a Lambda function to rotate the RDS password every 30 days. The configuration includes all necessary IAM roles and policies. The region is set to `us-west-2`.

