  sensitive = true
  default = "mypassword"
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage      = 20
  storage_type           = "gp2"
  engine                 = "mysql"
  engine_version         = "5.7"
  instance_class         = "db.t2.micro"
  name                   = var.db_name
  username               = var.db_username
  password               = var.db_password
  parameter_group_name   = "default.mysql5.7"
  publicly_accessible    = false
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  backup_retention_period = 7
  skip_final_snapshot     = false
}

resource "aws_security_group" "rds_sg" {
  name_prefix = "rds-sg-"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_snapshot" "rds_snapshot" {
  db_instance_identifier = aws_db_instance.rds_instance.id
  snapshot_identifier    = "initial-snapshot"
}
```

In this configuration, we first define the AWS provider and set the region to `us-west-2`. We then define variables for the database name, username, and password, with default values provided.

Next, we create an RDS instance using the `aws_db_instance` resource. We specify the allocated storage, storage type, engine, engine version, instance class, name, username, password, parameter group name, publicly accessible flag, VPC security group ID, backup retention period, and skip final snapshot flag.

We also create a security group for the RDS instance using the `aws_security_group` resource, allowing incoming traffic on port 3306 from any IP address.

Finally, we create a snapshot of the RDS instance using the `aws_db_snapshot` resource, with a snapshot identifier of "initial-snapshot".

