  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [for account_id in local.efs_account_ids : "account_id"]
  }
}

resource "aws_iam_role" "efs_access_role" {
  name = "efs_access_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "efs_access_policy" {
  name = "efs_access_policy"
  path = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "efs:ClientMount",
          "efs:ClientUntagResource",
          "efs:ClientUpdateAccessPoint",
          "efs:ClientUpdateAvailability",
          "efs:ClientUpdateLifecycle",
          "efs:ClientUpdateMountTarget",
          "efs:ClientUpdateSecurityPerimeter",
          "efs:ClientUpdateTags",
          "efs:ClientUpdateTransitEncryption",
          "efs:ClientUpdateVolumeAttributes",
          "efs:ClientUpdateVolumeProgress",
          "efs:ClientUpdateVolumeTags",
          "efs:ClientUnmount",
          "efs:DescribeAccessPoints",
          "efs:DescribeFileSystems",
          "efs:DescribeMountTargets",
          "efs:DescribeSecurityPerimeters",
          "efs:DescribeTags",
          "efs:DescribeTransitEncryption",
          "efs:DescribeVolumeAttributes",
          "efs:DescribeVolumeProgress",
          "efs:DescribeVolumes",
          "efs:ListMountTargets",
          "efs:ListTags",
          "efs:ListTransitEncryption"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "efs_access_role_policy_attachment" {
  role       = aws_iam_role.efs_access_role.name
  policy_arn = aws_iam_policy.efs_access_policy.arn
}

output "efs_id" {
  value = aws_efs_file_system.main.id
}

output "efs_arn" {
  value = aws_efs_file_system.main.arn
}
```

This configuration creates an EFS file system with a system policy that allows access only from the specified AWS accounts. It also creates an IAM role and policy for EFS access, and attaches the policy to the role. The EFS mount targets are created in the specified VPC and subnets, and a security group is created to allow access to the EFS from the specified accounts. The output values are the EFS ID and ARN.

